export default "{\"schema\":\"ai-brain.inert-reference.v1\",\"trust\":\"untrusted_reference_only\",\"records\":[{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_payload.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"af284cc6c53ab3c05d97256a47949e94d6c01fd2bd9c94961ea1323ca34e888b\",\"content\":\"from unittest.mock import MagicMock\\n\\nfrom langflow.utils.payload import extract_input_variables, get_root_vertex\\n\\n\\nclass TestExtractInputVariables:\\n    \\\"\\\"\\\"Test cases for extract_input_variables function.\\\"\\\"\\\"\\n\\n    def test_extract_input_variables_prompt_type(self):\\n        \\\"\\\"\\\"Test extracting input variables from prompt type node.\\\"\\\"\\\"\\n        nodes = [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"input_variables\\\": {\\\"value\\\": []},\\n                            \\\"_type\\\": \\\"prompt\\\",\\n                            \\\"template\\\": {\\\"value\\\": \\\"Hello {name}, welcome to {place}!\\\"},\\n                        }\\n                    }\\n                }\\n            }\\n        ]\\n\\n        result = extract_input_variables(nodes)\\n\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"] == [\\\"name\\\", \\\"place\\\"]\\n\\n    def test_extract_input_variables_few_shot_type(self):\\n        \\\"\\\"\\\"Test extracting input variables from few_shot type node.\\\"\\\"\\\"\\n        nodes = [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"input_variables\\\": {\\\"value\\\": []},\\n                            \\\"_type\\\": \\\"few_shot\\\",\\n                            \\\"prefix\\\": {\\\"value\\\": \\\"This is {prefix_var}\\\"},\\n                            \\\"suffix\\\": {\\\"value\\\": \\\"And this is {suffix_var}\\\"},\\n                        }\\n                    }\\n                }\\n            }\\n        ]\\n\\n        result = extract_input_variables(nodes)\\n\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"] == [\\\"prefix_var\\\", \\\"suffix_var\\\"]\\n\\n    def test_extract_input_variables_other_type(self):\\n        \\\"\\\"\\\"Test extracting input variables from other type nodes.\\\"\\\"\\\"\\n        nodes = [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"input_variables\\\": {\\\"value\\\": []}, \\\"_type\\\": \\\"other\\\"}}}}]\\n\\n        result = extract_input_variables(nodes)\\n\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"] == []\\n\\n    def test_extract_input_variables_no_input_variables_field(self):\\n        \\\"\\\"\\\"Test handling nodes without input_variables field.\\\"\\\"\\\"\\n        nodes = [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"_type\\\": \\\"prompt\\\", \\\"template\\\": {\\\"value\\\": \\\"Hello {name}!\\\"}}}}}]\\n\\n        # Should not raise exception due to contextlib.suppress\\n        result = extract_input_variables(nodes)\\n\\n        assert result == nodes  # Should return unchanged\\n\\n    def test_extract_input_variables_multiple_nodes(self):\\n        \\\"\\\"\\\"Test extracting input variables from multiple nodes.\\\"\\\"\\\"\\n        nodes = [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"input_variables\\\": {\\\"value\\\": []},\\n                            \\\"_type\\\": \\\"prompt\\\",\\n                            \\\"template\\\": {\\\"value\\\": \\\"Hello {user}!\\\"},\\n                        }\\n                    }\\n                }\\n            },\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"input_variables\\\": {\\\"value\\\": []},\\n                            \\\"_type\\\": \\\"few_shot\\\",\\n                            \\\"prefix\\\": {\\\"value\\\": \\\"Prefix with {var1}\\\"},\\n                            \\\"suffix\\\": {\\\"value\\\": \\\"Suffix with {var2}\\\"},\\n                        }\\n                    }\\n                }\\n            },\\n        ]\\n\\n        result = extract_input_variables(nodes)\\n\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"] == [\\\"user\\\"]\\n        assert result[1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"] == [\\\"var1\\\", \\\"var2\\\"]\\n\\n    def test_extract_input_variables_nested_brackets(self):\\n        \\\"\\\"\\\"Test extracting variables with nested brackets.\\\"\\\"\\\"\\n        nodes = [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"input_variables\\\": {\\\"value\\\": []},\\n                            \\\"_type\\\": \\\"prompt\\\",\\n                            \\\"template\\\": {\\\"value\\\": \\\"Process {data.field} and {other_var}\\\"},\\n                        }\\n                    }\\n                }\\n            }\\n        ]\\n\\n        result = extract_input_variables(nodes)\\n\\n        assert \\\"data.field\\\" in result[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"]\\n        assert \\\"other_var\\\" in result[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"]\\n\\n    def test_extract_input_variables_no_variables(self):\\n        \\\"\\\"\\\"Test extracting from template with no variables.\\\"\\\"\\\"\\n        nodes = [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"input_variables\\\": {\\\"value\\\": []},\\n                            \\\"_type\\\": \\\"prompt\\\",\\n                            \\\"template\\\": {\\\"value\\\": \\\"Hello World! No variables here.\\\"},\\n                        }\\n                    }\\n                }\\n            }\\n        ]\\n\\n        result = extract_input_variables(nodes)\\n\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"] == []\\n\\n    def test_extract_input_variables_duplicate_variables(self):\\n        \\\"\\\"\\\"Test extracting duplicate variables.\\\"\\\"\\\"\\n        nodes = [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"input_variables\\\": {\\\"value\\\": []},\\n                            \\\"_type\\\": \\\"prompt\\\",\\n                            \\\"template\\\": {\\\"value\\\": \\\"Hello {name}, how are you {name}?\\\"},\\n                        }\\n                    }\\n                }\\n            }\\n        ]\\n\\n        result = extract_input_variables(nodes)\\n\\n        # Should contain duplicates as found by regex\\n        assert result[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"] == [\\\"name\\\", \\\"name\\\"]\\n\\n    def test_extract_input_variables_malformed_node(self):\\n        \\\"\\\"\\\"Test handling malformed node structure.\\\"\\\"\\\"\\n        nodes = [\\n            {\\\"malformed\\\": \\\"data\\\"},\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"input_variables\\\": {\\\"value\\\": []},\\n                            \\\"_type\\\": \\\"prompt\\\",\\n                            \\\"template\\\": {\\\"value\\\": \\\"Hello {valid}!\\\"},\\n                        }\\n                    }\\n                }\\n            },\\n        ]\\n\\n        # Should not raise exception and process valid nodes\\n        result = extract_input_variables(nodes)\\n\\n        assert len(result) == 2\\n        # Second node should be processed correctly\\n        assert result[1][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"] == [\\\"valid\\\"]\\n\\n    def test_extract_input_variables_empty_list(self):\\n        \\\"\\\"\\\"Test extracting from empty nodes list.\\\"\\\"\\\"\\n        nodes = []\\n\\n        result = extract_input_variables(nodes)\\n\\n        assert result == []\\n\\n    def test_extract_input_variables_special_characters(self):\\n        \\\"\\\"\\\"Test extracting variables with special characters.\\\"\\\"\\\"\\n        nodes = [\\n            {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"template\\\": {\\n                            \\\"input_variables\\\": {\\\"value\\\": []},\\n                            \\\"_type\\\": \\\"prompt\\\",\\n                            \\\"template\\\": {\\\"value\\\": \\\"Variables: {var_1}, {var-2}, {var.3}\\\"},\\n                        }\\n                    }\\n                }\\n            }\\n        ]\\n\\n        result = extract_input_variables(nodes)\\n\\n        variables = result[0][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"][\\\"input_variables\\\"][\\\"value\\\"]\\n        assert \\\"var_1\\\" in variables\\n        assert \\\"var-2\\\" in variables\\n        assert \\\"var.3\\\" in variables\\n\\n\\nclass TestGetRootVertex:\\n    \\\"\\\"\\\"Test cases for get_root_vertex function.\\\"\\\"\\\"\\n\\n    def test_get_root_vertex_single_root(self):\\n        \\\"\\\"\\\"Test getting root vertex when there's a single root.\\\"\\\"\\\"\\n        # Mock graph with edges\\n        mock_graph = MagicMock()\\n        mock_edge1 = MagicMock()\\n        mock_edge1.source_id = \\\"node1\\\"\\n        mock_edge2 = MagicMock()\\n        mock_edge2.source_id = \\\"node2\\\"\\n\\n        mock_graph.edges = [mock_edge1, mock_edge2]\\n\\n        # Mock vertices\\n        mock_vertex1 = MagicMock()\\n        mock_vertex1.id = \\\"root\\\"\\n        mock_vertex2 = MagicMock()\\n        mock_vertex2.id = \\\"node1\\\"\\n        mock_vertex3 = MagicMock()\\n        mock_vertex3.id = \\\"node2\\\"\\n\\n        mock_graph.vertices = [mock_vertex1, mock_vertex2, mock_vertex3]\\n\\n        # The root should be the vertex not in incoming_edges\\n        if callable(get_root_vertex):\\n            _ = get_root_vertex(mock_graph)\\n            # This test assumes get_root_vertex returns the vertex with no incoming edges\\n            # The actual implementation would need to be verified\\n\\n    def test_get_root_vertex_no_edges(self):\\n        \\\"\\\"\\\"Test getting root vertex when there are no edges.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.edges = []\\n\\n        mock_vertex = MagicMock()\\n        mock_vertex.id = \\\"only_vertex\\\"\\n        mock_graph.vertices = [mock_vertex]\\n\\n        # When there are no edges, any vertex could be considered root\\n        if callable(get_root_vertex):\\n            _ = get_root_vertex(mock_graph)\\n\\n    def test_get_root_vertex_multiple_roots(self):\\n        \\\"\\\"\\\"Test getting root vertex when there are multiple potential roots.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_edge = MagicMock()\\n        mock_edge.source_id = \\\"node2\\\"\\n\\n        mock_graph.edges = [mock_edge]\\n\\n        # Mock vertices - both node1 and node3 could be roots\\n        mock_vertex1 = MagicMock()\\n        mock_vertex1.id = \\\"node1\\\"\\n        mock_vertex2 = MagicMock()\\n        mock_vertex2.id = \\\"node2\\\"\\n        mock_vertex3 = MagicMock()\\n        mock_vertex3.id = \\\"node3\\\"\\n\\n        mock_graph.vertices = [mock_vertex1, mock_vertex2, mock_vertex3]\\n\\n        if callable(get_root_vertex):\\n            _ = get_root_vertex(mock_graph)\\n\\n    def test_get_root_vertex_empty_graph(self):\\n        \\\"\\\"\\\"Test getting root vertex from empty graph.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n        mock_graph.edges = []\\n        mock_graph.vertices = []\\n\\n        if callable(get_root_vertex):\\n            _ = get_root_vertex(mock_graph)\\n            # Should handle empty graph gracefully\\n\\n    def test_get_root_vertex_circular_dependencies(self):\\n        \\\"\\\"\\\"Test getting root vertex with circular dependencies.\\\"\\\"\\\"\\n        mock_graph = MagicMock()\\n\\n        # Create circular edges: node1 -> node2 -> node1\\n        mock_edge1 = MagicMock()\\n        mock_edge1.source_id = \\\"node1\\\"\\n        mock_edge2 = MagicMock()\\n        mock_edge2.source_id = \\\"node2\\\"\\n\\n        mock_graph.edges = [mock_edge1, mock_edge2]\\n\\n        mock_vertex1 = MagicMock()\\n        mock_vertex1.id = \\\"node1\\\"\\n        mock_vertex2 = MagicMock()\\n        mock_vertex2.id = \\\"node2\\\"\\n\\n        mock_graph.vertices = [mock_vertex1, mock_vertex2]\\n\\n        if callable(get_root_vertex):\\n            _ = get_root_vertex(mock_graph)\\n            # Should handle circular dependencies gracefully\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_registered_email_util.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3ce2f3abe6faeac13197deeb099fc31cf3889ea75b01a40b6ab5f4c7256df35\",\"content\":\"from unittest.mock import patch\\n\\nimport pytest\\nfrom langflow.services.telemetry.schema import EmailPayload\\nfrom langflow.utils.registered_email_util import _RegisteredEmailCache, get_email_model\\n\\n\\n@pytest.fixture(autouse=True)\\ndef reset_cache():\\n    \\\"\\\"\\\"Fixture to reset the registered email cache before each test.\\\"\\\"\\\"\\n    _RegisteredEmailCache.set_email_model(None)\\n    _RegisteredEmailCache._resolved = False\\n\\n\\nclass TestGetEmailModel:\\n    \\\"\\\"\\\"Test cases for the get_email_model function.\\\"\\\"\\\"\\n\\n    def test_get_email_model_success(self):\\n        \\\"\\\"\\\"Test email model retrieval with success.\\\"\\\"\\\"\\n        # Mock load_registration to return a valid registration\\n        with patch(\\\"langflow.utils.registered_email_util.load_registration\\\") as mock_load_registration:\\n            mock_load_registration.return_value = {\\\"email\\\": \\\"test@example.com\\\"}\\n\\n            result = get_email_model()\\n\\n            assert result is not None\\n            assert isinstance(result, EmailPayload)\\n            assert result.email == \\\"test@example.com\\\"\\n            # Verify cache\\n            assert _RegisteredEmailCache.get_email_model() == result\\n            # Verify resolved flag\\n            assert _RegisteredEmailCache.is_resolved()\\n\\n    def test_get_email_model_oserror(self):\\n        \\\"\\\"\\\"Test email model retrieval with failure (OSError).\\\"\\\"\\\"\\n        # Mock load_registration to raise OSError\\n        with patch(\\\"langflow.utils.registered_email_util.load_registration\\\") as mock_load_registration:\\n            mock_load_registration.side_effect = OSError(\\\"File not found\\\")\\n\\n            result = get_email_model()\\n\\n            assert result is None\\n            # Verify cache\\n            assert _RegisteredEmailCache.get_email_model() is None\\n            # Verify resolved flag\\n            assert _RegisteredEmailCache.is_resolved()\\n\\n    def test_get_email_model_cached(self):\\n        \\\"\\\"\\\"Test email model retrieval from cache.\\\"\\\"\\\"\\n        # Set a cached email model\\n        cached_email = EmailPayload(email=\\\"cached@example.com\\\")\\n        _RegisteredEmailCache.set_email_model(cached_email)\\n\\n        # Note: No need to mock load_registration\\n        result = get_email_model()\\n\\n        assert result == cached_email\\n        # Verify resolved flag\\n        assert _RegisteredEmailCache.is_resolved()\\n\\n    def test_get_email_model_invalid_registration(self):\\n        \\\"\\\"\\\"Test email model retrieval with failure (invalid registration).\\\"\\\"\\\"\\n        # Mock load_registration to return invalid registration\\n        with patch(\\\"langflow.utils.registered_email_util.load_registration\\\") as mock_load_registration:\\n            mock_load_registration.return_value = \\\"invalid\\\"\\n\\n            result = get_email_model()\\n\\n            assert result is None\\n            # Verify cache\\n            assert _RegisteredEmailCache.get_email_model() is None\\n            # Verify resolved flag\\n            assert _RegisteredEmailCache.is_resolved()\\n\\n    def test_get_email_model_invalid_email_missing(self):\\n        \\\"\\\"\\\"Test email model retrieval with failure (invalid email missing).\\\"\\\"\\\"\\n        # Mock load_registration to return a registration with invalid email\\n        with patch(\\\"langflow.utils.registered_email_util.load_registration\\\") as mock_load_registration:\\n            mock_load_registration.return_value = {\\\"email\\\": \\\"\\\"}\\n\\n            result = get_email_model()\\n\\n            assert result is None\\n            # Verify cache\\n            assert _RegisteredEmailCache.get_email_model() is None\\n            # Verify resolved flag\\n            assert _RegisteredEmailCache.is_resolved()\\n\\n    def test_get_email_model_invalid_email_format(self):\\n        \\\"\\\"\\\"Test email model retrieval with failure (invalid email format).\\\"\\\"\\\"\\n        # Mock load_registration to return a registration with invalid email\\n        with patch(\\\"langflow.utils.registered_email_util.load_registration\\\") as mock_load_registration:\\n            mock_load_registration.return_value = {\\\"email\\\": \\\"test@example\\\"}\\n\\n            result = get_email_model()\\n\\n            assert result is None\\n            # Verify cache\\n            assert _RegisteredEmailCache.get_email_model() is None\\n            # Verify resolved flag\\n            assert _RegisteredEmailCache.is_resolved()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_rewrite_file_path.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fd130012e893bd8421931150cd3b54832866dda5d260519ec007763519a723f9\",\"content\":\"import pytest\\nfrom lfx.base.data.utils import format_directory_path\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"input_path\\\", \\\"expected\\\"),\\n    [\\n        # Test case 1: Standard path with no newlines\\n        (\\\"/home/user/documents/file.txt\\\", \\\"/home/user/documents/file.txt\\\"),\\n        # Test case 2: Path with newline character\\n        (\\\"/home/user/docu\\\\nments/file.txt\\\", \\\"/home/user/docu\\\\\\\\nments/file.txt\\\"),\\n        # Test case 3: Path with multiple newline characters\\n        (\\\"/home/user/\\\\ndocu\\\\nments/file.txt\\\", \\\"/home/user/\\\\\\\\ndocu\\\\\\\\nments/file.txt\\\"),\\n        # Test case 4: Path with only newline characters\\n        (\\\"\\\\n\\\\n\\\\n\\\", \\\"\\\\\\\\n\\\\\\\\n\\\\\\\\n\\\"),\\n        # Test case 5: Empty path\\n        (\\\"\\\", \\\"\\\"),\\n        # Test case 6: Path with mixed newlines and other special characters\\n        (\\\"/home/user/my-\\\\ndocs/special_file!.pdf\\\", \\\"/home/user/my-\\\\\\\\ndocs/special_file!.pdf\\\"),\\n        # Test case 7: Windows-style path with newline\\n        (\\\"C:\\\\\\\\Users\\\\\\\\\\\\nDocuments\\\\\\\\file.txt\\\", \\\"C:\\\\\\\\Users\\\\\\\\\\\\\\\\nDocuments\\\\\\\\file.txt\\\"),\\n        # Test case 8: Path with trailing newline\\n        (\\\"/home/user/documents/\\\\n\\\", \\\"/home/user/documents/\\\\\\\\n\\\"),\\n        # Test case 9: Path with leading newline\\n        (\\\"\\\\n/home/user/documents/\\\", \\\"\\\\\\\\n/home/user/documents/\\\"),\\n        # Test case 10: Path with multiple consecutive newlines\\n        (\\\"/home/user/docu\\\\n\\\\nments/file.txt\\\", \\\"/home/user/docu\\\\\\\\n\\\\\\\\nments/file.txt\\\"),\\n    ],\\n)\\ndef test_format_directory_path(input_path, expected):\\n    result = format_directory_path(input_path)\\n    assert result == expected\\n\\n\\n# Additional test for type checking\\ndef test_format_directory_path_type():\\n    result = format_directory_path(\\\"/home/user/file.txt\\\")\\n    assert isinstance(result, str)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_schemas.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"acd29cace2c8d9353f986518dc11bb8aacd40e05dbdc8df49e5a8557cd5dac13\",\"content\":\"import enum\\nfrom unittest.mock import Mock, patch\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.utils.schemas import ChatOutputResponse, ContainsEnumMeta, DataOutputResponse, File\\nfrom pydantic import ValidationError\\n\\n\\nclass TestFile:\\n    \\\"\\\"\\\"Test cases for File TypedDict.\\\"\\\"\\\"\\n\\n    def test_file_typed_dict_structure(self):\\n        \\\"\\\"\\\"Test that File TypedDict has correct structure.\\\"\\\"\\\"\\n        # TypedDict is mainly for type hints, so we test basic usage\\n        file_data: File = {\\\"path\\\": \\\"/path/to/file.txt\\\", \\\"name\\\": \\\"file.txt\\\", \\\"type\\\": \\\"txt\\\"}\\n\\n        assert file_data[\\\"path\\\"] == \\\"/path/to/file.txt\\\"\\n        assert file_data[\\\"name\\\"] == \\\"file.txt\\\"\\n        assert file_data[\\\"type\\\"] == \\\"txt\\\"\\n\\n    def test_file_with_image_type(self):\\n        \\\"\\\"\\\"Test File with image type.\\\"\\\"\\\"\\n        file_data: File = {\\\"path\\\": \\\"/images/photo.jpg\\\", \\\"name\\\": \\\"photo.jpg\\\", \\\"type\\\": \\\"jpg\\\"}\\n\\n        assert file_data[\\\"type\\\"] == \\\"jpg\\\"\\n\\n    def test_file_required_fields(self):\\n        \\\"\\\"\\\"Test that File requires all specified fields.\\\"\\\"\\\"\\n        # This is a compile-time check via TypedDict\\n        # At runtime, we can still create incomplete dicts\\n        incomplete_file = {\\n            \\\"path\\\": \\\"/some/path\\\",\\n            \\\"name\\\": \\\"filename\\\",\\n            # missing \\\"type\\\"\\n        }\\n\\n        # TypedDict doesn't enforce at runtime, but the schema should require all fields\\n        assert \\\"path\\\" in incomplete_file\\n        assert \\\"name\\\" in incomplete_file\\n\\n\\nclass TestChatOutputResponse:\\n    \\\"\\\"\\\"Test cases for ChatOutputResponse Pydantic model.\\\"\\\"\\\"\\n\\n    def test_basic_chat_response_creation(self):\\n        \\\"\\\"\\\"Test creating basic chat response.\\\"\\\"\\\"\\n        response = ChatOutputResponse(message=\\\"Hello, world!\\\", type=\\\"text\\\")\\n\\n        assert response.message == \\\"Hello, world!\\\"\\n        assert response.sender == \\\"Machine\\\"  # Default value\\n        assert response.sender_name == \\\"AI\\\"  # Default value\\n        assert response.type == \\\"text\\\"\\n        assert response.files == []\\n        assert response.session_id is None\\n        assert response.stream_url is None\\n        assert response.component_id is None\\n\\n    def test_chat_response_with_all_fields(self):\\n        \\\"\\\"\\\"Test creating chat response with all fields.\\\"\\\"\\\"\\n        files = [{\\\"path\\\": \\\"/test.txt\\\", \\\"name\\\": \\\"test.txt\\\", \\\"type\\\": \\\"txt\\\"}]\\n\\n        response = ChatOutputResponse(\\n            message=\\\"Test message\\\",\\n            sender=\\\"Human\\\",\\n            sender_name=\\\"User\\\",\\n            session_id=\\\"session-123\\\",\\n            stream_url=\\\"http://stream.url\\\",\\n            component_id=\\\"comp-456\\\",\\n            files=files,\\n            type=\\\"text\\\",\\n        )\\n\\n        assert response.message == \\\"Test message\\\"\\n        assert response.sender == \\\"Human\\\"\\n        assert response.sender_name == \\\"User\\\"\\n        assert response.session_id == \\\"session-123\\\"\\n        assert response.stream_url == \\\"http://stream.url\\\"\\n        assert response.component_id == \\\"comp-456\\\"\\n        assert response.files == files\\n        assert response.type == \\\"text\\\"\\n\\n    def test_chat_response_with_uuid_session_id_converts_to_string(self):\\n        \\\"\\\"\\\"Test UUID session_id conversion to string.\\\"\\\"\\\"\\n        session_id = uuid4()\\n        response = ChatOutputResponse(message=\\\"Test message\\\", session_id=session_id, type=\\\"text\\\")\\n        assert response.session_id == str(session_id)\\n\\n    def test_chat_response_with_non_string_non_uuid_session_id_raises_error(self):\\n        \\\"\\\"\\\"Test that non-string, non-UUID session_id raises validation error.\\\"\\\"\\\"\\n        with pytest.raises(ValidationError, match=\\\"must be a UUID, string, or None\\\"):\\n            ChatOutputResponse(message=\\\"Test message\\\", session_id=123, type=\\\"text\\\")\\n\\n    def test_chat_response_with_list_message(self):\\n        \\\"\\\"\\\"Test chat response with list message.\\\"\\\"\\\"\\n        message_list = [\\\"Hello\\\", {\\\"type\\\": \\\"text\\\", \\\"content\\\": \\\"world\\\"}]\\n\\n        response = ChatOutputResponse(\\n            message=message_list,\\n            sender=\\\"Human\\\",  # Use non-AI sender to avoid message validation\\n            type=\\\"mixed\\\",\\n        )\\n\\n        assert response.message == message_list\\n\\n    def test_validate_files_valid_files(self):\\n        \\\"\\\"\\\"Test file validation with valid files.\\\"\\\"\\\"\\n        files = [\\n            {\\\"path\\\": \\\"/file1.txt\\\", \\\"name\\\": \\\"file1.txt\\\", \\\"type\\\": \\\"txt\\\"},\\n            {\\\"path\\\": \\\"/file2.jpg\\\", \\\"name\\\": \\\"file2.jpg\\\", \\\"type\\\": \\\"jpg\\\"},\\n        ]\\n\\n        response = ChatOutputResponse(message=\\\"Test\\\", files=files, type=\\\"text\\\")\\n\\n        assert len(response.files) == 2\\n        assert response.files[0][\\\"name\\\"] == \\\"file1.txt\\\"\\n        assert response.files[1][\\\"type\\\"] == \\\"jpg\\\"\\n\\n    def test_validate_files_missing_name_and_type(self):\\n        \\\"\\\"\\\"Test file validation when name and type are missing.\\\"\\\"\\\"\\n        files = [{\\\"path\\\": \\\"/documents/report.pdf\\\"}]\\n\\n        with (\\n            patch(\\\"langflow.utils.schemas.TEXT_FILE_TYPES\\\", [\\\"pdf\\\", \\\"txt\\\"]),\\n            patch(\\\"langflow.utils.schemas.IMG_FILE_TYPES\\\", [\\\"jpg\\\", \\\"png\\\"]),\\n        ):\\n            response = ChatOutputResponse(message=\\\"Test\\\", files=files, type=\\\"text\\\")\\n\\n            # Should extract name from path\\n            assert response.files[0][\\\"name\\\"] == \\\"report.pdf\\\"\\n            # Should extract type from extension\\n            assert response.files[0][\\\"type\\\"] == \\\"pdf\\\"\\n\\n    def test_validate_files_missing_path_raises_error(self):\\n        \\\"\\\"\\\"Test that missing path raises validation error.\\\"\\\"\\\"\\n        files = [{\\\"name\\\": \\\"file.txt\\\", \\\"type\\\": \\\"txt\\\"}]\\n\\n        with pytest.raises(ValidationError, match=\\\"File path is required\\\"):\\n            ChatOutputResponse(message=\\\"Test\\\", files=files, type=\\\"text\\\")\\n\\n    def test_validate_files_non_dict_raises_error(self):\\n        \\\"\\\"\\\"Test that non-dict files raise validation error.\\\"\\\"\\\"\\n        files = [\\\"not_a_dict\\\"]\\n\\n        with pytest.raises(ValidationError, match=\\\"Files must be a list of dictionaries\\\"):\\n            ChatOutputResponse(message=\\\"Test\\\", files=files, type=\\\"text\\\")\\n\\n    def test_validate_files_unknown_type_raises_error(self):\\n        \\\"\\\"\\\"Test that unknown file type raises validation error.\\\"\\\"\\\"\\n        files = [{\\\"path\\\": \\\"/unknown/file.xyz\\\"}]\\n\\n        with (\\n            patch(\\\"langflow.utils.schemas.TEXT_FILE_TYPES\\\", [\\\"txt\\\"]),\\n            patch(\\\"langflow.utils.schemas.IMG_FILE_TYPES\\\", [\\\"jpg\\\"]),\\n            pytest.raises(ValidationError, match=\\\"File type is required\\\"),\\n        ):\\n            ChatOutputResponse(message=\\\"Test\\\", files=files, type=\\\"text\\\")\\n\\n    def test_validate_files_empty_list(self):\\n        \\\"\\\"\\\"Test validation with empty files list.\\\"\\\"\\\"\\n        response = ChatOutputResponse(message=\\\"Test\\\", files=[], type=\\\"text\\\")\\n\\n        assert response.files == []\\n\\n    def test_validate_files_none(self):\\n        \\\"\\\"\\\"Test validation with None files.\\\"\\\"\\\"\\n        # None is not valid for files field, it should use the default\\n        response = ChatOutputResponse(message=\\\"Test\\\", type=\\\"text\\\")\\n\\n        # Should be set to default empty list\\n        assert response.files == []\\n\\n    def test_validate_files_type_detection_in_path(self):\\n        \\\"\\\"\\\"Test file type detection when extension not clear but type in path.\\\"\\\"\\\"\\n        files = [{\\\"path\\\": \\\"/images/photo_jpg_compressed\\\"}]\\n\\n        with (\\n            patch(\\\"langflow.utils.schemas.TEXT_FILE_TYPES\\\", [\\\"txt\\\"]),\\n            patch(\\\"langflow.utils.schemas.IMG_FILE_TYPES\\\", [\\\"jpg\\\", \\\"png\\\"]),\\n        ):\\n            response = ChatOutputResponse(message=\\\"Test\\\", files=files, type=\\\"text\\\")\\n\\n            # Should detect 'jpg' in path\\n            assert response.files[0][\\\"type\\\"] == \\\"jpg\\\"\\n\\n    @patch.object(ChatOutputResponse, \\\"__init__\\\")\\n    def test_from_message_class_method(self, mock_init):\\n        \\\"\\\"\\\"Test creating ChatOutputResponse from message.\\\"\\\"\\\"\\n        mock_init.return_value = None\\n        mock_message = Mock()\\n        mock_message.content = \\\"Hello from message\\\"\\n\\n        ChatOutputResponse.from_message(mock_message)\\n\\n        # Verify __init__ was called with correct parameters\\n        mock_init.assert_called_once_with(message=\\\"Hello from message\\\", sender=\\\"Machine\\\", sender_name=\\\"AI\\\")\\n\\n    @patch.object(ChatOutputResponse, \\\"__init__\\\")\\n    def test_from_message_with_custom_sender(self, mock_init):\\n        \\\"\\\"\\\"Test creating ChatOutputResponse from message with custom sender.\\\"\\\"\\\"\\n        mock_init.return_value = None\\n        mock_message = Mock()\\n        mock_message.content = \\\"Custom message\\\"\\n\\n        ChatOutputResponse.from_message(mock_message, sender=\\\"Human\\\", sender_name=\\\"User\\\")\\n\\n        # Verify __init__ was called with correct parameters\\n        mock_init.assert_called_once_with(message=\\\"Custom message\\\", sender=\\\"Human\\\", sender_name=\\\"User\\\")\\n\\n    def test_validate_message_ai_sender_newline_formatting(self):\\n        \\\"\\\"\\\"Test message validation for AI sender with newline formatting.\\\"\\\"\\\"\\n        response = ChatOutputResponse(message=\\\"Line 1\\\\nLine 2\\\\nLine 3\\\", sender=\\\"Machine\\\", type=\\\"text\\\")\\n\\n        # Should convert single \\\\n to \\\\n\\\\n for markdown compliance\\n        expected_message = \\\"Line 1\\\\n\\\\nLine 2\\\\n\\\\nLine 3\\\"\\n        assert response.message == expected_message\\n\\n    def test_validate_message_ai_sender_existing_double_newlines(self):\\n        \\\"\\\"\\\"Test message validation with existing double newlines.\\\"\\\"\\\"\\n        response = ChatOutputResponse(message=\\\"Line 1\\\\n\\\\nLine 2\\\\n\\\\nLine 3\\\", sender=\\\"Machine\\\", type=\\\"text\\\")\\n\\n        # Should not add extra newlines where double newlines already exist\\n        expected_message = \\\"Line 1\\\\n\\\\nLine 2\\\\n\\\\nLine 3\\\"\\n        assert response.message == expected_message\\n\\n    def test_validate_message_non_ai_sender_unchanged(self):\\n        \\\"\\\"\\\"Test that non-AI sender messages are unchanged.\\\"\\\"\\\"\\n        original_message = \\\"Line 1\\\\nLine 2\\\\nLine 3\\\"\\n        response = ChatOutputResponse(message=original_message, sender=\\\"Human\\\", type=\\\"text\\\")\\n\\n        # Should remain unchanged for non-AI senders\\n        assert response.message == original_message\\n\\n    def test_validate_message_complex_newline_patterns(self):\\n        \\\"\\\"\\\"Test message validation with complex newline patterns.\\\"\\\"\\\"\\n        response = ChatOutputResponse(\\n            message=\\\"Para 1\\\\n\\\\nPara 2\\\\nLine in para 2\\\\n\\\\n\\\\nPara 3\\\", sender=\\\"Machine\\\", type=\\\"text\\\"\\n        )\\n\\n        # The actual logic: replace \\\\n\\\\n with \\\\n, then replace \\\\n with \\\\n\\\\n\\n        # \\\"Para 1\\\\n\\\\nPara 2\\\\nLine in para 2\\\\n\\\\n\\\\nPara 3\\\"\\n        # -> \\\"Para 1\\\\nPara 2\\\\nLine in para 2\\\\n\\\\nPara 3\\\" (replace \\\\n\\\\n with \\\\n)\\n        # -> \\\"Para 1\\\\n\\\\nPara 2\\\\n\\\\nLine in para 2\\\\n\\\\n\\\\n\\\\nPara 3\\\" (replace \\\\n with \\\\n\\\\n)\\n        expected_message = \\\"Para 1\\\\n\\\\nPara 2\\\\n\\\\nLine in para 2\\\\n\\\\n\\\\n\\\\nPara 3\\\"\\n        assert response.message == expected_message\\n\\n    def test_message_validation_with_list_message(self):\\n        \\\"\\\"\\\"Test message validation when message is a list.\\\"\\\"\\\"\\n        message_list = [\\\"Hello\\\", \\\"World\\\"]\\n        response = ChatOutputResponse(\\n            message=message_list,\\n            sender=\\\"Human\\\",  # Use non-AI sender to avoid validation error\\n            type=\\\"text\\\",\\n        )\\n\\n        # List messages should not be processed for newlines when sender is not AI\\n        assert response.message == message_list\\n\\n\\nclass TestDataOutputResponse:\\n    \\\"\\\"\\\"Test cases for DataOutputResponse Pydantic model.\\\"\\\"\\\"\\n\\n    def test_basic_data_response_creation(self):\\n        \\\"\\\"\\\"Test creating basic data output response.\\\"\\\"\\\"\\n        data = [{\\\"key\\\": \\\"value\\\"}, {\\\"another\\\": \\\"item\\\"}]\\n\\n        response = DataOutputResponse(data=data)\\n\\n        assert response.data == data\\n\\n    def test_data_response_with_none_values(self):\\n        \\\"\\\"\\\"Test data response with None values in list.\\\"\\\"\\\"\\n        data = [{\\\"key\\\": \\\"value\\\"}, None, {\\\"another\\\": \\\"item\\\"}]\\n\\n        response = DataOutputResponse(data=data)\\n\\n        assert response.data == data\\n        assert response.data[1] is None\\n\\n    def test_data_response_empty_list(self):\\n        \\\"\\\"\\\"Test data response with empty list.\\\"\\\"\\\"\\n        response = DataOutputResponse(data=[])\\n\\n        assert response.data == []\\n\\n    def test_data_response_all_none(self):\\n        \\\"\\\"\\\"Test data response with all None values.\\\"\\\"\\\"\\n        data = [None, None, None]\\n\\n        response = DataOutputResponse(data=data)\\n\\n        assert response.data == data\\n        assert all(item is None for item in response.data)\\n\\n    def test_data_response_complex_dicts(self):\\n        \\\"\\\"\\\"Test data response with complex dictionary structures.\\\"\\\"\\\"\\n        data = [{\\\"nested\\\": {\\\"key\\\": \\\"value\\\"}, \\\"list\\\": [1, 2, 3], \\\"number\\\": 42, \\\"boolean\\\": True}, {\\\"simple\\\": \\\"string\\\"}]\\n\\n        response = DataOutputResponse(data=data)\\n\\n        assert response.data == data\\n        assert response.data[0][\\\"nested\\\"][\\\"key\\\"] == \\\"value\\\"\\n        assert response.data[0][\\\"list\\\"] == [1, 2, 3]\\n\\n\\nclass TestContainsEnumMeta:\\n    \\\"\\\"\\\"Test cases for ContainsEnumMeta metaclass.\\\"\\\"\\\"\\n\\n    def test_enum_with_contains_meta(self):\\n        \\\"\\\"\\\"Test enum using ContainsEnumMeta.\\\"\\\"\\\"\\n\\n        class TestEnum(enum.Enum, metaclass=ContainsEnumMeta):\\n            VALUE_A = \\\"a\\\"\\n            VALUE_B = \\\"b\\\"\\n            VALUE_C = \\\"c\\\"\\n\\n        # Test contains functionality\\n        assert \\\"a\\\" in TestEnum\\n        assert \\\"b\\\" in TestEnum\\n        assert \\\"c\\\" in TestEnum\\n        assert \\\"d\\\" not in TestEnum\\n        assert \\\"invalid\\\" not in TestEnum\\n\\n    def test_enum_contains_with_different_types(self):\\n        \\\"\\\"\\\"Test enum contains with different value types.\\\"\\\"\\\"\\n\\n        class MixedEnum(enum.Enum, metaclass=ContainsEnumMeta):\\n            STRING_VAL = \\\"string\\\"\\n            INT_VAL = 42\\n            FLOAT_VAL = 3.14\\n\\n        assert \\\"string\\\" in MixedEnum\\n        assert 42 in MixedEnum\\n        assert 3.14 in MixedEnum\\n        assert \\\"not_string\\\" not in MixedEnum\\n        assert 999 not in MixedEnum\\n\\n    def test_enum_contains_with_duplicate_values(self):\\n        \\\"\\\"\\\"Test enum contains when enum has aliases.\\\"\\\"\\\"\\n\\n        class AliasEnum(enum.Enum, metaclass=ContainsEnumMeta):\\n            FIRST = \\\"value\\\"\\n            SECOND = \\\"value\\\"  # Alias for FIRST  # noqa: PIE796\\n            THIRD = \\\"other\\\"\\n\\n        assert \\\"value\\\" in AliasEnum\\n        assert \\\"other\\\" in AliasEnum\\n        assert \\\"nonexistent\\\" not in AliasEnum\\n\\n    def test_enum_contains_error_handling(self):\\n        \\\"\\\"\\\"Test that contains handles ValueError gracefully.\\\"\\\"\\\"\\n\\n        class StrictEnum(enum.Enum, metaclass=ContainsEnumMeta):\\n            def __new__(cls, value):\\n                if not isinstance(value, str):\\n                    msg = \\\"Only strings allowed\\\"\\n                    raise TypeError(msg)\\n                obj = object.__new__(cls)\\n                obj._value_ = value\\n                return obj\\n\\n            VALID = \\\"valid\\\"\\n\\n        assert \\\"valid\\\" in StrictEnum\\n        assert 123 not in StrictEnum  # Should return False, not raise\\n\\n    def test_enum_normal_functionality_preserved(self):\\n        \\\"\\\"\\\"Test that normal enum functionality is preserved.\\\"\\\"\\\"\\n\\n        class NormalEnum(enum.Enum, metaclass=ContainsEnumMeta):\\n            OPTION_1 = \\\"opt1\\\"\\n            OPTION_2 = \\\"opt2\\\"\\n\\n        # Normal enum operations should still work\\n        assert NormalEnum.OPTION_1.value == \\\"opt1\\\"\\n        assert NormalEnum(\\\"opt1\\\") == NormalEnum.OPTION_1\\n        assert list(NormalEnum) == [NormalEnum.OPTION_1, NormalEnum.OPTION_2]\\n\\n    def test_enum_inheritance_with_contains_meta(self):\\n        \\\"\\\"\\\"Test enum inheritance with ContainsEnumMeta.\\\"\\\"\\\"\\n\\n        class BaseEnum(enum.Enum, metaclass=ContainsEnumMeta):\\n            BASE_VALUE = \\\"base\\\"\\n\\n        # Test that the metaclass works for the base enum\\n        assert \\\"base\\\" in BaseEnum\\n        assert \\\"invalid\\\" not in BaseEnum\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_template_validation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"02256abf670d1a67ea12318597b15d25c45c91eb6081728dce1775b83f55a972\",\"content\":\"\\\"\\\"\\\"Unit tests for template validation utilities.\\\"\\\"\\\"\\n\\nimport asyncio\\nfrom unittest.mock import AsyncMock, Mock, patch\\n\\nimport pytest\\nfrom langflow.utils.template_validation import (\\n    _validate_event_stream,\\n    validate_flow_can_build,\\n    validate_flow_code,\\n    validate_flow_execution,\\n    validate_template_structure,\\n)\\n\\n\\nclass AsyncIteratorMock:\\n    \\\"\\\"\\\"Mock class that provides proper async iteration.\\\"\\\"\\\"\\n\\n    def __init__(self, items):\\n        self.items = items\\n\\n    def __aiter__(self):\\n        return self\\n\\n    async def __anext__(self):\\n        if not self.items:\\n            raise StopAsyncIteration\\n        return self.items.pop(0)\\n\\n\\nclass TestValidateTemplateStructure:\\n    \\\"\\\"\\\"Test cases for validate_template_structure function.\\\"\\\"\\\"\\n\\n    def test_valid_template_structure(self):\\n        \\\"\\\"\\\"Test validation passes for valid template structure.\\\"\\\"\\\"\\n        template_data = {\\n            \\\"nodes\\\": [\\n                {\\\"id\\\": \\\"node1\\\", \\\"data\\\": {\\\"type\\\": \\\"input\\\"}},\\n                {\\\"id\\\": \\\"node2\\\", \\\"data\\\": {\\\"type\\\": \\\"output\\\"}},\\n            ],\\n            \\\"edges\\\": [{\\\"source\\\": \\\"node1\\\", \\\"target\\\": \\\"node2\\\"}],\\n        }\\n        errors = validate_template_structure(template_data, \\\"test.json\\\")\\n        assert errors == []\\n\\n    def test_valid_template_with_data_wrapper(self):\\n        \\\"\\\"\\\"Test validation passes for template with data wrapper.\\\"\\\"\\\"\\n        template_data = {\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [{\\\"id\\\": \\\"node1\\\", \\\"data\\\": {\\\"type\\\": \\\"input\\\"}}],\\n                \\\"edges\\\": [],\\n            }\\n        }\\n        errors = validate_template_structure(template_data, \\\"test.json\\\")\\n        assert errors == []\\n\\n    def test_missing_nodes_field(self):\\n        \\\"\\\"\\\"Test validation fails when nodes field is missing.\\\"\\\"\\\"\\n        template_data = {\\\"edges\\\": []}\\n        errors = validate_template_structure(template_data, \\\"test.json\\\")\\n        assert \\\"test.json: Missing 'nodes' field\\\" in errors\\n\\n    def test_missing_edges_field(self):\\n        \\\"\\\"\\\"Test validation fails when edges field is missing.\\\"\\\"\\\"\\n        template_data = {\\\"nodes\\\": []}\\n        errors = validate_template_structure(template_data, \\\"test.json\\\")\\n        assert \\\"test.json: Missing 'edges' field\\\" in errors\\n\\n    def test_nodes_not_list(self):\\n        \\\"\\\"\\\"Test validation fails when nodes is not a list.\\\"\\\"\\\"\\n        template_data = {\\\"nodes\\\": \\\"not_a_list\\\", \\\"edges\\\": []}\\n        errors = validate_template_structure(template_data, \\\"test.json\\\")\\n        assert \\\"test.json: 'nodes' must be a list\\\" in errors\\n\\n    def test_edges_not_list(self):\\n        \\\"\\\"\\\"Test validation fails when edges is not a list.\\\"\\\"\\\"\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": \\\"not_a_list\\\"}\\n        errors = validate_template_structure(template_data, \\\"test.json\\\")\\n        assert \\\"test.json: 'edges' must be a list\\\" in errors\\n\\n    def test_node_missing_id(self):\\n        \\\"\\\"\\\"Test validation fails when node is missing id.\\\"\\\"\\\"\\n        template_data = {\\n            \\\"nodes\\\": [{\\\"data\\\": {\\\"type\\\": \\\"input\\\"}}],\\n            \\\"edges\\\": [],\\n        }\\n        errors = validate_template_structure(template_data, \\\"test.json\\\")\\n        assert \\\"test.json: Node 0 missing 'id'\\\" in errors\\n\\n    def test_node_missing_data(self):\\n        \\\"\\\"\\\"Test validation fails when node is missing data.\\\"\\\"\\\"\\n        template_data = {\\n            \\\"nodes\\\": [{\\\"id\\\": \\\"node1\\\"}],\\n            \\\"edges\\\": [],\\n        }\\n        errors = validate_template_structure(template_data, \\\"test.json\\\")\\n        assert \\\"test.json: Node 0 missing 'data'\\\" in errors\\n\\n    def test_multiple_validation_errors(self):\\n        \\\"\\\"\\\"Test multiple validation errors are collected.\\\"\\\"\\\"\\n        template_data = {\\n            \\\"nodes\\\": [\\n                {\\\"data\\\": {\\\"type\\\": \\\"input\\\"}},  # Missing id\\n                {\\\"id\\\": \\\"node2\\\"},  # Missing data\\n            ],\\n            \\\"edges\\\": \\\"not_a_list\\\",\\n        }\\n        errors = validate_template_structure(template_data, \\\"test.json\\\")\\n        assert len(errors) == 3\\n        assert \\\"Node 0 missing 'id'\\\" in str(errors)\\n        assert \\\"Node 1 missing 'data'\\\" in str(errors)\\n        assert \\\"'edges' must be a list\\\" in str(errors)\\n\\n\\nclass TestValidateFlowCanBuild:\\n    \\\"\\\"\\\"Test cases for validate_flow_can_build function.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.utils.template_validation.Graph\\\")\\n    def test_valid_flow_builds_successfully(self, mock_graph_class):\\n        \\\"\\\"\\\"Test validation passes when flow builds successfully.\\\"\\\"\\\"\\n        # Setup mock graph\\n        mock_graph = Mock()\\n        mock_graph.vertices = [Mock(id=\\\"vertex1\\\"), Mock(id=\\\"vertex2\\\")]\\n        mock_graph_class.from_payload.return_value = mock_graph\\n\\n        template_data = {\\n            \\\"nodes\\\": [{\\\"id\\\": \\\"node1\\\", \\\"data\\\": {\\\"type\\\": \\\"input\\\"}}],\\n            \\\"edges\\\": [],\\n        }\\n\\n        errors = validate_flow_can_build(template_data, \\\"test.json\\\")\\n        assert errors == []\\n        mock_graph_class.from_payload.assert_called_once()\\n        mock_graph.validate_stream.assert_called_once()\\n\\n    @patch(\\\"langflow.utils.template_validation.Graph\\\")\\n    def test_flow_build_fails_with_exception(self, mock_graph_class):\\n        \\\"\\\"\\\"Test validation fails when flow build raises exception.\\\"\\\"\\\"\\n        mock_graph_class.from_payload.side_effect = ValueError(\\\"Build failed\\\")\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        errors = validate_flow_can_build(template_data, \\\"test.json\\\")\\n        assert len(errors) == 1\\n        assert \\\"test.json: Failed to build flow graph: Build failed\\\" in errors\\n\\n    @patch(\\\"langflow.utils.template_validation.Graph\\\")\\n    def test_flow_has_no_vertices(self, mock_graph_class):\\n        \\\"\\\"\\\"Test validation fails when flow has no vertices.\\\"\\\"\\\"\\n        mock_graph = Mock()\\n        mock_graph.vertices = []\\n        mock_graph_class.from_payload.return_value = mock_graph\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        errors = validate_flow_can_build(template_data, \\\"test.json\\\")\\n        assert \\\"test.json: Flow has no vertices after building\\\" in errors\\n\\n    @patch(\\\"langflow.utils.template_validation.Graph\\\")\\n    def test_vertex_missing_id(self, mock_graph_class):\\n        \\\"\\\"\\\"Test validation fails when vertex is missing ID.\\\"\\\"\\\"\\n        mock_vertex = Mock()\\n        mock_vertex.id = None\\n        mock_graph = Mock()\\n        mock_graph.vertices = [mock_vertex]\\n        mock_graph_class.from_payload.return_value = mock_graph\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        errors = validate_flow_can_build(template_data, \\\"test.json\\\")\\n        assert \\\"test.json: Vertex missing ID\\\" in errors\\n\\n    @patch(\\\"langflow.utils.template_validation.Graph\\\")\\n    def test_uses_unique_flow_id(self, mock_graph_class):\\n        \\\"\\\"\\\"Test that unique flow ID and name are used.\\\"\\\"\\\"\\n        mock_graph = Mock()\\n        mock_graph.vertices = [Mock(id=\\\"vertex1\\\")]\\n        mock_graph_class.from_payload.return_value = mock_graph\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        validate_flow_can_build(template_data, \\\"my_flow.json\\\")\\n\\n        # Verify from_payload was called with proper parameters\\n        call_args = mock_graph_class.from_payload.call_args\\n        assert call_args[0][0] == template_data  # template_data\\n        assert len(call_args[0][1]) == 36  # UUID length\\n        assert call_args[0][2] == \\\"my_flow\\\"  # flow_name\\n        # The user_id is passed as a keyword argument\\n        assert call_args[1][\\\"user_id\\\"] == \\\"test_user\\\"\\n\\n    @patch(\\\"langflow.utils.template_validation.Graph\\\")\\n    def test_validate_stream_exception(self, mock_graph_class):\\n        \\\"\\\"\\\"Test that validate_stream exceptions are caught.\\\"\\\"\\\"\\n        mock_graph = Mock()\\n        mock_graph.vertices = [Mock(id=\\\"vertex1\\\")]\\n        mock_graph.validate_stream.side_effect = ValueError(\\\"Stream validation failed\\\")\\n        mock_graph_class.from_payload.return_value = mock_graph\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        errors = validate_flow_can_build(template_data, \\\"test.json\\\")\\n\\n        assert len(errors) == 1\\n        assert \\\"Failed to build flow graph: Stream validation failed\\\" in errors[0]\\n\\n\\nclass TestValidateFlowCode:\\n    \\\"\\\"\\\"Test cases for validate_flow_code function.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.utils.template_validation.validate_code\\\")\\n    def test_valid_flow_code(self, mock_validate_code):\\n        \\\"\\\"\\\"Test validation passes when code is valid.\\\"\\\"\\\"\\n        mock_validate_code.return_value = {\\n            \\\"imports\\\": {\\\"errors\\\": []},\\n            \\\"function\\\": {\\\"errors\\\": []},\\n        }\\n\\n        template_data = {\\n            \\\"data\\\": {\\n                \\\"nodes\\\": [\\n                    {\\n                        \\\"id\\\": \\\"node1\\\",\\n                        \\\"data\\\": {\\n                            \\\"id\\\": \\\"node1\\\",\\n                            \\\"node\\\": {\\n                                \\\"template\\\": {\\n                                    \\\"code_field\\\": {\\n                                        \\\"type\\\": \\\"code\\\",\\n                                        \\\"value\\\": \\\"def hello(): return 'world'\\\",\\n                                    }\\n                                }\\n                            },\\n                        },\\n                    }\\n                ]\\n            }\\n        }\\n\\n        errors = validate_flow_code(template_data, \\\"test.json\\\")\\n        assert errors == []\\n        mock_validate_code.assert_called_once_with(\\\"def hello(): return 'world'\\\")\\n\\n    @patch(\\\"langflow.utils.template_validation.validate_code\\\")\\n    def test_code_import_errors(self, mock_validate_code):\\n        \\\"\\\"\\\"Test validation fails when code has import errors.\\\"\\\"\\\"\\n        mock_validate_code.return_value = {\\n            \\\"imports\\\": {\\\"errors\\\": [\\\"Module not found: nonexistent_module\\\"]},\\n            \\\"function\\\": {\\\"errors\\\": []},\\n        }\\n\\n        template_data = {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"data\\\": {\\n                        \\\"id\\\": \\\"node1\\\",\\n                        \\\"node\\\": {\\n                            \\\"template\\\": {\\n                                \\\"code_field\\\": {\\n                                    \\\"type\\\": \\\"code\\\",\\n                                    \\\"value\\\": \\\"import nonexistent_module\\\",\\n                                }\\n                            }\\n                        },\\n                    }\\n                }\\n            ]\\n        }\\n\\n        errors = validate_flow_code(template_data, \\\"test.json\\\")\\n        assert len(errors) == 1\\n        assert \\\"Import error in node node1: Module not found: nonexistent_module\\\" in errors[0]\\n\\n    @patch(\\\"langflow.utils.template_validation.validate_code\\\")\\n    def test_code_function_errors(self, mock_validate_code):\\n        \\\"\\\"\\\"Test validation fails when code has function errors.\\\"\\\"\\\"\\n        mock_validate_code.return_value = {\\n            \\\"imports\\\": {\\\"errors\\\": []},\\n            \\\"function\\\": {\\\"errors\\\": [\\\"Syntax error in function\\\"]},\\n        }\\n\\n        template_data = {\\n            \\\"nodes\\\": [\\n                {\\n                    \\\"data\\\": {\\n                        \\\"id\\\": \\\"node2\\\",\\n                        \\\"node\\\": {\\n                            \\\"template\\\": {\\n                                \\\"code_field\\\": {\\n                                    \\\"type\\\": \\\"code\\\",\\n                                    \\\"value\\\": \\\"def broken(: pass\\\",\\n                                }\\n                            }\\n                        },\\n                    }\\n                }\\n            ]\\n        }\\n\\n        errors = validate_flow_code(template_data, \\\"test.json\\\")\\n        assert len(errors) == 1\\n        assert \\\"Function error in node node2: Syntax error in function\\\" in errors[0]\\n\\n    def test_no_code_fields(self):\\n        \\\"\\\"\\\"Test validation passes when there are no code fields.\\\"\\\"\\\"\\n        template_data = {\\n            \\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"text_field\\\": {\\\"type\\\": \\\"text\\\", \\\"value\\\": \\\"hello\\\"}}}}}]\\n        }\\n\\n        errors = validate_flow_code(template_data, \\\"test.json\\\")\\n        assert errors == []\\n\\n    def test_empty_code_value(self):\\n        \\\"\\\"\\\"Test validation passes when code value is empty.\\\"\\\"\\\"\\n        template_data = {\\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"code_field\\\": {\\\"type\\\": \\\"code\\\", \\\"value\\\": \\\"\\\"}}}}}]}\\n\\n        errors = validate_flow_code(template_data, \\\"test.json\\\")\\n        assert errors == []\\n\\n    def test_code_validation_exception(self):\\n        \\\"\\\"\\\"Test validation handles exceptions gracefully.\\\"\\\"\\\"\\n        template_data = {\\n            \\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"code_field\\\": {\\\"type\\\": \\\"code\\\", \\\"value\\\": \\\"def test(): pass\\\"}}}}}]\\n        }\\n\\n        with patch(\\\"langflow.utils.template_validation.validate_code\\\", side_effect=ValueError(\\\"Unexpected error\\\")):\\n            errors = validate_flow_code(template_data, \\\"test.json\\\")\\n            assert len(errors) == 1\\n            assert \\\"Code validation failed: Unexpected error\\\" in errors[0]\\n\\n    def test_code_validation_other_exceptions(self):\\n        \\\"\\\"\\\"Test validation handles different exception types.\\\"\\\"\\\"\\n        template_data = {\\n            \\\"nodes\\\": [{\\\"data\\\": {\\\"node\\\": {\\\"template\\\": {\\\"code_field\\\": {\\\"type\\\": \\\"code\\\", \\\"value\\\": \\\"def test(): pass\\\"}}}}}]\\n        }\\n\\n        # Test TypeError\\n        with patch(\\\"langflow.utils.template_validation.validate_code\\\", side_effect=TypeError(\\\"Type error\\\")):\\n            errors = validate_flow_code(template_data, \\\"test.json\\\")\\n            assert len(errors) == 1\\n            assert \\\"Code validation failed: Type error\\\" in errors[0]\\n\\n        # Test KeyError\\n        with patch(\\\"langflow.utils.template_validation.validate_code\\\", side_effect=KeyError(\\\"key\\\")):\\n            errors = validate_flow_code(template_data, \\\"test.json\\\")\\n            assert len(errors) == 1\\n            assert \\\"Code validation failed: 'key'\\\" in errors[0]\\n\\n        # Test AttributeError\\n        with patch(\\\"langflow.utils.template_validation.validate_code\\\", side_effect=AttributeError(\\\"Attribute error\\\")):\\n            errors = validate_flow_code(template_data, \\\"test.json\\\")\\n            assert len(errors) == 1\\n            assert \\\"Code validation failed: Attribute error\\\" in errors[0]\\n\\n\\nclass TestValidateFlowExecution:\\n    \\\"\\\"\\\"Test cases for validate_flow_execution function.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_successful_flow_execution(self):\\n        \\\"\\\"\\\"Test validation passes when flow execution succeeds.\\\"\\\"\\\"\\n        # Mock client responses\\n        mock_client = AsyncMock()\\n\\n        # Mock create flow response\\n        create_response = Mock()\\n        create_response.status_code = 201\\n        create_response.json.return_value = {\\\"id\\\": \\\"flow123\\\"}\\n        mock_client.post.return_value = create_response\\n\\n        # Mock build response\\n        build_response = Mock()\\n        build_response.status_code = 200\\n        build_response.json.return_value = {\\\"job_id\\\": \\\"job123\\\"}\\n\\n        # Mock events response\\n        events_response = Mock()\\n        events_response.status_code = 200\\n        events_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"vertices_sorted\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"ids\\\": [\\\"v1\\\"]}}',\\n                    '{\\\"event\\\": \\\"end_vertex\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"build_data\\\": {\\\"result\\\": \\\"success\\\"}}}',\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        # Set up call sequence\\n        mock_client.post.side_effect = [create_response, build_response]\\n        mock_client.get.return_value = events_response\\n        mock_client.delete.return_value = Mock()\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        headers = {\\\"Authorization\\\": \\\"Bearer token\\\"}\\n\\n        errors = await validate_flow_execution(mock_client, template_data, \\\"test.json\\\", headers)\\n        assert errors == []\\n\\n        # Verify API calls\\n        assert mock_client.post.call_count == 2\\n        mock_client.get.assert_called_once()\\n        mock_client.delete.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_flow_creation_fails(self):\\n        \\\"\\\"\\\"Test validation fails when flow creation fails.\\\"\\\"\\\"\\n        mock_client = AsyncMock()\\n        create_response = Mock()\\n        create_response.status_code = 400\\n        mock_client.post.return_value = create_response\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        headers = {\\\"Authorization\\\": \\\"Bearer token\\\"}\\n\\n        errors = await validate_flow_execution(mock_client, template_data, \\\"test.json\\\", headers)\\n        assert len(errors) == 1\\n        assert \\\"Failed to create flow: 400\\\" in errors[0]\\n\\n    @pytest.mark.asyncio\\n    async def test_flow_build_fails(self):\\n        \\\"\\\"\\\"Test validation fails when flow build fails.\\\"\\\"\\\"\\n        mock_client = AsyncMock()\\n\\n        # Mock successful create\\n        create_response = Mock()\\n        create_response.status_code = 201\\n        create_response.json.return_value = {\\\"id\\\": \\\"flow123\\\"}\\n\\n        # Mock failed build\\n        build_response = Mock()\\n        build_response.status_code = 500\\n\\n        mock_client.post.side_effect = [create_response, build_response]\\n        mock_client.delete.return_value = Mock()\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        headers = {\\\"Authorization\\\": \\\"Bearer token\\\"}\\n\\n        errors = await validate_flow_execution(mock_client, template_data, \\\"test.json\\\", headers)\\n        assert len(errors) == 1\\n        assert \\\"Failed to build flow: 500\\\" in errors[0]\\n\\n    @pytest.mark.asyncio\\n    async def test_execution_timeout(self):\\n        \\\"\\\"\\\"Test validation fails when execution times out.\\\"\\\"\\\"\\n        mock_client = AsyncMock()\\n        mock_client.post.side_effect = asyncio.TimeoutError()\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        headers = {\\\"Authorization\\\": \\\"Bearer token\\\"}\\n\\n        errors = await validate_flow_execution(mock_client, template_data, \\\"test.json\\\", headers)\\n        assert len(errors) == 1\\n        assert \\\"Flow execution timed out\\\" in errors[0]\\n\\n    @pytest.mark.asyncio\\n    async def test_cleanup_on_exception(self):\\n        \\\"\\\"\\\"Test that flow cleanup happens even when exceptions occur.\\\"\\\"\\\"\\n        mock_client = AsyncMock()\\n\\n        # Mock successful create\\n        create_response = Mock()\\n        create_response.status_code = 201\\n        create_response.json.return_value = {\\\"id\\\": \\\"flow123\\\"}\\n\\n        # Mock build that raises exception\\n        mock_client.post.side_effect = [create_response, ValueError(\\\"Build error\\\")]\\n        mock_client.delete.return_value = Mock()\\n\\n        template_data = {\\\"nodes\\\": [], \\\"edges\\\": []}\\n        headers = {\\\"Authorization\\\": \\\"Bearer token\\\", \\\"timeout\\\": 10}\\n\\n        errors = await validate_flow_execution(mock_client, template_data, \\\"test.json\\\", headers)\\n        assert len(errors) == 1\\n        assert \\\"Flow execution validation failed: Build error\\\" in errors[0]\\n\\n        # Verify cleanup was called\\n        mock_client.delete.assert_called_once_with(\\\"api/v1/flows/flow123\\\", headers=headers, timeout=10)\\n\\n\\nclass TestValidateEventStream:\\n    \\\"\\\"\\\"Test cases for _validate_event_stream function.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_valid_event_stream(self):\\n        \\\"\\\"\\\"Test validation passes for valid event stream.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"vertices_sorted\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"ids\\\": [\\\"v1\\\", \\\"v2\\\"]}}',\\n                    '{\\\"event\\\": \\\"end_vertex\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"build_data\\\": {\\\"result\\\": \\\"success\\\"}}}',\\n                    '{\\\"event\\\": \\\"end_vertex\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"build_data\\\": {\\\"result\\\": \\\"success\\\"}}}',\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert errors == []\\n\\n    @pytest.mark.asyncio\\n    async def test_missing_end_event(self):\\n        \\\"\\\"\\\"Test validation fails when end event is missing.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                ['{\\\"event\\\": \\\"vertices_sorted\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"ids\\\": [\\\"v1\\\"]}}']\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert len(errors) == 1\\n        assert \\\"Missing end event in execution\\\" in errors[0]\\n\\n    @pytest.mark.asyncio\\n    async def test_job_id_mismatch(self):\\n        \\\"\\\"\\\"Test validation fails when job ID doesn't match.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"vertices_sorted\\\", \\\"job_id\\\": \\\"wrong_job\\\", \\\"data\\\": {\\\"ids\\\": [\\\"v1\\\"]}}',\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert len(errors) == 1\\n        assert \\\"Job ID mismatch in event stream\\\" in errors[0]\\n\\n    @pytest.mark.asyncio\\n    async def test_invalid_json_in_stream(self):\\n        \\\"\\\"\\\"Test validation handles invalid JSON in event stream.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock([\\\"invalid json\\\", '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}'])\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert len(errors) == 1\\n        assert \\\"Invalid JSON in event stream: invalid json\\\" in errors[0]\\n\\n    @pytest.mark.asyncio\\n    async def test_error_event_handling(self):\\n        \\\"\\\"\\\"Test validation handles error events properly.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"error\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"error\\\": \\\"Something went wrong\\\"}}',\\n                    '{\\\"event\\\": \\\"error\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"error\\\": \\\"False\\\"}}',  # Should be ignored\\n                    '{\\\"event\\\": \\\"error\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": \\\"String error\\\"}',\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert len(errors) == 2\\n        assert \\\"Flow execution error: Something went wrong\\\" in errors[0]\\n        assert \\\"Flow execution error: String error\\\" in errors[1]\\n\\n    @pytest.mark.asyncio\\n    async def test_missing_vertex_ids(self):\\n        \\\"\\\"\\\"Test validation fails when vertices_sorted event missing IDs.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"vertices_sorted\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {}}',\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert len(errors) == 1\\n        assert \\\"Missing vertex IDs in vertices_sorted event\\\" in errors[0]\\n\\n    @pytest.mark.asyncio\\n    async def test_missing_build_data(self):\\n        \\\"\\\"\\\"Test validation fails when end_vertex event missing build_data.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"end_vertex\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {}}',\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert len(errors) == 1\\n        assert \\\"Missing build_data in end_vertex event\\\" in errors[0]\\n\\n    @pytest.mark.asyncio\\n    async def test_event_stream_timeout(self):\\n        \\\"\\\"\\\"Test validation handles timeout gracefully.\\\"\\\"\\\"\\n\\n        class SlowAsyncIterator:\\n            \\\"\\\"\\\"Async iterator that will cause timeout.\\\"\\\"\\\"\\n\\n            def __aiter__(self):\\n                return self\\n\\n            async def __anext__(self):\\n                await asyncio.sleep(10)  # Will cause timeout\\n                return '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}'\\n\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(return_value=SlowAsyncIterator())\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert len(errors) == 1\\n        assert \\\"Flow execution timeout\\\" in errors[0]\\n\\n    @pytest.mark.asyncio\\n    async def test_common_event_types_ignored(self):\\n        \\\"\\\"\\\"Test that common event types don't cause errors.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"message\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                    '{\\\"event\\\": \\\"token\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                    '{\\\"event\\\": \\\"add_message\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                    '{\\\"event\\\": \\\"stream_closed\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert errors == []\\n\\n    @pytest.mark.asyncio\\n    async def test_vertices_sorted_without_end_vertex_events(self):\\n        \\\"\\\"\\\"Test validation with vertices_sorted but no end_vertex events.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"vertices_sorted\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"ids\\\": [\\\"v1\\\", \\\"v2\\\"]}}',\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert errors == []\\n\\n    @pytest.mark.asyncio\\n    async def test_vertex_count_tracking(self):\\n        \\\"\\\"\\\"Test that vertex_count is properly tracked.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"vertices_sorted\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"ids\\\": [\\\"v1\\\", \\\"v2\\\", \\\"v3\\\"]}}',\\n                    '{\\\"event\\\": \\\"end_vertex\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"build_data\\\": {\\\"result\\\": \\\"success\\\"}}}',\\n                    '{\\\"event\\\": \\\"end_vertex\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"build_data\\\": {\\\"result\\\": \\\"success\\\"}}}',\\n                    '{\\\"event\\\": \\\"end_vertex\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"build_data\\\": {\\\"result\\\": \\\"success\\\"}}}',\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert errors == []\\n\\n    @pytest.mark.asyncio\\n    async def test_empty_lines_in_stream(self):\\n        \\\"\\\"\\\"Test that empty lines in event stream are properly handled.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    \\\"\\\",  # Empty line\\n                    '{\\\"event\\\": \\\"vertices_sorted\\\", \\\"job_id\\\": \\\"job123\\\", \\\"data\\\": {\\\"ids\\\": [\\\"v1\\\"]}}',\\n                    \\\"\\\",  # Another empty line\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                    \\\"\\\",  # Empty line at end\\n                ]\\n            )\\n        )\\n\\n        errors = []\\n        await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n        assert errors == []\\n\\n    @pytest.mark.asyncio\\n    async def test_event_stream_validation_exception(self):\\n        \\\"\\\"\\\"Test that event stream validation handles exceptions properly.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.aiter_lines = Mock(\\n            return_value=AsyncIteratorMock(\\n                [\\n                    '{\\\"event\\\": \\\"end\\\", \\\"job_id\\\": \\\"job123\\\"}',\\n                ]\\n            )\\n        )\\n\\n        # Mock the json.loads to raise a different exception type\\n        errors = []\\n        with patch(\\\"langflow.utils.template_validation.json.loads\\\", side_effect=TypeError(\\\"Type error\\\")):\\n            await _validate_event_stream(mock_response, \\\"job123\\\", \\\"test.json\\\", errors)\\n            assert len(errors) == 1\\n            assert \\\"Event stream validation failed: Type error\\\" in errors[0]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_truncate_long_strings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f6a0dc4c08313372f33a87c2e6cc3f6ebda0edadae01bbb9ba241cea9e9b68d5\",\"content\":\"import math\\n\\nimport pytest\\nfrom langflow.serialization.constants import MAX_TEXT_LENGTH\\nfrom lfx.utils.util_strings import truncate_long_strings\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"input_data\\\", \\\"max_length\\\", \\\"expected\\\"),\\n    [\\n        # Test case 1: String shorter than max_length\\n        (\\\"short string\\\", 20, \\\"short string\\\"),\\n        # Test case 2: String exactly at max_length\\n        (\\\"exact\\\", 5, \\\"exact\\\"),\\n        # Test case 3: String longer than max_length\\n        (\\\"long string\\\", 7, \\\"long st...\\\"),\\n        # Test case 4: Empty string\\n        (\\\"\\\", 5, \\\"\\\"),\\n        # Test case 5: Single character string\\n        (\\\"a\\\", 1, \\\"a\\\"),\\n        # Test case 6: Unicode string\\n        (\\\"\u3053\u3093\u306b\u3061\u306f\\\", 3, \\\"\u3053\u3093\u306b...\\\"),\\n        # Test case 7: Integer input\\n        (12345, 3, 12345),\\n        # Test case 8: Float input\\n        (math.pi, 4, math.pi),\\n        # Test case 9: Boolean input\\n        (True, 2, True),\\n        # Test case 10: None input\\n        (None, 5, None),\\n        # Test case 11: Very long string\\n        (\\\"a\\\" * 1000, 10, \\\"a\\\" * 10 + \\\"...\\\"),\\n    ],\\n)\\ndef test_truncate_long_strings_non_dict_list(input_data, max_length, expected):\\n    result = truncate_long_strings(input_data, max_length)\\n    assert result == expected\\n\\n\\n# Test for max_length of 0\\ndef test_truncate_long_strings_zero_max_length():\\n    assert truncate_long_strings(\\\"any string\\\", 0) == \\\"...\\\"\\n\\n\\n# Test for negative max_length\\ndef test_truncate_long_strings_negative_max_length():\\n    assert truncate_long_strings(\\\"any string\\\", -1) == \\\"any string\\\"\\n\\n\\n# Test for None max_length (should use default MAX_TEXT_LENGTH)\\ndef test_truncate_long_strings_none_max_length():\\n    long_string = \\\"a\\\" * (MAX_TEXT_LENGTH + 10)\\n    result = truncate_long_strings(long_string, None)\\n    assert len(result) == MAX_TEXT_LENGTH + 3  # +3 for \\\"...\\\"\\n    assert result == \\\"a\\\" * MAX_TEXT_LENGTH + \\\"...\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_truncate_long_strings_on_objects.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c1ef3b916f406583ea79be523f97d2bef426ef24df1c3e0be8b8b2884bbf95f5\",\"content\":\"import pytest\\nfrom langflow.serialization.constants import MAX_TEXT_LENGTH\\nfrom lfx.utils.util_strings import truncate_long_strings\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"input_data\\\", \\\"max_length\\\", \\\"expected\\\"),\\n    [\\n        # Test case 1: Simple string truncation\\n        ({\\\"key\\\": \\\"a\\\" * 100}, 10, {\\\"key\\\": \\\"a\\\" * 10 + \\\"...\\\"}),\\n        # Test case 2: Nested dictionary\\n        ({\\\"outer\\\": {\\\"inner\\\": \\\"b\\\" * 100}}, 5, {\\\"outer\\\": {\\\"inner\\\": \\\"b\\\" * 5 + \\\"...\\\"}}),\\n        # Test case 3: List of strings\\n        ([\\\"short\\\", \\\"a\\\" * 100, \\\"also short\\\"], 7, [\\\"short\\\", \\\"a\\\" * 7 + \\\"...\\\", \\\"also sh\\\" + \\\"...\\\"]),\\n        # Test case 4: Mixed nested structure\\n        (\\n            {\\\"key1\\\": [\\\"a\\\" * 100, {\\\"nested\\\": \\\"b\\\" * 100}], \\\"key2\\\": \\\"c\\\" * 100},\\n            8,\\n            {\\\"key1\\\": [\\\"a\\\" * 8 + \\\"...\\\", {\\\"nested\\\": \\\"b\\\" * 8 + \\\"...\\\"}], \\\"key2\\\": \\\"c\\\" * 8 + \\\"...\\\"},\\n        ),\\n        # Test case 5: Empty structures\\n        ({}, 10, {}),\\n        ([], 10, []),\\n        # Test case 6: Strings at exact max_length\\n        ({\\\"exact\\\": \\\"a\\\" * 10}, 10, {\\\"exact\\\": \\\"a\\\" * 10}),\\n        # Test case 7: Non-string values\\n        ({\\\"num\\\": 12345, \\\"bool\\\": True, \\\"none\\\": None}, 5, {\\\"num\\\": 12345, \\\"bool\\\": True, \\\"none\\\": None}),\\n        # Test case 8: Unicode characters\\n        ({\\\"unicode\\\": \\\"\u3053\u3093\u306b\u3061\u306f\u4e16\u754c\\\"}, 3, {\\\"unicode\\\": \\\"\u3053\u3093\u306b...\\\"}),\\n        # Test case 9: Very large structure\\n        (\\n            {\\\"key\\\" + str(i): \\\"value\\\" * i for i in range(1000)},\\n            10,\\n            {\\\"key\\\" + str(i): (\\\"value\\\" * i)[:10] + \\\"...\\\" if len(\\\"value\\\" * i) > 10 else \\\"value\\\" * i for i in range(1000)},\\n        ),\\n    ],\\n)\\ndef test_truncate_long_strings(input_data, max_length, expected):\\n    result = truncate_long_strings(input_data, max_length)\\n    assert result == expected\\n\\n\\ndef test_truncate_long_strings_default_max_length():\\n    long_string = \\\"a\\\" * (MAX_TEXT_LENGTH + 1)\\n    input_data = {\\\"key\\\": long_string}\\n    result = truncate_long_strings(input_data)\\n    assert len(result[\\\"key\\\"]) == MAX_TEXT_LENGTH + 3  # +3 for the \\\"...\\\"\\n\\n\\ndef test_truncate_long_strings_no_modification():\\n    input_data = {\\\"short\\\": \\\"short string\\\", \\\"nested\\\": {\\\"also_short\\\": \\\"another short string\\\"}}\\n    result = truncate_long_strings(input_data, 100)\\n    assert result == input_data\\n\\n\\n# Test for type preservation\\ndef test_truncate_long_strings_type_preservation():\\n    input_data = {\\\"str\\\": \\\"a\\\" * 100, \\\"list\\\": [\\\"b\\\" * 100], \\\"dict\\\": {\\\"nested\\\": \\\"c\\\" * 100}}\\n    result = truncate_long_strings(input_data, 10)\\n    assert isinstance(result, dict)\\n    assert isinstance(result[\\\"str\\\"], str)\\n    assert isinstance(result[\\\"list\\\"], list)\\n    assert isinstance(result[\\\"dict\\\"], dict)\\n\\n\\n# Test for in-place modification\\ndef test_truncate_long_strings_in_place_modification():\\n    input_data = {\\\"key\\\": \\\"a\\\" * 100}\\n    result = truncate_long_strings(input_data, 10)\\n    assert result is input_data  # Check if the same object is returned\\n\\n\\n# Test for invalid input\\ndef test_truncate_long_strings_invalid_input():\\n    input_string = \\\"not a dict or list\\\"\\n    result = truncate_long_strings(input_string, 10)\\n    assert result == \\\"not a dict...\\\"  # The function should truncate the string\\n\\n\\n# Updated test for negative max_length\\ndef test_truncate_long_strings_negative_max_length():\\n    input_data = {\\\"key\\\": \\\"value\\\"}\\n    result = truncate_long_strings(input_data, -1)\\n    assert result == input_data  # Assuming the function ignores negative max_length\\n\\n\\n# Additional test for zero max_length\\ndef test_truncate_long_strings_zero_max_length():\\n    input_data = {\\\"key\\\": \\\"value\\\"}\\n    result = truncate_long_strings(input_data, 0)\\n    assert result == {\\\"key\\\": \\\"...\\\"}  # Assuming the function truncates to just \\\"...\\\"\\n\\n\\n# Test for very small positive max_length\\ndef test_truncate_long_strings_small_max_length():\\n    input_data = {\\\"key\\\": \\\"value\\\"}\\n    result = truncate_long_strings(input_data, 1)\\n    assert result == {\\\"key\\\": \\\"v...\\\"}  # Assuming the function keeps at least one character\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_util.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"852400ef4bea7fa2fc2292a43144bea4a416fbb4c7dd525cd239f533f9089952\",\"content\":\"import inspect\\nfrom unittest.mock import Mock, patch\\n\\nimport pytest\\nfrom langflow.schema.data import Data\\nfrom langflow.utils.util import (\\n    add_options_to_field,\\n    build_loader_repr_from_data,\\n    build_template_from_function,\\n    build_template_from_method,\\n    check_list_type,\\n    escape_json_dump,\\n    find_closest_match,\\n    format_dict,\\n    get_base_classes,\\n    get_default_factory,\\n    get_formatted_type,\\n    get_type,\\n    get_type_from_union_literal,\\n    is_class_method,\\n    is_multiline_field,\\n    is_password_field,\\n    remove_ansi_escape_codes,\\n    remove_optional_wrapper,\\n    replace_default_value_with_actual,\\n    replace_mapping_with_dict,\\n    set_dict_file_attributes,\\n    set_headers_value,\\n    should_show_field,\\n    sync_to_async,\\n    unescape_string,\\n    update_settings,\\n    update_verbose,\\n)\\n\\n\\nclass TestUnescapeString:\\n    \\\"\\\"\\\"Test cases for unescape_string function.\\\"\\\"\\\"\\n\\n    def test_unescape_single_newline(self):\\n        \\\"\\\"\\\"Test unescaping single newline character.\\\"\\\"\\\"\\n        result = unescape_string(\\\"Line 1\\\\\\\\nLine 2\\\")\\n        assert result == \\\"Line 1\\\\nLine 2\\\"\\n\\n    def test_unescape_multiple_newlines(self):\\n        \\\"\\\"\\\"Test unescaping multiple newline characters.\\\"\\\"\\\"\\n        result = unescape_string(\\\"Line 1\\\\\\\\nLine 2\\\\\\\\nLine 3\\\")\\n        assert result == \\\"Line 1\\\\nLine 2\\\\nLine 3\\\"\\n\\n    def test_unescape_no_newlines(self):\\n        \\\"\\\"\\\"Test string with no newline characters.\\\"\\\"\\\"\\n        result = unescape_string(\\\"Simple string\\\")\\n        assert result == \\\"Simple string\\\"\\n\\n    def test_unescape_empty_string(self):\\n        \\\"\\\"\\\"Test empty string.\\\"\\\"\\\"\\n        result = unescape_string(\\\"\\\")\\n        assert result == \\\"\\\"\\n\\n    def test_unescape_mixed_content(self):\\n        \\\"\\\"\\\"Test string with mixed content including newlines.\\\"\\\"\\\"\\n        result = unescape_string(\\\"Hello\\\\\\\\nWorld\\\\\\\\nThis is a test\\\")\\n        assert result == \\\"Hello\\\\nWorld\\\\nThis is a test\\\"\\n\\n\\nclass TestRemoveAnsiEscapeCodes:\\n    \\\"\\\"\\\"Test cases for remove_ansi_escape_codes function.\\\"\\\"\\\"\\n\\n    def test_remove_color_codes(self):\\n        \\\"\\\"\\\"Test removing ANSI color escape codes.\\\"\\\"\\\"\\n        text_with_colors = \\\"\\\\x1b[31mRed text\\\\x1b[0m\\\"\\n        result = remove_ansi_escape_codes(text_with_colors)\\n        assert result == \\\"Red text\\\"\\n\\n    def test_remove_multiple_codes(self):\\n        \\\"\\\"\\\"Test removing multiple ANSI escape codes.\\\"\\\"\\\"\\n        text = \\\"\\\\x1b[1m\\\\x1b[31mBold Red\\\\x1b[0m\\\\x1b[32mGreen\\\\x1b[0m\\\"\\n        result = remove_ansi_escape_codes(text)\\n        assert result == \\\"Bold RedGreen\\\"\\n\\n    def test_no_escape_codes(self):\\n        \\\"\\\"\\\"Test text without ANSI escape codes.\\\"\\\"\\\"\\n        plain_text = \\\"Plain text without codes\\\"\\n        result = remove_ansi_escape_codes(plain_text)\\n        assert result == plain_text\\n\\n    def test_empty_string(self):\\n        \\\"\\\"\\\"Test empty string.\\\"\\\"\\\"\\n        result = remove_ansi_escape_codes(\\\"\\\")\\n        assert result == \\\"\\\"\\n\\n    def test_complex_ansi_codes(self):\\n        \\\"\\\"\\\"Test complex ANSI escape sequences.\\\"\\\"\\\"\\n        complex_text = \\\"\\\\x1b[1;4;31mBold underlined red\\\\x1b[0m normal text\\\"\\n        result = remove_ansi_escape_codes(complex_text)\\n        assert result == \\\"Bold underlined red normal text\\\"\\n\\n\\nclass TestBuildTemplateFromFunction:\\n    \\\"\\\"\\\"Test cases for build_template_from_function function.\\\"\\\"\\\"\\n\\n    def test_function_not_found(self):\\n        \\\"\\\"\\\"Test when function name is not in type_to_loader_dict.\\\"\\\"\\\"\\n        type_dict = {}\\n\\n        with pytest.raises(ValueError, match=\\\"TestName not found\\\"):\\n            build_template_from_function(\\\"TestName\\\", type_dict)\\n\\n    @patch(\\\"lfx.utils.util.parse\\\")\\n    @patch(\\\"lfx.utils.util.get_default_factory\\\")\\n    @patch(\\\"lfx.utils.util.get_base_classes\\\")\\n    @patch(\\\"lfx.utils.util.format_dict\\\")\\n    def test_successful_template_build(\\n        self, mock_format_dict, mock_get_base_classes, mock_get_default_factory, mock_parse\\n    ):\\n        \\\"\\\"\\\"Test successful template building.\\\"\\\"\\\"\\n        # Mock class with model_fields\\n        mock_class = Mock()\\n        mock_class.__name__ = \\\"TestClass\\\"\\n        # Create a mock base class with __module__\\n        mock_base = Mock()\\n        mock_base.__module__ = \\\"test.module\\\"\\n        mock_class.__base__ = mock_base\\n        mock_class.model_fields = {\\n            \\\"field1\\\": Mock(),\\n            \\\"callback_manager\\\": Mock(),  # Should be skipped\\n        }\\n\\n        # Mock field representation\\n        field_mock = mock_class.model_fields[\\\"field1\\\"]\\n        field_mock.__repr_args__ = Mock(return_value=[(\\\"default_factory\\\", \\\"test_factory\\\")])\\n\\n        # Mock loader function\\n        mock_loader = Mock()\\n        mock_loader.__annotations__ = {\\\"return\\\": mock_class}\\n\\n        type_dict = {\\\"test_type\\\": mock_loader}\\n\\n        # Mock dependencies\\n        mock_parse.return_value = Mock(short_description=\\\"Test description\\\", params={})\\n        mock_get_default_factory.return_value = \\\"default_value\\\"\\n        mock_get_base_classes.return_value = [\\\"BaseClass\\\"]\\n        mock_format_dict.return_value = {\\\"formatted\\\": \\\"dict\\\"}\\n\\n        result = build_template_from_function(\\\"TestClass\\\", type_dict)\\n\\n        assert result[\\\"template\\\"] == {\\\"formatted\\\": \\\"dict\\\"}\\n        assert result[\\\"description\\\"] == \\\"Test description\\\"\\n        assert result[\\\"base_classes\\\"] == [\\\"BaseClass\\\"]\\n\\n    def test_add_function_base_class(self):\\n        \\\"\\\"\\\"Test adding 'Callable' to base classes when add_function=True.\\\"\\\"\\\"\\n        mock_class = Mock()\\n        mock_class.__name__ = \\\"TestClass\\\"\\n        mock_class.model_fields = {}\\n\\n        mock_loader = Mock()\\n        mock_loader.__annotations__ = {\\\"return\\\": mock_class}\\n\\n        type_dict = {\\\"test_type\\\": mock_loader}\\n\\n        with (\\n            patch(\\\"lfx.utils.util.parse\\\") as mock_parse,\\n            patch(\\\"lfx.utils.util.get_base_classes\\\") as mock_get_base_classes,\\n            patch(\\\"lfx.utils.util.format_dict\\\") as mock_format_dict,\\n        ):\\n            mock_parse.return_value = Mock(short_description=\\\"Test\\\", params={})\\n            mock_get_base_classes.return_value = [\\\"BaseClass\\\"]\\n            mock_format_dict.return_value = {}\\n\\n            result = build_template_from_function(\\\"TestClass\\\", type_dict, add_function=True)\\n\\n            assert \\\"Callable\\\" in result[\\\"base_classes\\\"]\\n\\n\\nclass TestBuildTemplateFromMethod:\\n    \\\"\\\"\\\"Test cases for build_template_from_method function.\\\"\\\"\\\"\\n\\n    def test_class_not_found(self):\\n        \\\"\\\"\\\"Test when class name is not in type_to_cls_dict.\\\"\\\"\\\"\\n        type_dict = {}\\n\\n        with pytest.raises(ValueError, match=\\\"TestClass not found\\\"):\\n            build_template_from_method(\\\"TestClass\\\", \\\"test_method\\\", type_dict)\\n\\n    def test_method_not_found(self):\\n        \\\"\\\"\\\"Test when method doesn't exist in class.\\\"\\\"\\\"\\n        mock_class = Mock()\\n        mock_class.__name__ = \\\"TestClass\\\"\\n        # Mock hasattr to return False\\n\\n        type_dict = {\\\"test_type\\\": mock_class}\\n\\n        with (\\n            patch(\\\"builtins.hasattr\\\", return_value=False),\\n            pytest.raises(ValueError, match=\\\"Method test_method not found in class TestClass\\\"),\\n        ):\\n            build_template_from_method(\\\"TestClass\\\", \\\"test_method\\\", type_dict)\\n\\n    @patch(\\\"lfx.utils.util.parse\\\")\\n    @patch(\\\"lfx.utils.util.get_base_classes\\\")\\n    @patch(\\\"lfx.utils.util.format_dict\\\")\\n    def test_successful_method_template_build(self, mock_format_dict, mock_get_base_classes, mock_parse):\\n        \\\"\\\"\\\"Test successful method template building.\\\"\\\"\\\"\\n        # Create mock class with method\\n        mock_class = Mock()\\n        mock_class.__name__ = \\\"TestClass\\\"\\n\\n        # Create mock method with signature\\n        mock_method = Mock()\\n        mock_method.__doc__ = \\\"Test method\\\"\\n\\n        # Mock method signature\\n        param1 = Mock()\\n        param1.default = inspect.Parameter.empty\\n        param1.annotation = str\\n        param2 = Mock()\\n        param2.default = \\\"default_value\\\"\\n        param2.annotation = int\\n\\n        mock_sig = Mock()\\n        mock_sig.parameters = {\\n            \\\"self\\\": Mock(),  # Should be ignored\\n            \\\"param1\\\": param1,\\n            \\\"param2\\\": param2,\\n        }\\n\\n        mock_class.test_method = mock_method\\n\\n        type_dict = {\\\"test_type\\\": mock_class}\\n\\n        with patch(\\\"inspect.signature\\\", return_value=mock_sig):\\n            mock_parse.return_value = Mock(short_description=\\\"Test description\\\")\\n            mock_get_base_classes.return_value = [\\\"BaseClass\\\"]\\n            mock_format_dict.return_value = {\\\"formatted\\\": \\\"method_dict\\\"}\\n\\n            result = build_template_from_method(\\\"TestClass\\\", \\\"test_method\\\", type_dict)\\n\\n            assert result[\\\"template\\\"] == {\\\"formatted\\\": \\\"method_dict\\\"}\\n            assert result[\\\"description\\\"] == \\\"Test description\\\"\\n            assert result[\\\"base_classes\\\"] == [\\\"BaseClass\\\"]\\n\\n\\nclass TestGetBaseClasses:\\n    \\\"\\\"\\\"Test cases for get_base_classes function.\\\"\\\"\\\"\\n\\n    def test_class_with_bases(self):\\n        \\\"\\\"\\\"Test class with base classes.\\\"\\\"\\\"\\n\\n        class TestBase:\\n            pass\\n\\n        class TestClass(TestBase):\\n            pass\\n\\n        # Mock __module__ to avoid pydantic/abc filtering\\n        TestBase.__module__ = \\\"test.module\\\"\\n\\n        result = get_base_classes(TestClass)\\n\\n        assert \\\"TestClass\\\" in result\\n        assert \\\"TestBase\\\" in result\\n\\n    def test_class_without_bases(self):\\n        \\\"\\\"\\\"Test class without base classes.\\\"\\\"\\\"\\n\\n        class TestClass:\\n            pass\\n\\n        result = get_base_classes(TestClass)\\n\\n        # Should include both object and TestClass\\n        assert \\\"TestClass\\\" in result\\n        assert len(result) >= 1\\n\\n    def test_filtered_base_classes(self):\\n        \\\"\\\"\\\"Test that pydantic and abc bases are filtered out.\\\"\\\"\\\"\\n        # Create mock class with filtered bases\\n        mock_base = Mock()\\n        mock_base.__name__ = \\\"FilteredBase\\\"\\n        mock_base.__module__ = \\\"pydantic.main\\\"\\n\\n        mock_class = Mock()\\n        mock_class.__name__ = \\\"TestClass\\\"\\n        mock_class.__bases__ = (mock_base,)\\n\\n        result = get_base_classes(mock_class)\\n\\n        assert \\\"TestClass\\\" in result\\n        assert \\\"FilteredBase\\\" not in result\\n\\n\\nclass TestGetDefaultFactory:\\n    \\\"\\\"\\\"Test cases for get_default_factory function.\\\"\\\"\\\"\\n\\n    def test_valid_function_pattern(self):\\n        \\\"\\\"\\\"Test extracting function from valid pattern.\\\"\\\"\\\"\\n        with patch(\\\"importlib.import_module\\\") as mock_import, patch(\\\"warnings.catch_warnings\\\"):\\n            mock_module = Mock()\\n            mock_module.test_function = Mock(return_value=\\\"factory_result\\\")\\n            mock_import.return_value = mock_module\\n\\n            result = get_default_factory(\\\"test.module\\\", \\\"<function test_function>\\\")\\n\\n            assert result == \\\"factory_result\\\"\\n            # importlib.import_module might be called multiple times due to warnings imports\\n            # Just check that test.module was called\\n            calls = [call[0][0] for call in mock_import.call_args_list]\\n            assert \\\"test.module\\\" in calls\\n\\n    def test_invalid_pattern(self):\\n        \\\"\\\"\\\"Test with invalid function pattern.\\\"\\\"\\\"\\n        result = get_default_factory(\\\"test.module\\\", \\\"invalid_pattern\\\")\\n        assert result is None\\n\\n    def test_import_error(self):\\n        \\\"\\\"\\\"Test handling import error.\\\"\\\"\\\"\\n        # The function doesn't explicitly handle import errors, so it will propagate\\n        with pytest.raises((ImportError, ModuleNotFoundError)):\\n            get_default_factory(\\\"nonexistent.module\\\", \\\"<function test_function>\\\")\\n\\n\\nclass TestUpdateVerbose:\\n    \\\"\\\"\\\"Test cases for update_verbose function.\\\"\\\"\\\"\\n\\n    def test_update_nested_verbose(self):\\n        \\\"\\\"\\\"Test updating verbose in nested dictionary.\\\"\\\"\\\"\\n        test_dict = {\\\"level1\\\": {\\\"verbose\\\": False, \\\"level2\\\": {\\\"verbose\\\": True, \\\"other_key\\\": \\\"value\\\"}}, \\\"verbose\\\": False}\\n\\n        result = update_verbose(test_dict, new_value=True)\\n\\n        assert result[\\\"verbose\\\"] is True\\n        assert result[\\\"level1\\\"][\\\"verbose\\\"] is True\\n        assert result[\\\"level1\\\"][\\\"level2\\\"][\\\"verbose\\\"] is True\\n        assert result[\\\"level1\\\"][\\\"level2\\\"][\\\"other_key\\\"] == \\\"value\\\"\\n\\n    def test_no_verbose_keys(self):\\n        \\\"\\\"\\\"Test dictionary without verbose keys.\\\"\\\"\\\"\\n        test_dict = {\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": {\\\"nested\\\": \\\"value\\\"}}\\n\\n        result = update_verbose(test_dict, new_value=True)\\n\\n        assert result == test_dict\\n\\n    def test_empty_dict(self):\\n        \\\"\\\"\\\"Test empty dictionary.\\\"\\\"\\\"\\n        test_dict = {}\\n\\n        result = update_verbose(test_dict, new_value=True)\\n\\n        assert result == {}\\n\\n\\nclass TestSyncToAsync:\\n    \\\"\\\"\\\"Test cases for sync_to_async decorator.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_sync_to_async_decorator(self):\\n        \\\"\\\"\\\"Test converting sync function to async.\\\"\\\"\\\"\\n\\n        @sync_to_async\\n        def sync_function(x, y):\\n            return x + y\\n\\n        result = await sync_function(2, 3)\\n        assert result == 5\\n\\n    @pytest.mark.asyncio\\n    async def test_sync_to_async_with_kwargs(self):\\n        \\\"\\\"\\\"Test sync to async with keyword arguments.\\\"\\\"\\\"\\n\\n        @sync_to_async\\n        def sync_function(x, y=10):\\n            return x * y\\n\\n        result = await sync_function(5, y=4)\\n        assert result == 20\\n\\n    @pytest.mark.asyncio\\n    async def test_sync_to_async_exception(self):\\n        \\\"\\\"\\\"Test sync to async with exception.\\\"\\\"\\\"\\n\\n        @sync_to_async\\n        def failing_function():\\n            msg = \\\"Test error\\\"\\n            raise ValueError(msg)\\n\\n        with pytest.raises(ValueError, match=\\\"Test error\\\"):\\n            await failing_function()\\n\\n\\nclass TestFormatDict:\\n    \\\"\\\"\\\"Test cases for format_dict function.\\\"\\\"\\\"\\n\\n    def test_format_dict_basic(self):\\n        \\\"\\\"\\\"Test basic dictionary formatting.\\\"\\\"\\\"\\n        test_dict = {\\\"_type\\\": \\\"test_type\\\", \\\"field1\\\": {\\\"type\\\": \\\"str\\\", \\\"required\\\": True}}\\n\\n        with (\\n            patch(\\\"lfx.utils.util.get_type\\\") as mock_get_type,\\n            patch(\\\"lfx.utils.util.should_show_field\\\") as mock_show,\\n            patch(\\\"lfx.utils.util.is_password_field\\\") as mock_password,\\n            patch(\\\"lfx.utils.util.is_multiline_field\\\") as mock_multiline,\\n        ):\\n            mock_get_type.return_value = \\\"str\\\"\\n            mock_show.return_value = True\\n            mock_password.return_value = False\\n            mock_multiline.return_value = False\\n\\n            result = format_dict(test_dict)\\n\\n            assert \\\"_type\\\" in result\\n            assert result[\\\"field1\\\"][\\\"type\\\"] == \\\"str\\\"\\n            assert result[\\\"field1\\\"][\\\"show\\\"] is True\\n            assert result[\\\"field1\\\"][\\\"password\\\"] is False\\n            assert result[\\\"field1\\\"][\\\"multiline\\\"] is False\\n\\n    def test_format_dict_skips_basemodel(self):\\n        \\\"\\\"\\\"Test that BaseModel types are skipped.\\\"\\\"\\\"\\n        test_dict = {\\\"field1\\\": {\\\"type\\\": \\\"SomeBaseModel\\\"}}\\n\\n        with patch(\\\"langflow.utils.util.get_type\\\", return_value=\\\"SomeBaseModel\\\"):\\n            result = format_dict(test_dict)\\n\\n            # BaseModel fields are continued/skipped, so they retain original structure\\n            # Check that the field wasn't processed by looking for formatting indicators\\n            field_dict = result.get(\\\"field1\\\", {})\\n            assert \\\"show\\\" not in field_dict or \\\"password\\\" not in field_dict\\n\\n\\nclass TestGetTypeFromUnionLiteral:\\n    \\\"\\\"\\\"Test cases for get_type_from_union_literal function.\\\"\\\"\\\"\\n\\n    def test_literal_union_to_str(self):\\n        \\\"\\\"\\\"Test converting Union[Literal[...]] to str.\\\"\\\"\\\"\\n        union_type = \\\"Union[Literal['option1'], Literal['option2']]\\\"\\n        result = get_type_from_union_literal(union_type)\\n        assert result == \\\"str\\\"\\n\\n    def test_non_literal_unchanged(self):\\n        \\\"\\\"\\\"Test non-literal types remain unchanged.\\\"\\\"\\\"\\n        non_literal = \\\"Union[str, int]\\\"\\n        result = get_type_from_union_literal(non_literal)\\n        assert result == non_literal\\n\\n    def test_simple_type_unchanged(self):\\n        \\\"\\\"\\\"Test simple types remain unchanged.\\\"\\\"\\\"\\n        simple_type = \\\"str\\\"\\n        result = get_type_from_union_literal(simple_type)\\n        assert result == simple_type\\n\\n\\nclass TestGetType:\\n    \\\"\\\"\\\"Test cases for get_type function.\\\"\\\"\\\"\\n\\n    def test_get_type_from_dict(self):\\n        \\\"\\\"\\\"Test getting type from dictionary.\\\"\\\"\\\"\\n        value = {\\\"type\\\": \\\"str\\\"}\\n        result = get_type(value)\\n        assert result == \\\"str\\\"\\n\\n    def test_get_annotation_from_dict(self):\\n        \\\"\\\"\\\"Test getting annotation from dictionary.\\\"\\\"\\\"\\n        value = {\\\"annotation\\\": int}\\n        result = get_type(value)\\n        assert result == \\\"int\\\"\\n\\n    def test_get_type_object(self):\\n        \\\"\\\"\\\"Test getting type from type object.\\\"\\\"\\\"\\n        value = {\\\"type\\\": str}\\n        result = get_type(value)\\n        assert result == \\\"str\\\"\\n\\n    def test_empty_value(self):\\n        \\\"\\\"\\\"Test empty value dictionary.\\\"\\\"\\\"\\n        value = {}\\n        # This will cause an AttributeError in the actual implementation\\n        # when get_type tries to call __name__ on None\\n        with pytest.raises(AttributeError):\\n            get_type(value)\\n\\n\\nclass TestUtilityFunctions:\\n    \\\"\\\"\\\"Test cases for various utility functions.\\\"\\\"\\\"\\n\\n    def test_remove_optional_wrapper(self):\\n        \\\"\\\"\\\"Test removing Optional wrapper from type string.\\\"\\\"\\\"\\n        optional_type = \\\"Optional[str]\\\"\\n        result = remove_optional_wrapper(optional_type)\\n        assert result == \\\"str\\\"\\n\\n        non_optional = \\\"str\\\"\\n        result = remove_optional_wrapper(non_optional)\\n        assert result == \\\"str\\\"\\n\\n    def test_check_list_type(self):\\n        \\\"\\\"\\\"Test checking and modifying list types.\\\"\\\"\\\"\\n        value = {}\\n\\n        # Test List type\\n        result = check_list_type(\\\"List[str]\\\", value)\\n        assert result == \\\"str\\\"\\n        assert value[\\\"list\\\"] is True\\n\\n        # Test non-list type\\n        value = {}\\n        result = check_list_type(\\\"str\\\", value)\\n        assert result == \\\"str\\\"\\n        assert value[\\\"list\\\"] is False\\n\\n    def test_replace_mapping_with_dict(self):\\n        \\\"\\\"\\\"Test replacing Mapping with dict.\\\"\\\"\\\"\\n        mapping_type = \\\"Mapping[str, Any]\\\"\\n        result = replace_mapping_with_dict(mapping_type)\\n        assert result == \\\"dict[str, Any]\\\"\\n\\n    def test_get_formatted_type(self):\\n        \\\"\\\"\\\"Test type formatting for specific keys.\\\"\\\"\\\"\\n        assert get_formatted_type(\\\"allowed_tools\\\", \\\"Any\\\") == \\\"Tool\\\"\\n        assert get_formatted_type(\\\"max_value_length\\\", \\\"Any\\\") == \\\"int\\\"\\n        assert get_formatted_type(\\\"other_field\\\", \\\"str\\\") == \\\"str\\\"\\n\\n    def test_should_show_field(self):\\n        \\\"\\\"\\\"Test field visibility logic.\\\"\\\"\\\"\\n        # Required field should show\\n        assert should_show_field({\\\"required\\\": True}, \\\"test_field\\\") is True\\n\\n        # Password field should show\\n        assert should_show_field({\\\"required\\\": False}, \\\"password_field\\\") is True\\n\\n        # Non-required, non-special field shouldn't show\\n        assert should_show_field({\\\"required\\\": False}, \\\"regular_field\\\") is False\\n\\n    def test_is_password_field(self):\\n        \\\"\\\"\\\"Test password field detection.\\\"\\\"\\\"\\n        assert is_password_field(\\\"password\\\") is True\\n        assert is_password_field(\\\"api_key\\\") is True\\n        assert is_password_field(\\\"token\\\") is True\\n        assert is_password_field(\\\"regular_field\\\") is False\\n\\n    def test_is_multiline_field(self):\\n        \\\"\\\"\\\"Test multiline field detection.\\\"\\\"\\\"\\n        assert is_multiline_field(\\\"template\\\") is True\\n        assert is_multiline_field(\\\"code\\\") is True\\n        assert is_multiline_field(\\\"headers\\\") is True\\n        assert is_multiline_field(\\\"regular_field\\\") is False\\n\\n    def test_set_dict_file_attributes(self):\\n        \\\"\\\"\\\"Test setting file attributes for dict fields.\\\"\\\"\\\"\\n        value = {}\\n        set_dict_file_attributes(value)\\n\\n        assert value[\\\"type\\\"] == \\\"file\\\"\\n        assert value[\\\"fileTypes\\\"] == [\\\".json\\\", \\\".yaml\\\", \\\".yml\\\"]\\n\\n    def test_replace_default_value_with_actual(self):\\n        \\\"\\\"\\\"Test replacing default with value.\\\"\\\"\\\"\\n        value = {\\\"default\\\": \\\"test_value\\\", \\\"other\\\": \\\"data\\\"}\\n        replace_default_value_with_actual(value)\\n\\n        assert value[\\\"value\\\"] == \\\"test_value\\\"\\n        assert \\\"default\\\" not in value\\n        assert value[\\\"other\\\"] == \\\"data\\\"\\n\\n    def test_set_headers_value(self):\\n        \\\"\\\"\\\"Test setting headers value.\\\"\\\"\\\"\\n        value = {}\\n        set_headers_value(value)\\n\\n        assert value[\\\"value\\\"] == \\\"\\\"\\\"{\\\"Authorization\\\": \\\"Bearer <token>\\\"}\\\"\\\"\\\"\\n\\n    def test_add_options_to_field(self):\\n        \\\"\\\"\\\"Test adding options to specific fields.\\\"\\\"\\\"\\n        value = {}\\n\\n        with patch(\\\"lfx.utils.util.constants\\\") as mock_constants:\\n            mock_constants.OPENAI_MODELS = [\\\"gpt-3.5-turbo\\\", \\\"gpt-4\\\"]\\n\\n            add_options_to_field(value, \\\"OpenAI\\\", \\\"model_name\\\")\\n\\n            assert value[\\\"options\\\"] == [\\\"gpt-3.5-turbo\\\", \\\"gpt-4\\\"]\\n            assert value[\\\"list\\\"] is True\\n            assert value[\\\"value\\\"] == \\\"gpt-3.5-turbo\\\"\\n\\n\\nclass TestBuildLoaderReprFromData:\\n    \\\"\\\"\\\"Test cases for build_loader_repr_from_data function.\\\"\\\"\\\"\\n\\n    def test_build_repr_with_data(self):\\n        \\\"\\\"\\\"Test building representation with data.\\\"\\\"\\\"\\n        mock_data1 = Mock(spec=Data)\\n        mock_data1.text = \\\"Short text\\\"\\n        mock_data2 = Mock(spec=Data)\\n        mock_data2.text = \\\"This is a longer text content\\\"\\n\\n        data_list = [mock_data1, mock_data2]\\n\\n        result = build_loader_repr_from_data(data_list)\\n\\n        assert \\\"2 data\\\" in result\\n        assert \\\"Avg. Data Length\\\" in result\\n        assert \\\"Data:\\\" in result\\n\\n    def test_build_repr_empty_data(self):\\n        \\\"\\\"\\\"Test building representation with empty data.\\\"\\\"\\\"\\n        result = build_loader_repr_from_data([])\\n        assert result == \\\"0 data\\\"\\n\\n    def test_build_repr_none_data(self):\\n        \\\"\\\"\\\"Test building representation with None data.\\\"\\\"\\\"\\n        result = build_loader_repr_from_data(None)\\n        assert result == \\\"0 data\\\"\\n\\n\\nclass TestUpdateSettings:\\n    \\\"\\\"\\\"Test cases for update_settings function.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx.utils.util.get_settings_service\\\")\\n    async def test_update_settings_basic(self, mock_get_service):\\n        \\\"\\\"\\\"Test basic settings update.\\\"\\\"\\\"\\n        mock_service = Mock()\\n        mock_settings = Mock()\\n        mock_service.settings = mock_settings\\n        mock_get_service.return_value = mock_service\\n\\n        await update_settings(cache=\\\"redis\\\")\\n\\n        # Verify the service was called and update_settings was called\\n        mock_get_service.assert_called_once()\\n        # The function calls update_settings multiple times with different parameters\\n        assert mock_settings.update_settings.called\\n        # Check that our specific call was made\\n        mock_settings.update_settings.assert_any_call(cache=\\\"redis\\\")\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx.utils.util.get_settings_service\\\")\\n    async def test_update_settings_from_yaml(self, mock_get_service):\\n        \\\"\\\"\\\"Test updating settings from YAML config.\\\"\\\"\\\"\\n        mock_service = Mock()\\n        mock_settings = Mock()\\n\\n        # Create an async mock\\n        async def async_update_from_yaml(*_args, **_kwargs):\\n            return None\\n\\n        mock_settings.update_from_yaml = Mock(side_effect=async_update_from_yaml)\\n        mock_service.settings = mock_settings\\n        mock_get_service.return_value = mock_service\\n\\n        await update_settings(config=\\\"config.yaml\\\", dev=True)\\n\\n        # Verify the service was called and update_from_yaml was called\\n        mock_get_service.assert_called_once()\\n        mock_settings.update_from_yaml.assert_called_once_with(\\\"config.yaml\\\", dev=True)\\n\\n\\nclass TestUtilityMiscFunctions:\\n    \\\"\\\"\\\"Test cases for miscellaneous utility functions.\\\"\\\"\\\"\\n\\n    def test_is_class_method(self):\\n        \\\"\\\"\\\"Test class method detection.\\\"\\\"\\\"\\n\\n        class TestClass:\\n            @classmethod\\n            def class_method(cls):\\n                return \\\"class method\\\"\\n\\n            def instance_method(self):\\n                return \\\"instance method\\\"\\n\\n        # Note: This test may need adjustment based on actual implementation\\n        # The function checks if func.__self__ is cls.__class__\\n        bound_method = TestClass.class_method\\n        result = is_class_method(bound_method, TestClass)\\n\\n        # The actual result depends on how the function is implemented\\n        assert isinstance(result, bool)\\n\\n    def test_escape_json_dump(self):\\n        \\\"\\\"\\\"Test JSON escaping.\\\"\\\"\\\"\\n        test_dict = {\\\"key\\\": \\\"value\\\", \\\"nested\\\": {\\\"inner\\\": \\\"data\\\"}}\\n        result = escape_json_dump(test_dict)\\n\\n        assert \\\"\u0153\\\" in result  # Quotes should be replaced\\n        assert '\\\"' not in result  # No original quotes should remain\\n\\n    def test_find_closest_match(self):\\n        \\\"\\\"\\\"Test finding closest string match.\\\"\\\"\\\"\\n        strings_list = [\\\"hello\\\", \\\"world\\\", \\\"python\\\", \\\"test\\\"]\\n\\n        # Exact match\\n        result = find_closest_match(\\\"hello\\\", strings_list)\\n        assert result == \\\"hello\\\"\\n\\n        # Close match\\n        result = find_closest_match(\\\"helo\\\", strings_list)\\n        assert result == \\\"hello\\\"\\n\\n        # Test with a string that really has no close match\\n        # Use very different characters to ensure no match\\n        result = find_closest_match(\\\"zzzzqqqqwwwweeee\\\", strings_list)\\n        # The function uses cutoff=0.2, so any result is still valid behavior\\n        # Just test that it returns something or None\\n        assert result is None or result in strings_list\\n\\n    def test_find_closest_match_empty_list(self):\\n        \\\"\\\"\\\"Test finding closest match in empty list.\\\"\\\"\\\"\\n        result = find_closest_match(\\\"test\\\", [])\\n        assert result is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_util_strings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6e3f3d7b6f8633a85c24eb528d44fb2e5ae313e1cb7e2bebb0be68883647566f\",\"content\":\"import pytest\\nfrom lfx.utils import util_strings\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"value\\\", \\\"expected\\\"),\\n    [\\n        (\\\"sqlite:///test.db\\\", True),\\n        (\\\"sqlite:////var/folders/test.db\\\", True),\\n        (\\\"sqlite:///:memory:\\\", True),\\n        (\\\"sqlite+aiosqlite:////var/folders/test.db\\\", True),\\n        (\\\"postgresql://user:pass@localhost/dbname\\\", True),\\n        (\\\"postgresql+psycopg2://scott:tiger@localhost:5432/mydatabase\\\", True),\\n        (\\\"postgresql+pg8000://dbuser:kx%40jj5%2Fg@pghost10/appdb\\\", True),\\n        (\\\"mysql://user:pass@localhost/dbname\\\", True),\\n        (\\\"mysql+mysqldb://scott:tiger@localhost/foo\\\", True),\\n        (\\\"mysql+pymysql://scott:tiger@localhost/foo\\\", True),\\n        (\\\"oracle://scott:tiger@localhost:1521/?service_name=freepdb1\\\", True),\\n        (\\\"oracle+cx_oracle://scott:tiger@tnsalias\\\", True),\\n        (\\\"oracle+oracledb://scott:tiger@localhost:1521/?service_name=freepdb1\\\", True),\\n        (\\\"\\\", False),\\n        (\\\" invalid \\\", False),\\n        (\\\"not_a_url\\\", False),\\n        (None, False),\\n        (\\\"invalid://database\\\", False),\\n        (\\\"invalid://:@/test\\\", False),\\n    ],\\n)\\ndef test_is_valid_database_url(value, expected):\\n    assert util_strings.is_valid_database_url(value) == expected\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_validate.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1f42fa684f2149c307654cfe2972785c364b9f96692d75e33e67134c76daefbf\",\"content\":\"\\\"\\\"\\\"Unit tests for validate.py utilities.\\\"\\\"\\\"\\n\\nimport ast\\nimport warnings\\nfrom unittest.mock import Mock, patch\\n\\nimport pytest\\nfrom lfx.custom.validate import (\\n    add_type_ignores,\\n    build_class_constructor,\\n    compile_class_code,\\n    create_class,\\n    create_function,\\n    create_type_ignore_class,\\n    eval_function,\\n    execute_function,\\n    extract_class_code,\\n    extract_class_name,\\n    extract_function_name,\\n    find_names_in_code,\\n    get_default_imports,\\n    prepare_global_scope,\\n    validate_code,\\n)\\n\\n\\nclass TestAddTypeIgnores:\\n    \\\"\\\"\\\"Test cases for add_type_ignores function.\\\"\\\"\\\"\\n\\n    def test_adds_type_ignore_when_missing(self):\\n        \\\"\\\"\\\"Test that TypeIgnore is added when not present.\\\"\\\"\\\"\\n        # Remove TypeIgnore if it exists\\n        if hasattr(ast, \\\"TypeIgnore\\\"):\\n            delattr(ast, \\\"TypeIgnore\\\")\\n\\n        add_type_ignores()\\n\\n        assert hasattr(ast, \\\"TypeIgnore\\\")\\n        assert issubclass(ast.TypeIgnore, ast.AST)\\n        assert ast.TypeIgnore._fields == ()\\n\\n    def test_does_nothing_when_already_exists(self):\\n        \\\"\\\"\\\"Test that function doesn't modify existing TypeIgnore.\\\"\\\"\\\"\\n        # Ensure TypeIgnore exists first\\n        add_type_ignores()\\n        original_type_ignore = ast.TypeIgnore\\n\\n        add_type_ignores()\\n\\n        assert ast.TypeIgnore is original_type_ignore\\n\\n\\nclass TestValidateCode:\\n    \\\"\\\"\\\"Test cases for validate_code function.\\\"\\\"\\\"\\n\\n    def test_valid_code_with_function(self):\\n        \\\"\\\"\\\"Test validation passes for valid code with function.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef hello_world():\\n    return \\\"Hello, World!\\\"\\n\\\"\\\"\\\"\\n        result = validate_code(code)\\n        assert result[\\\"imports\\\"][\\\"errors\\\"] == []\\n        assert result[\\\"function\\\"][\\\"errors\\\"] == []\\n\\n    def test_code_with_valid_imports(self):\\n        \\\"\\\"\\\"Test validation passes for code with valid imports.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport os\\nimport sys\\n\\ndef get_path():\\n    return os.path.join(sys.path[0], \\\"test\\\")\\n\\\"\\\"\\\"\\n        result = validate_code(code)\\n        assert result[\\\"imports\\\"][\\\"errors\\\"] == []\\n        assert result[\\\"function\\\"][\\\"errors\\\"] == []\\n\\n    def test_code_with_invalid_imports(self):\\n        \\\"\\\"\\\"Test validation fails for code with invalid imports.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport nonexistent_module\\n\\ndef test_func():\\n    return nonexistent_module.some_function()\\n\\\"\\\"\\\"\\n        result = validate_code(code)\\n        assert len(result[\\\"imports\\\"][\\\"errors\\\"]) == 1\\n        assert \\\"nonexistent_module\\\" in result[\\\"imports\\\"][\\\"errors\\\"][0]\\n\\n    def test_code_with_syntax_error(self):\\n        \\\"\\\"\\\"Test validation fails for code with syntax errors.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef broken_function(\\n    return \\\"incomplete\\\"\\n\\\"\\\"\\\"\\n        result = validate_code(code)\\n        # The function should catch the syntax error and return it in the results\\n        assert len(result[\\\"function\\\"][\\\"errors\\\"]) >= 1\\n        error_message = \\\" \\\".join(result[\\\"function\\\"][\\\"errors\\\"])\\n        assert (\\n            \\\"SyntaxError\\\" in error_message or \\\"invalid syntax\\\" in error_message or \\\"was never closed\\\" in error_message\\n        )\\n\\n    def test_code_with_function_execution_error(self):\\n        \\\"\\\"\\\"Test validation fails when function execution fails.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef error_function():\\n    undefined_variable + 1\\n\\\"\\\"\\\"\\n        result = validate_code(code)\\n        # This should pass parsing but may fail execution\\n        assert result[\\\"imports\\\"][\\\"errors\\\"] == []\\n\\n    def test_empty_code(self):\\n        \\\"\\\"\\\"Test validation handles empty code.\\\"\\\"\\\"\\n        result = validate_code(\\\"\\\")\\n        assert result[\\\"imports\\\"][\\\"errors\\\"] == []\\n        assert result[\\\"function\\\"][\\\"errors\\\"] == []\\n\\n    def test_validate_code_does_not_execute_default_args(self, tmp_path):\\n        \\\"\\\"\\\"validate_code must not run function-definition-time code.\\n\\n        Regression for GHSA-2wcq-pvw2-xh7v: the\\n        validator previously exec()'d each function definition, so a default\\n        argument (or decorator) expression executed during validation. Here a\\n        default arg would create a file as a side effect; it must NOT run.\\n        \\\"\\\"\\\"\\n        marker = tmp_path / \\\"pwned.txt\\\"\\n        code = f'def exploit(x=open({str(marker)!r}, \\\"w\\\").write(\\\"pwned\\\")):\\\\n    return x\\\\n'\\n\\n        result = validate_code(code)\\n\\n        # No code executed -> the side-effect file was never created.\\n        assert not marker.exists()\\n        # Validation still returns the normal structure (valid syntax, no imports).\\n        assert result[\\\"imports\\\"][\\\"errors\\\"] == []\\n        # Code is syntactically valid, so no compile errors expected.\\n        assert result[\\\"function\\\"][\\\"errors\\\"] == []\\n\\n    def test_code_with_multiple_imports(self):\\n        \\\"\\\"\\\"Test validation handles multiple imports.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport os\\nimport sys\\nimport json\\nimport nonexistent1\\nimport nonexistent2\\n\\ndef test_func():\\n    return json.dumps({\\\"path\\\": os.getcwd()})\\n\\\"\\\"\\\"\\n        result = validate_code(code)\\n        assert len(result[\\\"imports\\\"][\\\"errors\\\"]) == 2\\n        assert any(\\\"nonexistent1\\\" in err for err in result[\\\"imports\\\"][\\\"errors\\\"])\\n        assert any(\\\"nonexistent2\\\" in err for err in result[\\\"imports\\\"][\\\"errors\\\"])\\n\\n    @patch(\\\"lfx.custom.validate.logger\\\")\\n    def test_logging_on_parse_error(self, mock_logger):\\n        \\\"\\\"\\\"Test that parsing errors are logged.\\\"\\\"\\\"\\n        # Structlog doesn't have opt method, so hasattr(logger, \\\"opt\\\") returns False\\n        mock_logger.debug = Mock()\\n\\n        code = \\\"invalid python syntax +++\\\"\\n        validate_code(code)\\n\\n        # With structlog, we expect logger.debug to be called with exc_info=True\\n        mock_logger.debug.assert_called_with(\\\"Error parsing code\\\", exc_info=True)\\n\\n\\nclass TestEvalFunction:\\n    \\\"\\\"\\\"Test cases for eval_function function.\\\"\\\"\\\"\\n\\n    def test_evaluates_simple_function(self):\\n        \\\"\\\"\\\"Test evaluation of a simple function.\\\"\\\"\\\"\\n        function_string = \\\"\\\"\\\"\\ndef add_numbers(a, b):\\n    return a + b\\n\\\"\\\"\\\"\\n        func = eval_function(function_string)\\n        assert callable(func)\\n        assert func(2, 3) == 5\\n\\n    def test_evaluates_function_with_default_args(self):\\n        \\\"\\\"\\\"Test evaluation of function with default arguments.\\\"\\\"\\\"\\n        function_string = \\\"\\\"\\\"\\ndef greet(name=\\\"World\\\"):\\n    return f\\\"Hello, {name}!\\\"\\n\\\"\\\"\\\"\\n        func = eval_function(function_string)\\n        assert func() == \\\"Hello, World!\\\"\\n        assert func(\\\"Alice\\\") == \\\"Hello, Alice!\\\"\\n\\n    def test_raises_error_for_no_function(self):\\n        \\\"\\\"\\\"Test that error is raised when no function is found.\\\"\\\"\\\"\\n        code_string = \\\"\\\"\\\"\\nx = 42\\ny = \\\"hello\\\"\\n\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Function string does not contain a function\\\"):\\n            eval_function(code_string)\\n\\n    def test_finds_correct_function_among_multiple(self):\\n        \\\"\\\"\\\"Test that the correct function is found when multiple exist.\\\"\\\"\\\"\\n        function_string = \\\"\\\"\\\"\\ndef helper():\\n    return \\\"helper\\\"\\n\\ndef main_function():\\n    return \\\"main\\\"\\n\\\"\\\"\\\"\\n        func = eval_function(function_string)\\n        # Should return one of the functions (implementation detail)\\n        assert callable(func)\\n\\n\\nclass TestExecuteFunction:\\n    \\\"\\\"\\\"Test cases for execute_function function.\\\"\\\"\\\"\\n\\n    def test_executes_function_with_args(self):\\n        \\\"\\\"\\\"Test execution of function with arguments.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef multiply(x, y):\\n    return x * y\\n\\\"\\\"\\\"\\n        result = execute_function(code, \\\"multiply\\\", 4, 5)\\n        assert result == 20\\n\\n    def test_executes_function_with_kwargs(self):\\n        \\\"\\\"\\\"Test execution of function with keyword arguments.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef create_message(text, urgent=False):\\n    prefix = \\\"URGENT: \\\" if urgent else \\\"\\\"\\n    return prefix + text\\n\\\"\\\"\\\"\\n        result = execute_function(code, \\\"create_message\\\", \\\"Hello\\\", urgent=True)\\n        assert result == \\\"URGENT: Hello\\\"\\n\\n    def test_executes_function_with_imports(self):\\n        \\\"\\\"\\\"Test execution of function that uses imports.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport os\\n\\ndef get_current_dir():\\n    return os.getcwd()\\n\\\"\\\"\\\"\\n        result = execute_function(code, \\\"get_current_dir\\\")\\n        assert isinstance(result, str)\\n\\n    def test_raises_error_for_missing_module(self):\\n        \\\"\\\"\\\"Test that error is raised for missing modules.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport nonexistent_module\\n\\ndef test_func():\\n    return nonexistent_module.test()\\n\\\"\\\"\\\"\\n        with pytest.raises(ModuleNotFoundError, match=\\\"Module nonexistent_module not found\\\"):\\n            execute_function(code, \\\"test_func\\\")\\n\\n    def test_raises_error_for_missing_function(self):\\n        \\\"\\\"\\\"Test that error is raised when function doesn't exist.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef existing_function():\\n    return \\\"exists\\\"\\n\\\"\\\"\\\"\\n        # The function should raise an error when the specified function doesn't exist\\n        with pytest.raises((ValueError, StopIteration)):\\n            execute_function(code, \\\"nonexistent_function\\\")\\n\\n\\nclass TestCreateFunction:\\n    \\\"\\\"\\\"Test cases for create_function function.\\\"\\\"\\\"\\n\\n    def test_creates_callable_function(self):\\n        \\\"\\\"\\\"Test that a callable function is created.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef square(x):\\n    return x ** 2\\n\\\"\\\"\\\"\\n        func = create_function(code, \\\"square\\\")\\n        assert callable(func)\\n        assert func(5) == 25\\n\\n    def test_handles_imports_in_function(self):\\n        \\\"\\\"\\\"Test that imports within function are handled.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport math\\n\\ndef calculate_area(radius):\\n    return math.pi * radius ** 2\\n\\\"\\\"\\\"\\n        func = create_function(code, \\\"calculate_area\\\")\\n        result = func(2)\\n        assert abs(result - 12.566370614359172) < 0.0001\\n\\n    def test_handles_from_imports(self):\\n        \\\"\\\"\\\"Test that from imports are handled correctly.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nfrom math import sqrt\\n\\ndef hypotenuse(a, b):\\n    return sqrt(a**2 + b**2)\\n\\\"\\\"\\\"\\n        func = create_function(code, \\\"hypotenuse\\\")\\n        assert func(3, 4) == 5.0\\n\\n    def test_raises_error_for_missing_module(self):\\n        \\\"\\\"\\\"Test that error is raised for missing modules.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport nonexistent_module\\n\\ndef test_func():\\n    return \\\"test\\\"\\n\\\"\\\"\\\"\\n        with pytest.raises(ModuleNotFoundError, match=\\\"Module nonexistent_module not found\\\"):\\n            create_function(code, \\\"test_func\\\")\\n\\n\\nclass TestCreateClass:\\n    \\\"\\\"\\\"Test cases for create_class function.\\\"\\\"\\\"\\n\\n    def test_creates_simple_class(self):\\n        \\\"\\\"\\\"Test creation of a simple class.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nclass TestClass:\\n    def __init__(self, value=None):\\n        self.value = value\\n\\n    def get_value(self):\\n        return self.value\\n\\\"\\\"\\\"\\n        cls = create_class(code, \\\"TestClass\\\")\\n        instance = cls()\\n        assert hasattr(instance, \\\"__init__\\\")\\n        assert hasattr(instance, \\\"get_value\\\")\\n\\n    def test_handles_class_with_imports(self):\\n        \\\"\\\"\\\"Test creation of class that uses imports.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport json\\n\\nclass JsonHandler:\\n    def __init__(self):\\n        self.data = {}\\n\\n    def to_json(self):\\n        return json.dumps(self.data)\\n\\\"\\\"\\\"\\n        cls = create_class(code, \\\"JsonHandler\\\")\\n        instance = cls()\\n        assert hasattr(instance, \\\"to_json\\\")\\n\\n    def test_replaces_legacy_imports(self):\\n        \\\"\\\"\\\"Test that legacy import statements are replaced.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nfrom langflow import CustomComponent\\n\\nclass MyComponent(CustomComponent):\\n    def build(self):\\n        return \\\"test\\\"\\n\\\"\\\"\\\"\\n        # Should not raise an error due to import replacement\\n        with patch(\\\"lfx.custom.validate.prepare_global_scope\\\") as mock_prepare:\\n            mock_prepare.return_value = {\\\"CustomComponent\\\": type(\\\"CustomComponent\\\", (), {})}\\n            with patch(\\\"lfx.custom.validate.extract_class_code\\\") as mock_extract:\\n                mock_extract.return_value = Mock()\\n                with patch(\\\"lfx.custom.validate.compile_class_code\\\") as mock_compile:\\n                    mock_compile.return_value = compile(\\\"pass\\\", \\\"<string>\\\", \\\"exec\\\")\\n                    with (\\n                        patch(\\\"lfx.custom.validate.build_class_constructor\\\") as mock_build,\\n                        patch(\\\"lfx.custom.validate.register_compiled_class_method_returns\\\"),\\n                    ):\\n                        mock_build.return_value = lambda: None\\n                        create_class(code, \\\"MyComponent\\\")\\n\\n    def test_handles_syntax_error(self):\\n        \\\"\\\"\\\"Test that syntax errors are handled properly.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nclass BrokenClass\\n    def __init__(self):\\n        pass\\n\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Syntax error in code\\\"):\\n            create_class(code, \\\"BrokenClass\\\")\\n\\n    def test_handles_validation_error(self):\\n        \\\"\\\"\\\"Test that validation errors are handled properly.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nclass TestClass:\\n    def __init__(self):\\n        pass\\n\\\"\\\"\\\"\\n        # Create a proper ValidationError instance\\n        from pydantic_core import ValidationError as CoreValidationError\\n\\n        validation_error = CoreValidationError.from_exception_data(\\\"TestClass\\\", [])\\n\\n        with (\\n            patch(\\\"lfx.custom.validate.prepare_global_scope\\\", side_effect=validation_error),\\n            pytest.raises(ValueError, match=r\\\".*\\\"),\\n        ):\\n            create_class(code, \\\"TestClass\\\")\\n\\n\\nclass TestHelperFunctions:\\n    \\\"\\\"\\\"Test cases for helper functions.\\\"\\\"\\\"\\n\\n    def test_create_type_ignore_class(self):\\n        \\\"\\\"\\\"Test creation of TypeIgnore class.\\\"\\\"\\\"\\n        type_ignore_class = create_type_ignore_class()\\n        assert issubclass(type_ignore_class, ast.AST)\\n        assert type_ignore_class._fields == ()\\n\\n    def test_extract_function_name(self):\\n        \\\"\\\"\\\"Test extraction of function name from code.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef my_function():\\n    return \\\"test\\\"\\n\\\"\\\"\\\"\\n        name = extract_function_name(code)\\n        assert name == \\\"my_function\\\"\\n\\n    def test_extract_function_name_no_function(self):\\n        \\\"\\\"\\\"Test error when no function found.\\\"\\\"\\\"\\n        code = \\\"x = 42\\\"\\n        with pytest.raises(ValueError, match=\\\"No function definition found\\\"):\\n            extract_function_name(code)\\n\\n    def test_extract_class_name(self):\\n        \\\"\\\"\\\"Test extraction of Component class name.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nclass MyComponent(Component):\\n    def build(self):\\n        pass\\n\\\"\\\"\\\"\\n        name = extract_class_name(code)\\n        assert name == \\\"MyComponent\\\"\\n\\n    def test_extract_class_name_no_component(self):\\n        \\\"\\\"\\\"Test error when no Component subclass found.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nclass RegularClass:\\n    pass\\n\\\"\\\"\\\"\\n        with pytest.raises(TypeError, match=\\\"No Component subclass found\\\"):\\n            extract_class_name(code)\\n\\n    def test_extract_class_name_syntax_error(self):\\n        \\\"\\\"\\\"Test error handling for syntax errors in extract_class_name.\\\"\\\"\\\"\\n        code = \\\"class BrokenClass\\\"\\n        with pytest.raises(ValueError, match=\\\"Invalid Python code\\\"):\\n            extract_class_name(code)\\n\\n    def test_find_names_in_code(self):\\n        \\\"\\\"\\\"Test finding specific names in code.\\\"\\\"\\\"\\n        code = \\\"from typing import Optional, List\\\\ndata: Optional[List[str]] = None\\\"\\n        names = [\\\"Optional\\\", \\\"List\\\", \\\"Dict\\\", \\\"Union\\\"]\\n        found = find_names_in_code(code, names)\\n        assert found == {\\\"Optional\\\", \\\"List\\\"}\\n\\n    def test_find_names_in_code_none_found(self):\\n        \\\"\\\"\\\"Test when no names are found in code.\\\"\\\"\\\"\\n        code = \\\"x = 42\\\"\\n        names = [\\\"Optional\\\", \\\"List\\\"]\\n        found = find_names_in_code(code, names)\\n        assert found == set()\\n\\n\\nclass TestPrepareGlobalScope:\\n    \\\"\\\"\\\"Test cases for prepare_global_scope function.\\\"\\\"\\\"\\n\\n    def test_handles_imports(self):\\n        \\\"\\\"\\\"Test that imports are properly handled.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport os\\nimport sys\\n\\ndef test():\\n    pass\\n\\\"\\\"\\\"\\n        module = ast.parse(code)\\n        scope = prepare_global_scope(module)\\n        assert \\\"os\\\" in scope\\n        assert \\\"sys\\\" in scope\\n\\n    def test_handles_from_imports(self):\\n        \\\"\\\"\\\"Test that from imports are properly handled.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nfrom os import path\\nfrom sys import version\\n\\ndef test():\\n    pass\\n\\\"\\\"\\\"\\n        module = ast.parse(code)\\n        scope = prepare_global_scope(module)\\n        assert \\\"path\\\" in scope\\n        assert \\\"version\\\" in scope\\n\\n    def test_handles_import_errors(self):\\n        \\\"\\\"\\\"Test that import errors are properly raised.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nimport nonexistent_module\\n\\ndef test():\\n    pass\\n\\\"\\\"\\\"\\n        module = ast.parse(code)\\n        with pytest.raises(ModuleNotFoundError, match=\\\"No module named 'nonexistent_module'\\\"):\\n            prepare_global_scope(module)\\n\\n    def test_handles_langchain_warnings(self):\\n        \\\"\\\"\\\"Test that langchain warnings are suppressed.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nfrom langchain_core.messages import BaseMessage\\n\\ndef test():\\n    pass\\n\\\"\\\"\\\"\\n        module = ast.parse(code)\\n\\n        with patch(\\\"importlib.import_module\\\") as mock_import:\\n            mock_module = Mock()\\n            mock_module.BaseMessage = Mock()\\n            mock_import.return_value = mock_module\\n\\n            with warnings.catch_warnings(record=True) as w:\\n                warnings.simplefilter(\\\"always\\\")\\n                prepare_global_scope(module)\\n                # Should not have langchain warnings\\n                langchain_warnings = [warning for warning in w if \\\"langchain\\\" in str(warning.message).lower()]\\n                assert len(langchain_warnings) == 0\\n\\n    def test_executes_definitions(self):\\n        \\\"\\\"\\\"Test that class and function definitions are executed.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef helper():\\n    return \\\"helper\\\"\\n\\nclass TestClass:\\n    value = 42\\n\\\"\\\"\\\"\\n        module = ast.parse(code)\\n        scope = prepare_global_scope(module)\\n        assert \\\"helper\\\" in scope\\n        assert \\\"TestClass\\\" in scope\\n        assert callable(scope[\\\"helper\\\"])\\n        assert scope[\\\"TestClass\\\"].value == 42\\n\\n\\nclass TestClassCodeOperations:\\n    \\\"\\\"\\\"Test cases for class code operation functions.\\\"\\\"\\\"\\n\\n    def test_extract_class_code(self):\\n        \\\"\\\"\\\"Test extraction of class code from module.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\ndef helper():\\n    pass\\n\\nclass MyClass:\\n    def method(self):\\n        pass\\n\\\"\\\"\\\"\\n        module = ast.parse(code)\\n        class_code = extract_class_code(module, \\\"MyClass\\\")\\n        assert isinstance(class_code, ast.ClassDef)\\n        assert class_code.name == \\\"MyClass\\\"\\n\\n    def test_compile_class_code(self):\\n        \\\"\\\"\\\"Test compilation of class code.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nclass TestClass:\\n    def method(self):\\n        return \\\"test\\\"\\n\\\"\\\"\\\"\\n        module = ast.parse(code)\\n        class_code = extract_class_code(module, \\\"TestClass\\\")\\n        compiled = compile_class_code(class_code)\\n        assert compiled is not None\\n\\n    def test_build_class_constructor(self):\\n        \\\"\\\"\\\"Test building class constructor.\\\"\\\"\\\"\\n        code = \\\"\\\"\\\"\\nclass SimpleClass:\\n    def __init__(self):\\n        self.value = \\\"test\\\"\\n\\\"\\\"\\\"\\n        module = ast.parse(code)\\n        class_code = extract_class_code(module, \\\"SimpleClass\\\")\\n        compiled = compile_class_code(class_code)\\n\\n        constructor = build_class_constructor(compiled, {}, \\\"SimpleClass\\\")\\n        assert constructor is not None\\n\\n\\nclass TestGetDefaultImports:\\n    \\\"\\\"\\\"Test cases for get_default_imports function.\\\"\\\"\\\"\\n\\n    @patch(\\\"lfx.field_typing.constants.CUSTOM_COMPONENT_SUPPORTED_TYPES\\\", {\\\"TestType\\\": Mock()})\\n    def test_returns_default_imports(self):\\n        \\\"\\\"\\\"Test that default imports are returned.\\\"\\\"\\\"\\n        code = \\\"TestType and Optional\\\"\\n\\n        with patch(\\\"importlib.import_module\\\") as mock_import:\\n            mock_module = Mock()\\n            mock_module.TestType = Mock()\\n            mock_import.return_value = mock_module\\n\\n            imports = get_default_imports(code)\\n            assert \\\"Optional\\\" in imports\\n            assert \\\"List\\\" in imports\\n            assert \\\"Dict\\\" in imports\\n            assert \\\"Union\\\" in imports\\n\\n    def test_includes_langflow_imports(self):\\n        \\\"\\\"\\\"Test that langflow imports are included when found in code.\\\"\\\"\\\"\\n        # Use an actual type from CUSTOM_COMPONENT_SUPPORTED_TYPES\\n        code = \\\"Chain is used here\\\"\\n\\n        with patch(\\\"lfx.custom.validate.importlib\\\") as mock_importlib:\\n            mock_module = Mock()\\n            mock_module.Chain = Mock()\\n            mock_importlib.import_module.return_value = mock_module\\n\\n            imports = get_default_imports(code)\\n            assert \\\"Chain\\\" in imports\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_version.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1cbe821fec4ae44bbd9fd0b8c2a4a5b89b842b9566285bd1df04d124a6811bb0\",\"content\":\"from unittest.mock import Mock, patch\\n\\nimport httpx\\nimport pytest\\nfrom langflow.utils.version import (\\n    _compute_non_prerelease_version,\\n    _get_version_info,\\n    fetch_latest_version,\\n    get_version_info,\\n    is_nightly,\\n    is_pre_release,\\n)\\n\\n\\nclass TestComputeNonPrereleaseVersion:\\n    \\\"\\\"\\\"Test cases for _compute_non_prerelease_version function.\\\"\\\"\\\"\\n\\n    def test_compute_alpha_version(self):\\n        \\\"\\\"\\\"Test computing non-prerelease version from alpha version.\\\"\\\"\\\"\\n        version = \\\"1.2.3.a1\\\"\\n        result = _compute_non_prerelease_version(version)\\n        assert result == \\\"1.2.3\\\"\\n\\n    def test_compute_beta_version(self):\\n        \\\"\\\"\\\"Test computing non-prerelease version from beta version.\\\"\\\"\\\"\\n        version = \\\"2.0.0.b2\\\"\\n        result = _compute_non_prerelease_version(version)\\n        assert result == \\\"2.0.0\\\"\\n\\n    def test_compute_rc_version(self):\\n        \\\"\\\"\\\"Test computing non-prerelease version from release candidate version.\\\"\\\"\\\"\\n        version = \\\"1.5.0.rc1\\\"\\n        result = _compute_non_prerelease_version(version)\\n        assert result == \\\"1.5.0\\\"\\n\\n    def test_compute_dev_version(self):\\n        \\\"\\\"\\\"Test computing non-prerelease version from dev version.\\\"\\\"\\\"\\n        version = \\\"1.0.0.dev123\\\"\\n        result = _compute_non_prerelease_version(version)\\n        assert result == \\\"1.0.0\\\"\\n\\n    def test_compute_post_version(self):\\n        \\\"\\\"\\\"Test computing non-prerelease version from post version.\\\"\\\"\\\"\\n        version = \\\"1.1.0.post1\\\"\\n        result = _compute_non_prerelease_version(version)\\n        assert result == \\\"1.1.0\\\"\\n\\n    def test_compute_stable_version(self):\\n        \\\"\\\"\\\"Test computing non-prerelease version from stable version.\\\"\\\"\\\"\\n        version = \\\"1.0.0\\\"\\n        result = _compute_non_prerelease_version(version)\\n        assert result == \\\"1.0.0\\\"\\n\\n    def test_compute_version_with_multiple_keywords(self):\\n        \\\"\\\"\\\"Test computing version with multiple prerelease keywords (first match).\\\"\\\"\\\"\\n        version = \\\"1.0.0.a1.dev\\\"\\n        result = _compute_non_prerelease_version(version)\\n        assert result == \\\"1.0.0\\\"\\n\\n    def test_compute_version_no_dot_before_keyword(self):\\n        \\\"\\\"\\\"Test computing version without dot before keyword.\\\"\\\"\\\"\\n        version = \\\"1.0.0a1\\\"\\n        result = _compute_non_prerelease_version(version)\\n        assert result == \\\"1.0.\\\"\\n\\n    def test_compute_version_complex_format(self):\\n        \\\"\\\"\\\"Test computing version with complex format.\\\"\\\"\\\"\\n        version = \\\"2.1.0.rc2.post1\\\"\\n        result = _compute_non_prerelease_version(version)\\n        assert result == \\\"2.1.0\\\"\\n\\n\\nclass TestGetVersionInfo:\\n    \\\"\\\"\\\"Test cases for _get_version_info function.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.utils.version.metadata\\\")\\n    def test_get_version_info_langflow_package(self, mock_metadata):\\n        \\\"\\\"\\\"Test getting version info for langflow package.\\\"\\\"\\\"\\n        mock_metadata.version.return_value = \\\"1.0.0\\\"\\n\\n        result = _get_version_info()\\n\\n        assert result[\\\"version\\\"] == \\\"1.0.0\\\"\\n        assert result[\\\"main_version\\\"] == \\\"1.0.0\\\"\\n        assert result[\\\"package\\\"] == \\\"Langflow\\\"\\n\\n    @patch(\\\"langflow.utils.version.metadata\\\")\\n    def test_get_version_info_langflow_base_package(self, mock_metadata):\\n        \\\"\\\"\\\"Test getting version info for langflow-base package.\\\"\\\"\\\"\\n        from importlib import metadata as real_metadata\\n\\n        mock_metadata.PackageNotFoundError = real_metadata.PackageNotFoundError\\n\\n        def mock_version(pkg_name):\\n            if pkg_name == \\\"langflow\\\":\\n                raise mock_metadata.PackageNotFoundError\\n            if pkg_name == \\\"langflow-base\\\":\\n                return \\\"1.0.0.dev123\\\"\\n            raise mock_metadata.PackageNotFoundError\\n\\n        mock_metadata.version.side_effect = mock_version\\n\\n        result = _get_version_info()\\n\\n        assert result[\\\"version\\\"] == \\\"1.0.0.dev123\\\"\\n        assert result[\\\"main_version\\\"] == \\\"1.0.0\\\"\\n        # A `.dev` version is labeled a nightly regardless of which package name resolved it.\\n        assert result[\\\"package\\\"] == \\\"Langflow Nightly\\\"\\n\\n    @patch(\\\"langflow.utils.version.metadata\\\")\\n    def test_get_version_info_nightly_package(self, mock_metadata):\\n        \\\"\\\"\\\"Test getting version info for nightly package.\\\"\\\"\\\"\\n        from importlib import metadata as real_metadata\\n\\n        mock_metadata.PackageNotFoundError = real_metadata.PackageNotFoundError\\n\\n        def mock_version(pkg_name):\\n            if pkg_name in [\\\"langflow\\\", \\\"langflow-base\\\"]:\\n                raise mock_metadata.PackageNotFoundError\\n            if pkg_name == \\\"langflow-nightly\\\":\\n                return \\\"1.0.0.dev456\\\"\\n            raise mock_metadata.PackageNotFoundError\\n\\n        mock_metadata.version.side_effect = mock_version\\n\\n        result = _get_version_info()\\n\\n        assert result[\\\"version\\\"] == \\\"1.0.0.dev456\\\"\\n        assert result[\\\"main_version\\\"] == \\\"1.0.0\\\"\\n        assert result[\\\"package\\\"] == \\\"Langflow Nightly\\\"\\n\\n    @patch(\\\"langflow.utils.version.metadata\\\")\\n    def test_get_version_info_base_nightly_package(self, mock_metadata):\\n        \\\"\\\"\\\"Test getting version info for base nightly package.\\\"\\\"\\\"\\n        from importlib import metadata as real_metadata\\n\\n        mock_metadata.PackageNotFoundError = real_metadata.PackageNotFoundError\\n\\n        def mock_version(pkg_name):\\n            if pkg_name in [\\\"langflow\\\", \\\"langflow-base\\\", \\\"langflow-nightly\\\"]:\\n                raise mock_metadata.PackageNotFoundError\\n            if pkg_name == \\\"langflow-base-nightly\\\":\\n                return \\\"1.0.0.a1\\\"\\n            raise mock_metadata.PackageNotFoundError\\n\\n        mock_metadata.version.side_effect = mock_version\\n\\n        result = _get_version_info()\\n\\n        assert result[\\\"version\\\"] == \\\"1.0.0.a1\\\"\\n        assert result[\\\"main_version\\\"] == \\\"1.0.0\\\"\\n        assert result[\\\"package\\\"] == \\\"Langflow Nightly\\\"\\n\\n    @patch(\\\"langflow.utils.version.metadata\\\")\\n    def test_get_version_info_canonical_dev_is_nightly(self, mock_metadata):\\n        \\\"\\\"\\\"A canonical ``langflow`` install at a ``.dev`` version is labeled a nightly.\\n\\n        The nightly now publishes as ``langflow==X.Y.Z.devN`` (the canonical name matches first),\\n        so the \\\"Nightly\\\" label must come from the ``.dev`` marker, not the package name.\\n        \\\"\\\"\\\"\\n        from importlib import metadata as real_metadata\\n\\n        mock_metadata.PackageNotFoundError = real_metadata.PackageNotFoundError\\n\\n        def mock_version(pkg_name):\\n            if pkg_name == \\\"langflow\\\":\\n                return \\\"1.11.0.dev5\\\"\\n            raise mock_metadata.PackageNotFoundError\\n\\n        mock_metadata.version.side_effect = mock_version\\n\\n        result = _get_version_info()\\n\\n        assert result[\\\"version\\\"] == \\\"1.11.0.dev5\\\"\\n        assert result[\\\"main_version\\\"] == \\\"1.11.0\\\"\\n        assert result[\\\"package\\\"] == \\\"Langflow Nightly\\\"\\n\\n    @patch(\\\"langflow.utils.version.metadata\\\")\\n    def test_get_version_info_no_package_found(self, mock_metadata):\\n        \\\"\\\"\\\"Test getting version info when no package is found.\\\"\\\"\\\"\\n        from importlib import metadata as real_metadata\\n\\n        mock_metadata.PackageNotFoundError = real_metadata.PackageNotFoundError\\n        mock_metadata.version.side_effect = mock_metadata.PackageNotFoundError()\\n\\n        with pytest.raises(ValueError, match=\\\"Package not found from options\\\"):\\n            _get_version_info()\\n\\n    @patch(\\\"langflow.utils.version.metadata\\\")\\n    def test_get_version_info_import_error(self, mock_metadata):\\n        \\\"\\\"\\\"Test getting version info when ImportError occurs.\\\"\\\"\\\"\\n        from importlib import metadata as real_metadata\\n\\n        mock_metadata.PackageNotFoundError = real_metadata.PackageNotFoundError\\n        mock_metadata.version.side_effect = ImportError()\\n\\n        with pytest.raises(ValueError, match=\\\"Package not found from options\\\"):\\n            _get_version_info()\\n\\n\\nclass TestIsPreRelease:\\n    \\\"\\\"\\\"Test cases for is_pre_release function.\\\"\\\"\\\"\\n\\n    def test_is_pre_release_alpha(self):\\n        \\\"\\\"\\\"Test alpha versions are pre-release.\\\"\\\"\\\"\\n        assert is_pre_release(\\\"1.0.0a1\\\") is True\\n        assert is_pre_release(\\\"1.0.0.a1\\\") is True\\n\\n    def test_is_pre_release_beta(self):\\n        \\\"\\\"\\\"Test beta versions are pre-release.\\\"\\\"\\\"\\n        assert is_pre_release(\\\"1.0.0b1\\\") is True\\n        assert is_pre_release(\\\"1.0.0.b1\\\") is True\\n\\n    def test_is_pre_release_rc(self):\\n        \\\"\\\"\\\"Test release candidate versions are pre-release.\\\"\\\"\\\"\\n        assert is_pre_release(\\\"1.0.0rc1\\\") is True\\n        assert is_pre_release(\\\"1.0.0.rc1\\\") is True\\n\\n    def test_is_not_pre_release_stable(self):\\n        \\\"\\\"\\\"Test stable versions are not pre-release.\\\"\\\"\\\"\\n        assert is_pre_release(\\\"1.0.0\\\") is False\\n\\n    def test_is_not_pre_release_dev(self):\\n        \\\"\\\"\\\"Test dev versions are not considered pre-release.\\\"\\\"\\\"\\n        assert is_pre_release(\\\"1.0.0.dev123\\\") is False\\n\\n    def test_is_not_pre_release_post(self):\\n        \\\"\\\"\\\"Test post versions are not considered pre-release.\\\"\\\"\\\"\\n        assert is_pre_release(\\\"1.0.0.post1\\\") is False\\n\\n    def test_is_pre_release_mixed_version(self):\\n        \\\"\\\"\\\"Test mixed versions with pre-release markers.\\\"\\\"\\\"\\n        assert is_pre_release(\\\"1.0.0a1.dev123\\\") is True\\n        assert is_pre_release(\\\"1.0.0.rc1.post1\\\") is True\\n\\n\\nclass TestIsNightly:\\n    \\\"\\\"\\\"Test cases for is_nightly function.\\\"\\\"\\\"\\n\\n    def test_is_nightly_dev_version(self):\\n        \\\"\\\"\\\"Test dev versions are nightly.\\\"\\\"\\\"\\n        assert is_nightly(\\\"1.0.0.dev123\\\") is True\\n        assert is_nightly(\\\"1.0.0dev456\\\") is True\\n\\n    def test_is_not_nightly_stable(self):\\n        \\\"\\\"\\\"Test stable versions are not nightly.\\\"\\\"\\\"\\n        assert is_nightly(\\\"1.0.0\\\") is False\\n\\n    def test_is_not_nightly_alpha(self):\\n        \\\"\\\"\\\"Test alpha versions are not nightly.\\\"\\\"\\\"\\n        assert is_nightly(\\\"1.0.0a1\\\") is False\\n\\n    def test_is_not_nightly_beta(self):\\n        \\\"\\\"\\\"Test beta versions are not nightly.\\\"\\\"\\\"\\n        assert is_nightly(\\\"1.0.0b1\\\") is False\\n\\n    def test_is_not_nightly_rc(self):\\n        \\\"\\\"\\\"Test release candidate versions are not nightly.\\\"\\\"\\\"\\n        assert is_nightly(\\\"1.0.0rc1\\\") is False\\n\\n    def test_is_nightly_mixed_version(self):\\n        \\\"\\\"\\\"Test mixed versions with dev marker.\\\"\\\"\\\"\\n        assert is_nightly(\\\"1.0.0a1.dev123\\\") is True\\n\\n\\nclass TestFetchLatestVersion:\\n    \\\"\\\"\\\"Test cases for fetch_latest_version function.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.utils.version.httpx\\\")\\n    def test_fetch_latest_version_success(self, mock_httpx):\\n        \\\"\\\"\\\"Test successful fetching of latest version.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"releases\\\": {\\\"1.0.0\\\": [], \\\"1.1.0\\\": [], \\\"1.2.0\\\": [], \\\"2.0.0a1\\\": []}}\\n        mock_httpx.get.return_value = mock_response\\n\\n        result = fetch_latest_version(\\\"test-package\\\", include_prerelease=False)\\n\\n        assert result == \\\"1.2.0\\\"\\n        mock_httpx.get.assert_called_once_with(\\\"https://pypi.org/pypi/test-package/json\\\")\\n\\n    @patch(\\\"langflow.utils.version.httpx\\\")\\n    def test_fetch_latest_version_with_prerelease(self, mock_httpx):\\n        \\\"\\\"\\\"Test fetching latest version including prerelease.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"releases\\\": {\\\"1.0.0\\\": [], \\\"1.1.0\\\": [], \\\"2.0.0a1\\\": [], \\\"2.0.0b1\\\": []}}\\n        mock_httpx.get.return_value = mock_response\\n\\n        result = fetch_latest_version(\\\"test-package\\\", include_prerelease=True)\\n\\n        assert result == \\\"2.0.0b1\\\"\\n\\n    @patch(\\\"langflow.utils.version.httpx\\\")\\n    def test_fetch_latest_version_no_stable_versions(self, mock_httpx):\\n        \\\"\\\"\\\"Test fetching when no stable versions exist.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"releases\\\": {\\\"1.0.0a1\\\": [], \\\"1.0.0b1\\\": [], \\\"1.0.0rc1\\\": []}}\\n        mock_httpx.get.return_value = mock_response\\n\\n        result = fetch_latest_version(\\\"test-package\\\", include_prerelease=False)\\n\\n        assert result is None\\n\\n    @patch(\\\"langflow.utils.version.httpx\\\")\\n    def test_fetch_latest_version_package_name_normalization(self, mock_httpx):\\n        \\\"\\\"\\\"Test package name normalization.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"releases\\\": {\\\"1.0.0\\\": []}}\\n        mock_httpx.get.return_value = mock_response\\n\\n        fetch_latest_version(\\\"Test Package Name\\\", include_prerelease=False)\\n\\n        mock_httpx.get.assert_called_once_with(\\\"https://pypi.org/pypi/test-package-name/json\\\")\\n\\n    @patch(\\\"langflow.utils.version.httpx\\\")\\n    def test_fetch_latest_version_http_error(self, mock_httpx):\\n        \\\"\\\"\\\"Test handling HTTP errors.\\\"\\\"\\\"\\n        mock_httpx.get.side_effect = httpx.HTTPError(\\\"Network error\\\")\\n\\n        result = fetch_latest_version(\\\"test-package\\\", include_prerelease=False)\\n\\n        assert result is None\\n\\n    @patch(\\\"langflow.utils.version.httpx\\\")\\n    def test_fetch_latest_version_json_error(self, mock_httpx):\\n        \\\"\\\"\\\"Test handling JSON parsing errors.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.side_effect = ValueError(\\\"Invalid JSON\\\")\\n        mock_httpx.get.return_value = mock_response\\n\\n        result = fetch_latest_version(\\\"test-package\\\", include_prerelease=False)\\n\\n        assert result is None\\n\\n    @patch(\\\"langflow.utils.version.httpx\\\")\\n    def test_fetch_latest_version_empty_releases(self, mock_httpx):\\n        \\\"\\\"\\\"Test handling empty releases.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\\"releases\\\": {}}\\n        mock_httpx.get.return_value = mock_response\\n\\n        result = fetch_latest_version(\\\"test-package\\\", include_prerelease=False)\\n\\n        assert result is None\\n\\n    @patch(\\\"langflow.utils.version.httpx\\\")\\n    def test_fetch_latest_version_complex_versions(self, mock_httpx):\\n        \\\"\\\"\\\"Test fetching with complex version numbers.\\\"\\\"\\\"\\n        mock_response = Mock()\\n        mock_response.json.return_value = {\\n            \\\"releases\\\": {\\\"1.0.0\\\": [], \\\"1.0.1\\\": [], \\\"1.0.10\\\": [], \\\"1.0.2\\\": [], \\\"1.1.0\\\": [], \\\"2.0.0\\\": []}\\n        }\\n        mock_httpx.get.return_value = mock_response\\n\\n        result = fetch_latest_version(\\\"test-package\\\", include_prerelease=False)\\n\\n        # Should correctly parse and find the highest version\\n        assert result == \\\"2.0.0\\\"\\n\\n\\nclass TestGetVersionInfoFunction:\\n    \\\"\\\"\\\"Test cases for get_version_info function.\\\"\\\"\\\"\\n\\n    @patch(\\\"langflow.utils.version.VERSION_INFO\\\")\\n    def test_get_version_info_returns_version_info(self, mock_version_info):\\n        \\\"\\\"\\\"Test that get_version_info returns VERSION_INFO.\\\"\\\"\\\"\\n        mock_version_info = {\\\"version\\\": \\\"1.0.0\\\", \\\"main_version\\\": \\\"1.0.0\\\", \\\"package\\\": \\\"Langflow\\\"}\\n\\n        with patch(\\\"langflow.utils.version.VERSION_INFO\\\", mock_version_info):\\n            result = get_version_info()\\n\\n            assert result == mock_version_info\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/utils/test_voice_utils.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e2649403c375bd89d658f15e8aef0de4bc256adcbe94ea3aea859dcb0ce48f4f\",\"content\":\"import base64\\nfrom unittest.mock import AsyncMock, MagicMock, mock_open, patch\\n\\nimport numpy as np\\nimport pytest\\nfrom langflow.utils.voice_utils import (\\n    BYTES_PER_16K_FRAME,\\n    BYTES_PER_24K_FRAME,\\n    BYTES_PER_SAMPLE,\\n    FRAME_DURATION_MS,\\n    SAMPLE_RATE_24K,\\n    VAD_SAMPLE_RATE_16K,\\n    _write_bytes_to_file,\\n    resample_24k_to_16k,\\n    write_audio_to_file,\\n)\\n\\n\\nclass TestConstants:\\n    \\\"\\\"\\\"Test the audio constants.\\\"\\\"\\\"\\n\\n    def test_sample_rates(self):\\n        \\\"\\\"\\\"Test sample rate constants.\\\"\\\"\\\"\\n        assert SAMPLE_RATE_24K == 24000\\n        assert VAD_SAMPLE_RATE_16K == 16000\\n\\n    def test_frame_duration(self):\\n        \\\"\\\"\\\"Test frame duration constant.\\\"\\\"\\\"\\n        assert FRAME_DURATION_MS == 20\\n\\n    def test_bytes_per_sample(self):\\n        \\\"\\\"\\\"Test bytes per sample constant.\\\"\\\"\\\"\\n        assert BYTES_PER_SAMPLE == 2\\n\\n    def test_bytes_per_frame_calculations(self):\\n        \\\"\\\"\\\"Test frame size calculations.\\\"\\\"\\\"\\n        # 24kHz: 24000 * 20 / 1000 * 2 = 960 bytes\\n        expected_24k = int(24000 * 20 / 1000) * 2\\n        assert expected_24k == BYTES_PER_24K_FRAME\\n        assert BYTES_PER_24K_FRAME == 960\\n\\n        # 16kHz: 16000 * 20 / 1000 * 2 = 640 bytes\\n        expected_16k = int(16000 * 20 / 1000) * 2\\n        assert expected_16k == BYTES_PER_16K_FRAME\\n        assert BYTES_PER_16K_FRAME == 640\\n\\n\\nclass TestResample24kTo16k:\\n    \\\"\\\"\\\"Test cases for resample_24k_to_16k function.\\\"\\\"\\\"\\n\\n    def test_resample_correct_frame_size(self):\\n        \\\"\\\"\\\"Test resampling with correct 960-byte frame.\\\"\\\"\\\"\\n        # Create a 960-byte frame (480 samples of int16)\\n        rng = np.random.default_rng()\\n        samples_24k = rng.integers(-32768, 32767, 480, dtype=np.int16)\\n        frame_24k_bytes = samples_24k.tobytes()\\n\\n        assert len(frame_24k_bytes) == BYTES_PER_24K_FRAME\\n\\n        result = resample_24k_to_16k(frame_24k_bytes)\\n\\n        # Should return 640 bytes (320 samples)\\n        assert len(result) == BYTES_PER_16K_FRAME\\n        assert isinstance(result, bytes)\\n\\n        # Verify we can convert back to int16 array\\n        result_samples = np.frombuffer(result, dtype=np.int16)\\n        assert len(result_samples) == 320\\n\\n    def test_resample_with_zero_audio(self):\\n        \\\"\\\"\\\"Test resampling with silent audio (all zeros).\\\"\\\"\\\"\\n        # Create silent 24kHz frame\\n        samples_24k = np.zeros(480, dtype=np.int16)\\n        frame_24k_bytes = samples_24k.tobytes()\\n\\n        result = resample_24k_to_16k(frame_24k_bytes)\\n        result_samples = np.frombuffer(result, dtype=np.int16)\\n\\n        # Result should also be mostly zeros (allowing for minor resampling artifacts)\\n        assert np.max(np.abs(result_samples)) <= 1  # Very small values allowed\\n\\n    def test_resample_with_sine_wave(self):\\n        \\\"\\\"\\\"Test resampling with a known sine wave.\\\"\\\"\\\"\\n        # Create a 1kHz sine wave at 24kHz sample rate\\n        t = np.linspace(0, 0.02, 480, endpoint=False)  # 20ms\\n        sine_wave = np.sin(2 * np.pi * 1000 * t)\\n\\n        # Convert to int16 range\\n        samples_24k = (sine_wave * 16384).astype(np.int16)\\n        frame_24k_bytes = samples_24k.tobytes()\\n\\n        result = resample_24k_to_16k(frame_24k_bytes)\\n        result_samples = np.frombuffer(result, dtype=np.int16)\\n\\n        # Verify the resampled wave maintains similar characteristics\\n        assert len(result_samples) == 320\\n        # The amplitude should be preserved roughly\\n        assert np.max(result_samples) > 10000  # Should maintain significant amplitude\\n        assert np.min(result_samples) < -10000\\n\\n    def test_resample_invalid_frame_size_too_small(self):\\n        \\\"\\\"\\\"Test error handling for frame too small.\\\"\\\"\\\"\\n        invalid_frame = b\\\"\\\\x00\\\" * 959  # 959 bytes instead of 960\\n\\n        with pytest.raises(ValueError, match=f\\\"Expected exactly {BYTES_PER_24K_FRAME} bytes\\\"):\\n            resample_24k_to_16k(invalid_frame)\\n\\n    def test_resample_invalid_frame_size_too_large(self):\\n        \\\"\\\"\\\"Test error handling for frame too large.\\\"\\\"\\\"\\n        invalid_frame = b\\\"\\\\x00\\\" * 961  # 961 bytes instead of 960\\n\\n        with pytest.raises(ValueError, match=f\\\"Expected exactly {BYTES_PER_24K_FRAME} bytes\\\"):\\n            resample_24k_to_16k(invalid_frame)\\n\\n    def test_resample_empty_frame(self):\\n        \\\"\\\"\\\"Test error handling for empty frame.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=f\\\"Expected exactly {BYTES_PER_24K_FRAME} bytes\\\"):\\n            resample_24k_to_16k(b\\\"\\\")\\n\\n    def test_resample_very_large_frame(self):\\n        \\\"\\\"\\\"Test error handling for very large frame.\\\"\\\"\\\"\\n        huge_frame = b\\\"\\\\x00\\\" * 10000\\n\\n        with pytest.raises(ValueError, match=f\\\"Expected exactly {BYTES_PER_24K_FRAME} bytes\\\"):\\n            resample_24k_to_16k(huge_frame)\\n\\n    def test_resample_preserves_data_type(self):\\n        \\\"\\\"\\\"Test that resampling preserves int16 data type.\\\"\\\"\\\"\\n        # Create frame with extreme values\\n        samples_24k = np.array([32767, -32768] * 240, dtype=np.int16)  # 480 samples\\n        frame_24k_bytes = samples_24k.tobytes()\\n\\n        result = resample_24k_to_16k(frame_24k_bytes)\\n        result_samples = np.frombuffer(result, dtype=np.int16)\\n\\n        # Verify data type is preserved\\n        assert result_samples.dtype == np.int16\\n        # Values should still be in int16 range\\n        assert np.all(result_samples >= -32768)\\n        assert np.all(result_samples <= 32767)\\n\\n    def test_resample_ratio_verification(self):\\n        \\\"\\\"\\\"Test that the resampling ratio is approximately 2/3.\\\"\\\"\\\"\\n        # Create a simple pattern\\n        samples_24k = np.tile(np.array([1000, -1000], dtype=np.int16), 240)  # 480 samples\\n        frame_24k_bytes = samples_24k.tobytes()\\n\\n        result = resample_24k_to_16k(frame_24k_bytes)\\n        result_samples = np.frombuffer(result, dtype=np.int16)\\n\\n        # Input: 480 samples, Output: 320 samples\\n        # Ratio: 320/480 = 2/3 \u2248 0.667\\n        ratio = len(result_samples) / len(samples_24k)\\n        assert abs(ratio - 2 / 3) < 0.001\\n\\n    @patch(\\\"langflow.utils.voice_utils.resample\\\")\\n    def test_resample_function_called(self, mock_resample):\\n        \\\"\\\"\\\"Test that scipy.signal.resample is called correctly.\\\"\\\"\\\"\\n        mock_resample.return_value = np.zeros(320, dtype=np.int16)\\n\\n        samples_24k = np.zeros(480, dtype=np.int16)\\n        frame_24k_bytes = samples_24k.tobytes()\\n\\n        resample_24k_to_16k(frame_24k_bytes)\\n\\n        # Verify resample was called with correct parameters\\n        mock_resample.assert_called_once()\\n        args, _ = mock_resample.call_args\\n        input_array, target_samples = args\\n\\n        assert len(input_array) == 480\\n        assert target_samples == 320  # int(480 * 2 / 3)\\n\\n\\nclass TestWriteAudioToFile:\\n    \\\"\\\"\\\"Test cases for write_audio_to_file function.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_write_audio_to_file_success(self):\\n        \\\"\\\"\\\"Test successful audio file writing.\\\"\\\"\\\"\\n        audio_data = b\\\"\\\\x01\\\\x02\\\\x03\\\\x04\\\"\\n        audio_base64 = base64.b64encode(audio_data).decode(\\\"utf-8\\\")\\n\\n        with (\\n            patch(\\\"langflow.utils.voice_utils.asyncio.to_thread\\\") as mock_to_thread,\\n            patch(\\\"langflow.utils.voice_utils.logger\\\") as mock_logger,\\n        ):\\n            mock_to_thread.return_value = None\\n            mock_logger.ainfo = AsyncMock()\\n\\n            await write_audio_to_file(audio_base64, \\\"test.raw\\\")\\n\\n            # Verify asyncio.to_thread was called correctly\\n            mock_to_thread.assert_called_once()\\n            args = mock_to_thread.call_args[0]\\n            assert args[0] == _write_bytes_to_file\\n            assert args[1] == audio_data\\n            assert args[2] == \\\"test.raw\\\"\\n\\n            # Verify logging\\n            mock_logger.ainfo.assert_called_once_with(f\\\"Wrote {len(audio_data)} bytes to test.raw\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_write_audio_to_file_default_filename(self):\\n        \\\"\\\"\\\"Test writing with default filename.\\\"\\\"\\\"\\n        audio_data = b\\\"\\\\x05\\\\x06\\\\x07\\\\x08\\\"\\n        audio_base64 = base64.b64encode(audio_data).decode(\\\"utf-8\\\")\\n\\n        with patch(\\\"langflow.utils.voice_utils.asyncio.to_thread\\\") as mock_to_thread:\\n            mock_to_thread.return_value = None\\n\\n            await write_audio_to_file(audio_base64)\\n\\n            # Should use default filename\\n            args = mock_to_thread.call_args[0]\\n            assert args[2] == \\\"output_audio.raw\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_write_audio_to_file_base64_decode_error(self):\\n        \\\"\\\"\\\"Test error handling for invalid base64.\\\"\\\"\\\"\\n        invalid_base64 = \\\"invalid base64 string!!!\\\"\\n\\n        with patch(\\\"langflow.utils.voice_utils.logger\\\") as mock_logger:\\n            mock_logger.aerror = AsyncMock()\\n            await write_audio_to_file(invalid_base64, \\\"test.raw\\\")\\n\\n            # Should log error\\n            mock_logger.aerror.assert_called_once()\\n            error_msg = mock_logger.aerror.call_args[0][0]\\n            assert \\\"Error writing audio to file:\\\" in error_msg\\n\\n    @pytest.mark.asyncio\\n    async def test_write_audio_to_file_os_error(self):\\n        \\\"\\\"\\\"Test error handling for OS errors during file writing.\\\"\\\"\\\"\\n        audio_data = b\\\"\\\\x01\\\\x02\\\\x03\\\\x04\\\"\\n        audio_base64 = base64.b64encode(audio_data).decode(\\\"utf-8\\\")\\n\\n        with (\\n            patch(\\\"langflow.utils.voice_utils.asyncio.to_thread\\\") as mock_to_thread,\\n            patch(\\\"langflow.utils.voice_utils.logger\\\") as mock_logger,\\n        ):\\n            mock_to_thread.side_effect = OSError(\\\"File write error\\\")\\n            # Mock the async logger methods\\n            mock_logger.aerror = AsyncMock()\\n\\n            await write_audio_to_file(audio_base64, \\\"test.raw\\\")\\n\\n            # Should log error\\n            mock_logger.aerror.assert_called_once()\\n            error_msg = mock_logger.aerror.call_args[0][0]\\n            assert \\\"Error writing audio to file:\\\" in error_msg\\n\\n    @pytest.mark.asyncio\\n    async def test_write_audio_to_file_empty_audio(self):\\n        \\\"\\\"\\\"Test writing empty audio data.\\\"\\\"\\\"\\n        empty_audio = b\\\"\\\"\\n        audio_base64 = base64.b64encode(empty_audio).decode(\\\"utf-8\\\")\\n\\n        with (\\n            patch(\\\"langflow.utils.voice_utils.asyncio.to_thread\\\") as mock_to_thread,\\n            patch(\\\"langflow.utils.voice_utils.logger\\\") as mock_logger,\\n        ):\\n            mock_to_thread.return_value = None\\n            mock_logger.ainfo = AsyncMock()\\n\\n            await write_audio_to_file(audio_base64, \\\"empty.raw\\\")\\n\\n            # Should still work and log\\n            mock_to_thread.assert_called_once()\\n            mock_logger.ainfo.assert_called_once_with(\\\"Wrote 0 bytes to empty.raw\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_write_audio_to_file_large_audio(self):\\n        \\\"\\\"\\\"Test writing large audio data.\\\"\\\"\\\"\\n        large_audio = b\\\"\\\\x01\\\" * 10000\\n        audio_base64 = base64.b64encode(large_audio).decode(\\\"utf-8\\\")\\n\\n        with (\\n            patch(\\\"langflow.utils.voice_utils.asyncio.to_thread\\\") as mock_to_thread,\\n            patch(\\\"langflow.utils.voice_utils.logger\\\") as mock_logger,\\n        ):\\n            mock_to_thread.return_value = None\\n            mock_logger.ainfo = AsyncMock()\\n\\n            await write_audio_to_file(audio_base64, \\\"large.raw\\\")\\n\\n            # Should handle large data correctly\\n            args = mock_to_thread.call_args[0]\\n            assert args[1] == large_audio\\n            mock_logger.ainfo.assert_called_once_with(\\\"Wrote 10000 bytes to large.raw\\\")\\n\\n\\nclass TestWriteBytesToFile:\\n    \\\"\\\"\\\"Test cases for _write_bytes_to_file function.\\\"\\\"\\\"\\n\\n    def test_write_bytes_to_file_success(self):\\n        \\\"\\\"\\\"Test successful bytes writing to file.\\\"\\\"\\\"\\n        test_data = b\\\"\\\\x01\\\\x02\\\\x03\\\\x04\\\\x05\\\"\\n        filename = \\\"test_output.raw\\\"\\n\\n        mock_file = mock_open()\\n        with patch(\\\"langflow.utils.voice_utils.Path.open\\\", mock_file):\\n            _write_bytes_to_file(test_data, filename)\\n\\n            # Verify file was opened in append binary mode\\n            mock_file.assert_called_once_with(\\\"ab\\\")\\n            # Verify data was written\\n            mock_file().write.assert_called_once_with(test_data)\\n\\n    def test_write_bytes_to_file_path_construction(self):\\n        \\\"\\\"\\\"Test that Path is constructed correctly.\\\"\\\"\\\"\\n        test_data = b\\\"\\\\x06\\\\x07\\\\x08\\\"\\n        filename = \\\"test/path/file.raw\\\"\\n\\n        with patch(\\\"langflow.utils.voice_utils.Path\\\") as mock_path:\\n            mock_path_instance = MagicMock()\\n            mock_path.return_value = mock_path_instance\\n\\n            _write_bytes_to_file(test_data, filename)\\n\\n            # Verify Path was constructed with filename\\n            mock_path.assert_called_once_with(filename)\\n            # Verify open was called in append binary mode\\n            mock_path_instance.open.assert_called_once_with(\\\"ab\\\")\\n\\n    def test_write_bytes_to_file_empty_data(self):\\n        \\\"\\\"\\\"Test writing empty bytes.\\\"\\\"\\\"\\n        empty_data = b\\\"\\\"\\n        filename = \\\"empty.raw\\\"\\n\\n        mock_file = mock_open()\\n        with patch(\\\"langflow.utils.voice_utils.Path.open\\\", mock_file):\\n            _write_bytes_to_file(empty_data, filename)\\n\\n            # Should still attempt to write empty data\\n            mock_file().write.assert_called_once_with(empty_data)\\n\\n    def test_write_bytes_to_file_large_data(self):\\n        \\\"\\\"\\\"Test writing large bytes.\\\"\\\"\\\"\\n        large_data = b\\\"\\\\xff\\\" * 50000\\n        filename = \\\"large.raw\\\"\\n\\n        mock_file = mock_open()\\n        with patch(\\\"langflow.utils.voice_utils.Path.open\\\", mock_file):\\n            _write_bytes_to_file(large_data, filename)\\n\\n            # Should write all data\\n            mock_file().write.assert_called_once_with(large_data)\\n\\n    def test_write_bytes_to_file_append_mode(self):\\n        \\\"\\\"\\\"Test that file is opened in append mode.\\\"\\\"\\\"\\n        test_data = b\\\"\\\\x10\\\\x11\\\\x12\\\"\\n        filename = \\\"append_test.raw\\\"\\n\\n        mock_file = mock_open()\\n        with patch(\\\"langflow.utils.voice_utils.Path.open\\\", mock_file):\\n            _write_bytes_to_file(test_data, filename)\\n\\n            # Verify append binary mode\\n            mock_file.assert_called_once_with(\\\"ab\\\")\\n\\n    def test_write_bytes_to_file_context_manager(self):\\n        \\\"\\\"\\\"Test that file is properly closed using context manager.\\\"\\\"\\\"\\n        test_data = b\\\"\\\\x13\\\\x14\\\\x15\\\"\\n        filename = \\\"context_test.raw\\\"\\n\\n        mock_file = mock_open()\\n        with patch(\\\"langflow.utils.voice_utils.Path.open\\\", mock_file):\\n            _write_bytes_to_file(test_data, filename)\\n\\n            # Verify context manager was used (enter and exit called)\\n            mock_file().__enter__.assert_called_once()\\n            mock_file().__exit__.assert_called_once()\\n\\n    def test_write_bytes_to_file_multiple_calls(self):\\n        \\\"\\\"\\\"Test multiple calls to write_bytes_to_file.\\\"\\\"\\\"\\n        data1 = b\\\"\\\\x20\\\\x21\\\"\\n        data2 = b\\\"\\\\x22\\\\x23\\\"\\n        filename = \\\"multi_test.raw\\\"\\n\\n        mock_file = mock_open()\\n        with patch(\\\"langflow.utils.voice_utils.Path.open\\\", mock_file):\\n            _write_bytes_to_file(data1, filename)\\n            _write_bytes_to_file(data2, filename)\\n\\n            # Should have been called twice\\n            assert mock_file.call_count == 2\\n            # Both calls should use append mode\\n            assert all(call[0] == (\\\"ab\\\",) for call in mock_file.call_args_list)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/NIGHTLY.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"86cc8f15661e63283d5c0e8ce0a940ba8615f88ef6f342ca53ebee3db349359c\",\"content\":\"# Canonical nightly releases\\n\\nNightlies use the canonical package names with coordinated `.devN` versions.\\nThey do not publish parallel `*-nightly` Python distributions.\\n\\n## Version chain\\n\\nThe workflow derives one coordinated Langflow development version from the\\ncanonical histories of `langflow`, `langflow-base`, `lfx`, and\\n`langflow-sdk`.\\n\\nThe dependency chain is exact for a nightly:\\n\\n```text\\nlangflow==X.Y.Z.devN\\n  -> langflow-base==X.Y.Z.devN\\n      -> lfx==X.Y.Z.devN\\n```\\n\\nThe SDK uses the same coordinated version. Standalone extension distributions\\nretain their canonical names and their bounded LFX compatibility ranges.\\nAffected extension wheels are built and published before `langflow-base`.\\n\\n## Publish order\\n\\nThe release workflow publishes in dependency order:\\n\\n1. `langflow-sdk`\\n2. `lfx`\\n3. affected `lfx-*` extension distributions\\n4. `langflow-base`\\n5. `langflow`\\n\\nThe `langflow-base` and `langflow` versions must match. A base-only or\\nfull-only nightly version is not supported.\\n\\n## Installing a nightly\\n\\nUse prerelease resolution with the canonical package name:\\n\\n```bash\\nuv pip install --pre langflow\\n```\\n\\nFor the runnable application without provider extensions:\\n\\n```bash\\nuv pip install --pre langflow-base\\n```\\n\\nBoth packages provide the `langflow` command.\\n\\n## Dry runs\\n\\nThe release workflow retains its `dry_run` input. A dry run may use a release\\ntag, immutable commit SHA, or pull-request ref. It builds and validates every\\nselected wheel and image, but disables PyPI publication, registry publication,\\ntag creation, and GitHub Release writes.\\n\\n## Verification\\n\\n- Confirm the root and base versions match before building.\\n- Inspect wheel metadata for exact nightly pins through the SDK/LFX/base/full\\n  dependency chain.\\n- Install the local wheels together and run `pip check`.\\n- Confirm base contains no provider `lfx-*`, PyTorch, or TorchVision\\n  distributions.\\n- Confirm full discovers the curated extensions.\\n- Run `scripts/ci/test_pypi_nightly_tag.py` and the release workflow contract\\n  tests before enabling publication.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/PORTING.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"56a41c8fa637e02582516dc1f259c68069b4979e146c952fef9f21c6bbb6b651\",\"content\":\"# Porting a component from `lfx.components.<provider>` to `src/bundles/<provider>`\\n\\nThis is the step-by-step recipe for extracting a provider package from the\\nin-tree `src/lfx/src/lfx/components/<provider>/` directory into a standalone\\nExtension Bundle distribution under `src/bundles/<provider>/`. The DuckDuckGo\\nbundle ([`src/bundles/duckduckgo`](duckduckgo/)) is the reference\\nimplementation; every section below maps to a single, copy-pasteable change\\nand a verification command.\\n\\nIf you'd rather automate the mechanical steps, use\\n[`scripts/migrate/port_bundle.py`](../../scripts/migrate/port_bundle.py)\\n(see [\u00a7 Automation](#automation)). It writes the same files this doc\\ndescribes \u2014 review the diff before committing.\\n\\n---\\n\\n## 0. Prerequisites \u2014 pick a candidate\\n\\nBefore you start, confirm the component is a good fit:\\n\\n- [ ] The provider directory `src/lfx/src/lfx/components/<provider>/` exists\\n      and contains one or more `Component` subclasses.\\n- [ ] Imports from `lfx.*` only (no `from langflow...`); the bundle is\\n      installed against the public `BUNDLE_API` surface, not Langflow internals.\\n      Check with: `grep -r \\\"from langflow\\\" src/lfx/src/lfx/components/<provider>/`\\n- [ ] No deactivated / legacy duplicate exists under `src/lfx/src/lfx/components/deactivated/<provider>/`.\\n- [ ] The runtime dependencies the component pulls in (e.g. `langchain-community`,\\n      a vendor SDK) can be declared in the bundle's `pyproject.toml` without\\n      cycling through `lfx` or `langflow-base`.\\n\\nPick the **bundle name** (snake_case, lowercase, matches the directory name \u2014\\ne.g. `duckduckgo`, `arxiv`, `wikipedia`) and the **distribution name**\\n(`lfx-<bundle>`, e.g. `lfx-duckduckgo`). These two strings are the only\\nidentifiers you'll repeat throughout the port.\\n\\n---\\n\\n## 1. Lay out the bundle directory\\n\\nCreate `src/bundles/<bundle>/` with this exact tree (mirrors\\n`src/bundles/duckduckgo/`):\\n\\n```\\nsrc/bundles/<bundle>/\\n\u251c\u2500\u2500 README.md\\n\u251c\u2500\u2500 pyproject.toml\\n\u2514\u2500\u2500 src/\\n    \u2514\u2500\u2500 lfx_<bundle>/\\n        \u251c\u2500\u2500 __init__.py\\n        \u251c\u2500\u2500 extension.json\\n        \u2514\u2500\u2500 components/\\n            \u2514\u2500\u2500 <bundle>/\\n                \u251c\u2500\u2500 __init__.py\\n                \u2514\u2500\u2500 <source>.py        # one file per component class\\n```\\n\\n> **Why nested `src/lfx_<bundle>/components/<bundle>/`?** The outer\\n> `lfx_<bundle>` is the importable Python package (matches the wheel layout\\n> `importlib.metadata.files()` walks). The inner `components/<bundle>/`\\n> is the path declared in `extension.json:bundles[].path` \u2014 keeping it as\\n> `components/<bundle>` means saved flows that referenced\\n> `lfx.components.<bundle>.<file>.<Class>` migrate cleanly via a single\\n> import-path entry in the migration table.\\n\\n### 1a. `pyproject.toml`\\n\\nCopy [`src/bundles/duckduckgo/pyproject.toml`](duckduckgo/pyproject.toml) and\\nsubstitute names + the runtime-dep block. The non-obvious bits:\\n\\n- `dependencies` lists every runtime dep the component imports. Floor `lfx`\\n  at the current Langflow/LFX `major.minor` line and cap below the next `lfx`\\n  major \u2014 e.g. `\\\"lfx>=1.10.0,<2.0.0\\\"`. You normally don't hand-write this:\\n  `port_bundle.py` fills it in from `src/lfx/pyproject.toml` at port time, and\\n  `make patch` re-syncs every existing bundle via\\n  [`scripts/ci/sync_bundle_lfx_pin.py`](../../scripts/ci/sync_bundle_lfx_pin.py).\\n  Fine-grained BUNDLE_API compatibility is enforced separately via\\n  `extension.json`'s `\\\"lfx\\\": {\\\"compat\\\": [...]}` contract against the running\\n  lfx's `BUNDLE_API_VERSION`, not the version cap.\\n- **Platform-gated deps:** if a runtime dep has no wheel on some platform\\n  (e.g. `ibm-db` ships none for linux/aarch64), gate it with a PEP 508 marker\\n  so `pip install langflow` still succeeds there, e.g.\\n  `\\\"ibm-db>=3.2.9,<4.0.0; sys_platform != 'linux' or platform_machine != 'aarch64'\\\"`.\\n  Import that dep *lazily* (inside the method that uses it, not at module top\\n  level) so the bundle still loads on the excluded platform and the affected\\n  component degrades gracefully instead of breaking discovery. The\\n  cross-platform install test gates a hard-dep bundle through langflow's main\\n  install; if the **bundle itself** (not just a transitive dep) cannot install\\n  on a platform, also add the same marker to its dependency line in the root\\n  [`pyproject.toml`](../../pyproject.toml) so langflow does not require it there.\\n- `[project.entry-points.\\\"langflow.extensions\\\"]`: `<dist-name> = \\\"lfx_<bundle>\\\"`.\\n  This is what `lfx.extension.loader._plugins._manifest_via_entry_point`\\n  reads to find the manifest; an editable install with no `dist.files`\\n  visibility falls back to this entry point.\\n- `[tool.hatch.build.targets.wheel]` MUST include\\n  `src/lfx_<bundle>/extension.json` and the components glob \u2014 wheel\\n  installs read the manifest via `dist.files` and skip the bundle if the\\n  file isn't packaged.\\n\\n### 1b. `src/lfx_<bundle>/extension.json`\\n\\n```json\\n{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-<bundle>\\\",\\n  \\\"version\\\": \\\"0.1.0\\\",\\n  \\\"name\\\": \\\"<Human-readable bundle name>\\\",\\n  \\\"description\\\": \\\"<One-line description>.\\\",\\n  \\\"lfx\\\": { \\\"compat\\\": [\\\"1\\\"] },\\n  \\\"bundles\\\": [\\n    { \\\"name\\\": \\\"<bundle>\\\", \\\"path\\\": \\\"components/<bundle>\\\" }\\n  ]\\n}\\n```\\n\\nThe `id` is the distribution name (with a hyphen). The `bundles[0].name`\\nis the snake_case bundle name used in saved-flow IDs\\n(`ext:<bundle>:<Class>@official`). They differ by one character (`-` vs\\n`_`); don't mix them up.\\n\\n### 1c. `src/lfx_<bundle>/__init__.py`\\n\\nRe-export the component class(es) from the package root so\\n`lfx_<bundle>.<Class>` resolves. The migration table's `bare_class_name`\\nentry depends on this import working.\\n\\n```python\\n\\\"\\\"\\\"lfx-<bundle>: <description>.\\\"\\\"\\\"\\n\\nfrom lfx_<bundle>.components.<bundle>.<source> import <Class>\\n\\n__all__ = [\\\"<Class>\\\"]\\n```\\n\\n### 1d. `src/lfx_<bundle>/components/<bundle>/__init__.py`\\n\\n```python\\nfrom .<source> import <Class>\\n\\n__all__ = [\\\"<Class>\\\"]\\n```\\n\\n### 1e. `src/lfx_<bundle>/components/<bundle>/<source>.py`\\n\\nThis is the **moved** file. Copy it byte-for-byte from\\n`src/lfx/src/lfx/components/<bundle>/<source>.py` \u2014 do **not** rewrite\\nimports. The component's `from lfx.*` imports work unchanged because\\n`lfx` is a runtime dep of the bundle.\\n\\n### 1f. `README.md`\\n\\nA short page explaining what the bundle ships, how to install it, and how\\nto develop against it. Use [`duckduckgo/README.md`](duckduckgo/README.md)\\nas the template.\\n\\n---\\n\\n## 2. Remove the in-tree component\\n\\nDelete the whole legacy directory:\\n\\n```bash\\ngit rm -r src/lfx/src/lfx/components/<bundle>/\\n```\\n\\nThen surgically remove the three references in\\n[`src/lfx/src/lfx/components/__init__.py`](../lfx/src/lfx/components/__init__.py):\\n\\n1. The `<bundle>,` line in the import block (around line 10).\\n2. The `\\\"<bundle>\\\": \\\"__module__\\\",` entry in the type-mapping dict.\\n3. The `\\\"<bundle>\\\",` string in the `__all__`-style list.\\n\\n> **Sanity check:** after the edit,\\n> `grep -n \\\"<bundle>\\\" src/lfx/src/lfx/components/__init__.py` returns\\n> nothing.\\n\\n---\\n\\n## 3. Wire the workspace\\n\\n### 3a. Root [`pyproject.toml`](../../pyproject.toml)\\n\\nThree edits \u2014 all mechanical:\\n\\n```toml\\n# 1. Add to [project] dependencies (regular dep so `pip install langflow`\\n#    still pulls the component in -- no user-visible change at install time).\\ndependencies = [\\n    \\\"langflow-base~=1.12.0\\\",\\n    \\\"lfx-duckduckgo>=0.1.0\\\",\\n    \\\"lfx-<bundle>>=0.1.0\\\",                 # <-- add this line\\n]\\n\\n# 2. Add to [tool.uv.sources]\\nlfx-<bundle> = { workspace = true }\\n\\n# 3. Add to [tool.uv.workspace] members\\nmembers = [\\n    \\\"src/backend/base\\\",\\n    \\\".\\\",\\n    \\\"src/lfx\\\",\\n    \\\"src/sdk\\\",\\n    \\\"src/bundles/duckduckgo\\\",\\n    \\\"src/bundles/<bundle>\\\",                # <-- add this line\\n]\\n```\\n\\n### 3b. `src/backend/base/pyproject.toml` (optional)\\n\\nOnly touch this if the component had a `langflow-base[<bundle>]` extra.\\nRemove the extra and any `langflow-base[<bundle>]` reference from\\n`complete`. The duckduckgo port did this; if the component had no extras\\n(e.g. arxiv), skip this section entirely.\\n\\n### 3c. Lockfile\\n\\n```bash\\nuv lock\\ngit add uv.lock\\n```\\n\\n---\\n\\n## 4. Add migration entries\\n\\nAppend to\\n[`src/lfx/src/lfx/extension/migration/migration_table.json`](../lfx/src/lfx/extension/migration/migration_table.json).\\nThe schema requires **three** legacy forms covering every shape a saved\\nflow may have used:\\n\\n```json\\n{\\n  \\\"bare_class_name\\\": \\\"<Class>\\\",\\n  \\\"target\\\": \\\"ext:<bundle>:<Class>@official\\\",\\n  \\\"added_in\\\": \\\"<release>\\\"\\n},\\n{\\n  \\\"import_path\\\": \\\"lfx.components.<bundle>.<source>.<Class>\\\",\\n  \\\"target\\\": \\\"ext:<bundle>:<Class>@official\\\",\\n  \\\"added_in\\\": \\\"<release>\\\"\\n},\\n{\\n  \\\"import_path\\\": \\\"lfx.components.<bundle>.<Class>\\\",\\n  \\\"target\\\": \\\"ext:<bundle>:<Class>@official\\\",\\n  \\\"added_in\\\": \\\"<release>\\\"\\n},\\n{\\n  \\\"legacy_slot\\\": \\\"ext:<bundle>:<Class>@official-pre-a\\\",\\n  \\\"target\\\": \\\"ext:<bundle>:<Class>@official\\\",\\n  \\\"added_in\\\": \\\"<release>\\\"\\n}\\n```\\n\\nIf the component declared multiple classes, repeat the four-entry block\\nper class (the bare-name entry is only added when the class name is\\nglobally unique across every Bundle in the release;\\n`scripts/migrate/check_bare_names.py` enforces this).\\n\\nThe migration table is **append-only**. Never remove or rewrite an\\nexisting entry \u2014 CI rejects removals so a flow saved years ago against a\\nlong-extracted bundle still loads.\\n\\n---\\n\\n## 5. Regenerate the component index\\n\\nThe pre-built component index drives lazy loading; the moved component's\\nold entry must be removed.\\n\\n```bash\\nLFX_DEV=1 uv run python scripts/build_component_index.py\\n```\\n\\n`LFX_DEV=1` forces dynamic discovery via `pkgutil.walk_packages`; without\\nit the script reads the existing index and reproduces the stale entry\\neven when the source module is gone.\\n\\nThe diff should only delete the `<bundle>` block; if it touches anything\\nelse, your local checkout has unrelated drift.\\n\\n---\\n\\n## 6. Add an integration test\\n\\nCreate\\n`src/lfx/tests/integration/extension/test_pilot_<bundle>_upgrade.py`,\\nmodelled on\\n[`test_pilot_duckduckgo_upgrade.py`](../lfx/tests/integration/extension/test_pilot_duckduckgo_upgrade.py).\\nThe four test cases that matter:\\n\\n1. Bare class name \u2192 canonical ID.\\n2. Full import path \u2192 canonical ID.\\n3. Package-level import path \u2192 canonical ID.\\n4. The `lfx-<bundle>` distribution is importable AND ships\\n   `extension.json` in a location `importlib.metadata.files` can discover\\n   (or, for editable installs, that `direct_url.json` resolves).\\n\\nThe integration test is the only place the saved-flow contract is\\nexercised end-to-end; do **not** skip it.\\n\\n### Coverage that moves with the port\\n\\nThe in-tree `test_<bundle>_component.py` under\\n`src/backend/tests/unit/components/<bundle>/` typically includes a\\n`test_component_versions` case that walks a `file_names_mapping` fixture\\nto verify saved fixtures from older schema versions still instantiate.\\nThat fixture imports from `tests.base`, which is not importable inside a\\nbundle. The new bundle-local test (`src/bundles/<bundle>/tests/`) drops\\nit, and `test_pilot_<bundle>_upgrade.py` covers namespace migration but\\nnot intra-class schema evolution.\\n\\nIf the legacy fixture had non-empty entries, replicate the version check\\nin some bundle-friendly form (parametrise the bundle test over the same\\nmapping, no `tests.base` import). If it was empty, call out the\\nregression in the PR description so reviewers can weigh in on whether\\nthe case should be replicated before merge.\\n\\n---\\n\\n## 7. Verify\\n\\nRun, in order, the smallest commands that will fail loudly when a step is\\nwrong:\\n\\n```bash\\n# 1. The bundle's manifest is structurally valid.  Point ``validate`` at\\n#    the package directory (where extension.json lives), not the bundle\\n#    root -- the manifest is nested inside ``src/lfx_<bundle>/`` so the\\n#    wheel ships it.  The validator accepts both ``def build(self): ...``\\n#    and ``outputs = [Output(method=\\\"...\\\")]`` shapes; a component that\\n#    uses neither will fail with ``build-method-missing`` -- add an\\n#    ``outputs`` declaration in that case.\\nuv run lfx extension validate src/bundles/<bundle>/src/lfx_<bundle>\\n\\n# 2. Workspace resolves and the bundle is importable.\\nuv sync\\nuv run python -c \\\"from lfx_<bundle> import <Class>; print(<Class>.__name__)\\\"\\n\\n# 3. Migration table parses and the new entries are visible.\\nuv run pytest src/lfx/tests/unit/extension/migration -q\\n\\n# 4. Loader discovers the editable install via direct_url.json.\\nuv run python -c \\\"\\nfrom lfx.extension.loader._plugins import installed_extension_roots\\nroots = installed_extension_roots()\\nassert 'lfx-<bundle>' in roots, roots\\nprint('discovered:', roots['lfx-<bundle>'])\\n\\\"\\n\\n# 5. The integration test passes.\\nuv run pytest src/lfx/tests/integration/extension/test_pilot_<bundle>_upgrade.py -q\\n\\n# 6. Ruff is clean across the touched Python files.  (Don't pass the\\n#    JSON migration table to ruff -- it lints it as Python and complains\\n#    about the top-level expression.)\\nuv run ruff check src/bundles/<bundle> src/lfx/src/lfx/components/__init__.py src/lfx/tests/integration/extension/test_pilot_<bundle>_upgrade.py\\n```\\n\\n**End-to-end smoke test** (optional but cheap): start a dev server with\\nthe bundle on the palette and click Reload.\\n\\n```bash\\nuv run lfx extension dev src/bundles/<bundle>\\n# In a browser at http://localhost:7860:\\n#   - Confirm <Class> appears under the <bundle> bundle group.\\n#   - Right-click the <bundle> header -> Reload. No errors.\\n```\\n\\n### Release-plan and version changes\\n\\nAny releasable change under `src/bundles/<bundle>/src/` or to the bundle's\\n`pyproject.toml` requires a distribution-version increase. Generate the same\\nplan CI reviews without changing files:\\n\\n```bash\\npython scripts/ci/bundle_release_plan.py plan \\\\\\n  --base-ref origin/release-1.11.0 \\\\\\n  --check \\\\\\n  --output bundle-release-plan.json\\n```\\n\\nTo apply the plan, use the update command instead of editing version fields by\\nhand. It bumps affected bundles by one patch by default, synchronizes their\\n`extension.json` versions and LFX ranges, raises every matching Langflow\\ndependency floor, and regenerates `uv.lock` as one rollback-safe operation:\\n\\n```bash\\npython scripts/ci/bundle_release_plan.py update \\\\\\n  --base-ref origin/release-1.11.0 \\\\\\n  --output bundle-release-plan.json\\n```\\n\\nUse `--bump minor` or an explicit `--version lfx-<bundle>=X.Y.Z` when a patch\\nbump is not appropriate. Release workflows upload the version/artifact plans\\nfor review and refuse to reuse an existing PyPI version unless its normalized\\nwheel content matches the wheel built by the current run. Every bundle pins\\nthe same exact Hatchling build backend so unchanged sources reproduce the\\nimmutable published wheel metadata; update that pin only as an explicit,\\nrepo-wide release migration.\\n\\n---\\n\\n## 8. Docker images (only if shipping a new bundle to the runtime image)\\n\\nThe shared [`docker/build_and_push.Dockerfile`](../../docker/build_and_push.Dockerfile)\\ncopies `src/bundles` into the build context. A curated bundle added to the root\\ndependencies is picked up by the `full` target's workspace sync. The `base`\\ntarget intentionally does not install provider extensions.\\n\\n- [`docker/build_and_push_backend.Dockerfile`](../../docker/build_and_push_backend.Dockerfile):\\n  add `./src/bundles/<bundle>` to the explicit `uv pip install` line.\\n\\nDo not add provider extensions to the base target. Validate that the full image\\ndiscovers the bundle and that the base image's distribution inventory remains\\nunchanged.\\n\\n---\\n\\n## Common pitfalls\\n\\n- **Component imports `from langflow...`**: the bundle is installed against\\n  `lfx`, not `langflow`. Either rewrite the import to use the public\\n  `BUNDLE_API` surface or leave the component in-tree.\\n- **`extension.json` not in the wheel**: `dist.files` doesn't surface it,\\n  so non-editable installs skip the bundle. Confirm the `[tool.hatch.build.targets.wheel] include` glob picks it up.\\n- **Bundle name has a hyphen**: only the *distribution* name uses\\n  hyphens (`lfx-duckduckgo`); the *bundle* name is snake_case\\n  (`duckduckgo`). The schema rejects hyphens in `bundles[].name`.\\n- **Forgot the `langflow.extensions` entry-point**: editable installs\\n  fail discovery silently \u2014 `installed_extension_roots()` returns an\\n  empty dict and the bundle never enters the registry.\\n- **Migration entries missing**: saved flows still validate, but the\\n  palette can't render the legacy node \u2014 the user sees a \\\"component not\\n  found\\\" toast. The four-entry block in step 4 covers every shape Langflow\\n  has serialized in the past.\\n\\n---\\n\\n## Automation\\n\\n[`scripts/migrate/port_bundle.py`](../../scripts/migrate/port_bundle.py)\\ngenerates the bundle skeleton, removes the in-tree directory, edits the\\ntwo `__init__.py` references, and patches the root `pyproject.toml`. It\\n**does not** edit the migration table or the integration test \u2014 those\\nrequire human judgement (release version, class-name uniqueness check).\\n\\n```bash\\n# Dry run -- prints the planned changes; reviewer signs off before --apply.\\nuv run python scripts/migrate/port_bundle.py --bundle arxiv --apply\\n```\\n\\nAfter running the script, work through this doc's verification block (\u00a77);\\nif anything fails, the script's diff is the single artefact to review.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aeef99208e3ebbb169d98c7c2a1744700697324dfd07d4125a5ee95863cf56f0\",\"content\":\"# lfx-amazon\\n\\nAmazon component(s) as a standalone Langflow Extension Bundle.\\n\\n## Install\\n\\n```bash\\npip install lfx-amazon\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the bundle's\\ncomponents will appear in the palette under the `amazon` group with\\nthe namespaced IDs `ext:amazon:<Class>@official`.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/amazon\\npip install -e .\\nlfx extension validate src/lfx_amazon\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name(s) or the old import paths\\nunder `lfx.components.amazon.*` are rewritten to the new namespaced\\nIDs by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a7bd17f3303248e80b26d60fde178efcfae6d5d08ed288aef1c3ff5f01a9e28d\",\"content\":\"[project]\\nname = \\\"lfx-amazon\\\"\\nversion = \\\"0.1.6\\\"\\ndescription = \\\"Amazon component(s) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"amazon\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus any third-party imports\\n# the bundle's components rely on.  REVIEW THIS LIST -- the script ports\\n# only ``lfx``; add any other deps the moved component(s) import.\\n# lfx is floored at the current major.minor line and capped below the next\\n# lfx major (e.g. \\\"lfx>=1.11.0,<2.0.0\\\"); the floor is read from\\n# src/lfx/pyproject.toml at port time and re-synced on ``make patch`` via\\n# scripts/ci/sync_bundle_lfx_pin.py.  Fine-grained BUNDLE_API compatibility\\n# is enforced via extension.json's lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"boto3>=1.34.162,<2.0.0\\\",\\n    \\\"langchain-aws>=1.4.1,<2.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-amazon = \\\"lfx_amazon\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_amazon package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_amazon\\\"]\\ninclude = [\\n    \\\"src/lfx_amazon/extension.json\\\",\\n    \\\"src/lfx_amazon/components/**/*.py\\\",\\n]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_amazon\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/src/lfx_amazon/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c4259e1174c31750e3030fb9e6b1a62e3d0c593ffd378ae15a817fb97054d502\",\"content\":\"\\\"\\\"\\\"lfx-amazon: Amazon bundle.\\n\\nDistribution unit ``lfx-amazon``.  At runtime Langflow's loader\\ndiscovers ``extension.json`` shipped alongside this ``__init__.py`` and\\nregisters the bundle's components under the namespaced IDs\\n``ext:amazon:<Class>@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_amazon.components.amazon.amazon_bedrock_converse import AmazonBedrockConverseComponent\\nfrom lfx_amazon.components.amazon.amazon_bedrock_embedding import AmazonBedrockEmbeddingsComponent\\nfrom lfx_amazon.components.amazon.amazon_bedrock_model import AmazonBedrockComponent\\nfrom lfx_amazon.components.amazon.s3_bucket_uploader import S3BucketUploaderComponent\\n\\n__all__ = [\\n    \\\"AmazonBedrockComponent\\\",\\n    \\\"AmazonBedrockConverseComponent\\\",\\n    \\\"AmazonBedrockEmbeddingsComponent\\\",\\n    \\\"S3BucketUploaderComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/src/lfx_amazon/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/src/lfx_amazon/components/amazon/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"55cbe333f7ac5736a52506893226413e68dc6a38661940496b95a74abe57e757\",\"content\":\"\\\"\\\"\\\"Lazy component re-exports for the ``amazon`` bundle.\\n\\nMirrors the pre-extraction layout of ``lfx.components.amazon`` so saved\\nflows that referenced the module-level class\\n(e.g. ``lfx.components.amazon.<Class>``) keep resolving via the\\nmigration table after rewrite to\\n``lfx_amazon.components.amazon.<Class>``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .amazon_bedrock_converse import AmazonBedrockConverseComponent\\n    from .amazon_bedrock_embedding import AmazonBedrockEmbeddingsComponent\\n    from .amazon_bedrock_model import AmazonBedrockComponent\\n    from .s3_bucket_uploader import S3BucketUploaderComponent\\n\\n_dynamic_imports = {\\n    \\\"AmazonBedrockComponent\\\": \\\"amazon_bedrock_model\\\",\\n    \\\"AmazonBedrockConverseComponent\\\": \\\"amazon_bedrock_converse\\\",\\n    \\\"AmazonBedrockEmbeddingsComponent\\\": \\\"amazon_bedrock_embedding\\\",\\n    \\\"S3BucketUploaderComponent\\\": \\\"s3_bucket_uploader\\\",\\n}\\n\\n__all__ = [\\n    \\\"AmazonBedrockComponent\\\",\\n    \\\"AmazonBedrockConverseComponent\\\",\\n    \\\"AmazonBedrockEmbeddingsComponent\\\",\\n    \\\"S3BucketUploaderComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module {__name__!r} has no attribute {attr_name!r}\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import {attr_name!r} from {__name__!r}: {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/src/lfx_amazon/components/amazon/amazon_bedrock_converse.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5101a3f7a8e5e5b744aeaa534d24ae3b046f6b019f71c13c6d1b6a69d87167f8\",\"content\":\"from lfx.base.models.aws_constants import AWS_REGIONS, AWS_MODEL_IDs\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.inputs.inputs import BoolInput, FloatInput, IntInput, MessageTextInput, SecretStrInput\\nfrom lfx.io import DictInput, DropdownInput\\n\\n# Providers whose Bedrock models document \\\"top_k\\\" as an inference parameter, in the\\n# range this component's default sits in. The Converse API only accepts\\n# additionalModelRequestFields the target model actually supports, so sending it\\n# anywhere else makes Bedrock reject the whole call: Meta takes only\\n# prompt/temperature/top_p/max_gen_len, Amazon Titan and AI21 have no top_k, and Cohere\\n# spells it \\\"k\\\". Mistral is excluded too, despite listing top_k for text completion:\\n# Mistral Large uses the chat-completion schema, which has no top_k at all, and the\\n# text-completion models cap it below this component's default of 250. Anything outside\\n# this set can still opt in explicitly through Additional Model Fields.\\nTOP_K_PROVIDERS = frozenset({\\\"anthropic\\\"})\\n\\n# Inference profile ids are prefixed with the geography, e.g. \\\"us.anthropic...\\\";\\n# \\\"global\\\" is the worldwide-routing profile. Mirrors MODEL_ID_GEO_PREFIXES in\\n# langchain_aws.utils: ChatBedrockConverse strips exactly these before resolving the\\n# provider, so a shorter set here would drop top_k for models the library still\\n# resolves to Anthropic. Kept as a literal because the constant only exists in newer\\n# langchain-aws releases than this bundle's floor.\\n_INFERENCE_PROFILE_PREFIXES = frozenset({\\\"us\\\", \\\"eu\\\", \\\"apac\\\", \\\"global\\\", \\\"us-gov\\\", \\\"sa\\\", \\\"amer\\\", \\\"jp\\\", \\\"au\\\"})\\n\\n\\ndef _model_provider(model_id: str) -> str:\\n    \\\"\\\"\\\"Provider segment of a Bedrock model id, ignoring any cross-region prefix.\\\"\\\"\\\"\\n    parts = str(model_id or \\\"\\\").split(\\\".\\\")\\n    if len(parts) > 1 and parts[0] in _INFERENCE_PROFILE_PREFIXES:\\n        parts = parts[1:]\\n    return parts[0] if parts else \\\"\\\"\\n\\n\\nclass AmazonBedrockConverseComponent(LCModelComponent):\\n    display_name: str = \\\"Amazon Bedrock Converse\\\"\\n    description: str = (\\n        \\\"Generate text using Amazon Bedrock LLMs with the modern Converse API for improved conversation handling.\\\"\\n    )\\n    icon = \\\"Amazon\\\"\\n    name = \\\"AmazonBedrockConverseModel\\\"\\n    beta = True\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        DropdownInput(\\n            name=\\\"model_id\\\",\\n            display_name=\\\"Model ID\\\",\\n            options=AWS_MODEL_IDs,\\n            value=\\\"anthropic.claude-3-5-sonnet-20241022-v2:0\\\",\\n            info=\\\"List of available model IDs to choose from.\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_access_key_id\\\",\\n            display_name=\\\"AWS Access Key ID\\\",\\n            info=\\\"The access key for your AWS account. \\\"\\n            \\\"Usually set in Python code as the environment variable 'AWS_ACCESS_KEY_ID'.\\\",\\n            value=\\\"AWS_ACCESS_KEY_ID\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_secret_access_key\\\",\\n            display_name=\\\"AWS Secret Access Key\\\",\\n            info=\\\"The secret key for your AWS account. \\\"\\n            \\\"Usually set in Python code as the environment variable 'AWS_SECRET_ACCESS_KEY'.\\\",\\n            value=\\\"AWS_SECRET_ACCESS_KEY\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_session_token\\\",\\n            display_name=\\\"AWS Session Token\\\",\\n            advanced=True,\\n            info=\\\"The session key for your AWS account. \\\"\\n            \\\"Only needed for temporary credentials. \\\"\\n            \\\"Usually set in Python code as the environment variable 'AWS_SESSION_TOKEN'.\\\",\\n            load_from_db=False,\\n        ),\\n        SecretStrInput(\\n            name=\\\"credentials_profile_name\\\",\\n            display_name=\\\"Credentials Profile Name\\\",\\n            advanced=True,\\n            info=\\\"The name of the profile to use from your \\\"\\n            \\\"~/.aws/credentials file. \\\"\\n            \\\"If not provided, the default profile will be used.\\\",\\n            load_from_db=False,\\n        ),\\n        DropdownInput(\\n            name=\\\"region_name\\\",\\n            display_name=\\\"Region Name\\\",\\n            value=\\\"us-east-1\\\",\\n            options=AWS_REGIONS,\\n            info=\\\"The AWS region where your Bedrock resources are located.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"endpoint_url\\\",\\n            display_name=\\\"Endpoint URL\\\",\\n            advanced=True,\\n            info=\\\"The URL of the Bedrock endpoint to use.\\\",\\n        ),\\n        # Model-specific parameters for fine control\\n        FloatInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.7,\\n            info=\\\"Controls randomness in output. Higher values make output more random.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Tokens\\\",\\n            value=4096,\\n            info=\\\"Maximum number of tokens to generate.\\\",\\n            advanced=True,\\n        ),\\n        FloatInput(\\n            name=\\\"top_p\\\",\\n            display_name=\\\"Top P\\\",\\n            value=0.9,\\n            info=\\\"Nucleus sampling parameter. Controls diversity of output.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"top_k\\\",\\n            display_name=\\\"Top K\\\",\\n            value=250,\\n            info=\\\"Limits the number of highest probability vocabulary tokens to consider. \\\"\\n            \\\"Only sent to Anthropic models, the ones that document it for the Converse API; it is \\\"\\n            \\\"ignored for the others. Use 'Additional Model Fields' to pass a provider's own equivalent.\\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"disable_streaming\\\",\\n            display_name=\\\"Disable Streaming\\\",\\n            value=False,\\n            info=\\\"If True, disables streaming responses. Useful for batch processing.\\\",\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"additional_model_fields\\\",\\n            display_name=\\\"Additional Model Fields\\\",\\n            advanced=True,\\n            is_list=True,\\n            info=\\\"Additional model-specific parameters for fine-tuning behavior.\\\",\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        try:\\n            from langchain_aws.chat_models.bedrock_converse import ChatBedrockConverse\\n        except ImportError as e:\\n            msg = \\\"langchain_aws is not installed. Please install it with `pip install langchain_aws`.\\\"\\n            raise ImportError(msg) from e\\n\\n        # Prepare initialization parameters\\n        init_params = {\\n            \\\"model\\\": self.model_id,\\n            \\\"region_name\\\": self.region_name,\\n        }\\n\\n        # Add AWS credentials if provided\\n        if self.aws_access_key_id:\\n            init_params[\\\"aws_access_key_id\\\"] = self.aws_access_key_id\\n        if self.aws_secret_access_key:\\n            init_params[\\\"aws_secret_access_key\\\"] = self.aws_secret_access_key\\n        if self.aws_session_token:\\n            init_params[\\\"aws_session_token\\\"] = self.aws_session_token\\n        if self.credentials_profile_name:\\n            init_params[\\\"credentials_profile_name\\\"] = self.credentials_profile_name\\n        if self.endpoint_url:\\n            init_params[\\\"endpoint_url\\\"] = self.endpoint_url\\n\\n        # Add model parameters directly as supported by ChatBedrockConverse\\n        if hasattr(self, \\\"temperature\\\") and self.temperature is not None:\\n            init_params[\\\"temperature\\\"] = self.temperature\\n        if hasattr(self, \\\"max_tokens\\\") and self.max_tokens is not None:\\n            init_params[\\\"max_tokens\\\"] = self.max_tokens\\n        if hasattr(self, \\\"top_p\\\") and self.top_p is not None:\\n            init_params[\\\"top_p\\\"] = self.top_p\\n\\n        # Handle streaming - only disable if explicitly requested\\n        if hasattr(self, \\\"disable_streaming\\\") and self.disable_streaming:\\n            init_params[\\\"disable_streaming\\\"] = True\\n\\n        # top_k is not part of the universal Converse API inferenceConfig, so it is\\n        # passed through additional_model_request_fields like other provider-specific fields.\\n        additional_model_request_fields = {}\\n        if hasattr(self, \\\"top_k\\\") and self.top_k is not None and _model_provider(self.model_id) in TOP_K_PROVIDERS:\\n            additional_model_request_fields[\\\"top_k\\\"] = self.top_k\\n\\n        # additional_model_fields lets users override or extend provider-specific fields,\\n        # including using a different key for providers that don't accept \\\"top_k\\\".\\n        if hasattr(self, \\\"additional_model_fields\\\") and self.additional_model_fields:\\n            for field in self.additional_model_fields:\\n                if isinstance(field, dict):\\n                    additional_model_request_fields.update(field)\\n\\n        # Only add if we have actual additional fields\\n        if additional_model_request_fields:\\n            init_params[\\\"additional_model_request_fields\\\"] = additional_model_request_fields\\n\\n        try:\\n            output = ChatBedrockConverse(**init_params)\\n        except Exception as e:\\n            # Provide helpful error message with fallback suggestions\\n            error_details = str(e)\\n            if \\\"validation error\\\" in error_details.lower():\\n                msg = (\\n                    f\\\"ChatBedrockConverse validation error: {error_details}. \\\"\\n                    f\\\"This may be due to incompatible parameters for model '{self.model_id}'. \\\"\\n                    f\\\"Consider adjusting the model parameters or trying the legacy Amazon Bedrock component.\\\"\\n                )\\n            elif \\\"converse api\\\" in error_details.lower():\\n                msg = (\\n                    f\\\"Converse API error: {error_details}. \\\"\\n                    f\\\"The model '{self.model_id}' may not support the Converse API. \\\"\\n                    f\\\"Try using the legacy Amazon Bedrock component instead.\\\"\\n                )\\n            else:\\n                msg = f\\\"Could not initialize ChatBedrockConverse: {error_details}\\\"\\n            raise ValueError(msg) from e\\n\\n        return output\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/src/lfx_amazon/components/amazon/amazon_bedrock_embedding.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"70d039ff79f091e8164b7058ef921f8cec29a3e83c76983e120b502528155df8\",\"content\":\"from lfx.base.models.aws_constants import AWS_EMBEDDING_MODEL_IDS, AWS_REGIONS\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.inputs.inputs import SecretStrInput\\nfrom lfx.io import DropdownInput, MessageTextInput, Output\\n\\n\\nclass AmazonBedrockEmbeddingsComponent(LCModelComponent):\\n    display_name: str = \\\"Amazon Bedrock Embeddings\\\"\\n    description: str = \\\"Generate embeddings using Amazon Bedrock models.\\\"\\n    icon = \\\"Amazon\\\"\\n    name = \\\"AmazonBedrockEmbeddings\\\"\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"model_id\\\",\\n            display_name=\\\"Model Id\\\",\\n            options=AWS_EMBEDDING_MODEL_IDS,\\n            value=\\\"amazon.titan-embed-text-v1\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_access_key_id\\\",\\n            display_name=\\\"AWS Access Key ID\\\",\\n            info=\\\"The access key for your AWS account.\\\"\\n            \\\"Usually set in Python code as the environment variable 'AWS_ACCESS_KEY_ID'.\\\",\\n            value=\\\"AWS_ACCESS_KEY_ID\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_secret_access_key\\\",\\n            display_name=\\\"AWS Secret Access Key\\\",\\n            info=\\\"The secret key for your AWS account. \\\"\\n            \\\"Usually set in Python code as the environment variable 'AWS_SECRET_ACCESS_KEY'.\\\",\\n            value=\\\"AWS_SECRET_ACCESS_KEY\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_session_token\\\",\\n            display_name=\\\"AWS Session Token\\\",\\n            advanced=False,\\n            info=\\\"The session key for your AWS account. \\\"\\n            \\\"Only needed for temporary credentials. \\\"\\n            \\\"Usually set in Python code as the environment variable 'AWS_SESSION_TOKEN'.\\\",\\n            value=\\\"AWS_SESSION_TOKEN\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"credentials_profile_name\\\",\\n            display_name=\\\"Credentials Profile Name\\\",\\n            advanced=True,\\n            info=\\\"The name of the profile to use from your \\\"\\n            \\\"~/.aws/credentials file. \\\"\\n            \\\"If not provided, the default profile will be used.\\\",\\n            value=\\\"AWS_CREDENTIALS_PROFILE_NAME\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"region_name\\\",\\n            display_name=\\\"Region Name\\\",\\n            value=\\\"us-east-1\\\",\\n            options=AWS_REGIONS,\\n            info=\\\"The AWS region where your Bedrock resources are located.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"endpoint_url\\\",\\n            display_name=\\\"Endpoint URL\\\",\\n            advanced=True,\\n            info=\\\"The URL of the AWS Bedrock endpoint to use.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Embeddings\\\", name=\\\"embeddings\\\", method=\\\"build_embeddings\\\"),\\n    ]\\n\\n    def build_embeddings(self) -> Embeddings:\\n        try:\\n            from langchain_aws import BedrockEmbeddings\\n        except ImportError as e:\\n            msg = \\\"langchain_aws is not installed. Please install it with `pip install langchain_aws`.\\\"\\n            raise ImportError(msg) from e\\n        try:\\n            import boto3\\n        except ImportError as e:\\n            msg = \\\"boto3 is not installed. Please install it with `pip install boto3`.\\\"\\n            raise ImportError(msg) from e\\n        if self.aws_access_key_id or self.aws_secret_access_key:\\n            session = boto3.Session(\\n                aws_access_key_id=self.aws_access_key_id,\\n                aws_secret_access_key=self.aws_secret_access_key,\\n                aws_session_token=self.aws_session_token,\\n            )\\n        elif self.credentials_profile_name:\\n            session = boto3.Session(profile_name=self.credentials_profile_name)\\n        else:\\n            session = boto3.Session()\\n\\n        client_params = {}\\n        if self.endpoint_url:\\n            client_params[\\\"endpoint_url\\\"] = self.endpoint_url\\n        if self.region_name:\\n            client_params[\\\"region_name\\\"] = self.region_name\\n\\n        boto3_client = session.client(\\\"bedrock-runtime\\\", **client_params)\\n        return BedrockEmbeddings(\\n            credentials_profile_name=self.credentials_profile_name,\\n            client=boto3_client,\\n            model_id=self.model_id,\\n            endpoint_url=self.endpoint_url,\\n            region_name=self.region_name,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/src/lfx_amazon/components/amazon/amazon_bedrock_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"922093a831b62ab6ded22e58046f54383c7035307d78f6702df80d311f755304\",\"content\":\"from lfx.base.models.aws_constants import AWS_REGIONS, AWS_MODEL_IDs\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.inputs.inputs import MessageTextInput, SecretStrInput\\nfrom lfx.io import DictInput, DropdownInput\\n\\n\\nclass AmazonBedrockComponent(LCModelComponent):\\n    display_name: str = \\\"Amazon Bedrock\\\"\\n    description: str = (\\n        \\\"Generate text using Amazon Bedrock LLMs with the legacy ChatBedrock API. \\\"\\n        \\\"This component is deprecated. Please use Amazon Bedrock Converse instead \\\"\\n        \\\"for better compatibility, newer features, and improved conversation handling.\\\"\\n    )\\n    icon = \\\"Amazon\\\"\\n    name = \\\"AmazonBedrockModel\\\"\\n    legacy = True\\n    replacement = \\\"amazon.AmazonBedrockConverseModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        DropdownInput(\\n            name=\\\"model_id\\\",\\n            display_name=\\\"Model ID\\\",\\n            options=AWS_MODEL_IDs,\\n            value=\\\"anthropic.claude-3-haiku-20240307-v1:0\\\",\\n            info=\\\"List of available model IDs to choose from.\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_access_key_id\\\",\\n            display_name=\\\"AWS Access Key ID\\\",\\n            info=\\\"The access key for your AWS account.\\\"\\n            \\\"Usually set in Python code as the environment variable 'AWS_ACCESS_KEY_ID'.\\\",\\n            value=\\\"AWS_ACCESS_KEY_ID\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_secret_access_key\\\",\\n            display_name=\\\"AWS Secret Access Key\\\",\\n            info=\\\"The secret key for your AWS account. \\\"\\n            \\\"Usually set in Python code as the environment variable 'AWS_SECRET_ACCESS_KEY'.\\\",\\n            value=\\\"AWS_SECRET_ACCESS_KEY\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_session_token\\\",\\n            display_name=\\\"AWS Session Token\\\",\\n            advanced=False,\\n            info=\\\"The session key for your AWS account. \\\"\\n            \\\"Only needed for temporary credentials. \\\"\\n            \\\"Usually set in Python code as the environment variable 'AWS_SESSION_TOKEN'.\\\",\\n            load_from_db=False,\\n        ),\\n        SecretStrInput(\\n            name=\\\"credentials_profile_name\\\",\\n            display_name=\\\"Credentials Profile Name\\\",\\n            advanced=True,\\n            info=\\\"The name of the profile to use from your \\\"\\n            \\\"~/.aws/credentials file. \\\"\\n            \\\"If not provided, the default profile will be used.\\\",\\n            load_from_db=False,\\n        ),\\n        DropdownInput(\\n            name=\\\"region_name\\\",\\n            display_name=\\\"Region Name\\\",\\n            value=\\\"us-east-1\\\",\\n            options=AWS_REGIONS,\\n            info=\\\"The AWS region where your Bedrock resources are located.\\\",\\n        ),\\n        DictInput(\\n            name=\\\"model_kwargs\\\",\\n            display_name=\\\"Model Kwargs\\\",\\n            advanced=True,\\n            is_list=True,\\n            info=\\\"Additional keyword arguments to pass to the model.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"endpoint_url\\\",\\n            display_name=\\\"Endpoint URL\\\",\\n            advanced=True,\\n            info=\\\"The URL of the Bedrock endpoint to use.\\\",\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        try:\\n            from langchain_aws import ChatBedrock\\n        except ImportError as e:\\n            msg = \\\"langchain_aws is not installed. Please install it with `pip install langchain_aws`.\\\"\\n            raise ImportError(msg) from e\\n        try:\\n            import boto3\\n        except ImportError as e:\\n            msg = \\\"boto3 is not installed. Please install it with `pip install boto3`.\\\"\\n            raise ImportError(msg) from e\\n        if self.aws_access_key_id or self.aws_secret_access_key:\\n            try:\\n                session = boto3.Session(\\n                    aws_access_key_id=self.aws_access_key_id,\\n                    aws_secret_access_key=self.aws_secret_access_key,\\n                    aws_session_token=self.aws_session_token,\\n                )\\n            except Exception as e:\\n                msg = \\\"Could not create a boto3 session.\\\"\\n                raise ValueError(msg) from e\\n        elif self.credentials_profile_name:\\n            session = boto3.Session(profile_name=self.credentials_profile_name)\\n        else:\\n            session = boto3.Session()\\n\\n        client_params = {}\\n        if self.endpoint_url:\\n            client_params[\\\"endpoint_url\\\"] = self.endpoint_url\\n        if self.region_name:\\n            client_params[\\\"region_name\\\"] = self.region_name\\n\\n        boto3_client = session.client(\\\"bedrock-runtime\\\", **client_params)\\n        try:\\n            output = ChatBedrock(\\n                client=boto3_client,\\n                model_id=self.model_id,\\n                region_name=self.region_name,\\n                model_kwargs=self.model_kwargs,\\n                endpoint_url=self.endpoint_url,\\n                streaming=self.stream,\\n            )\\n        except Exception as e:\\n            msg = \\\"Could not connect to AmazonBedrock API.\\\"\\n            raise ValueError(msg) from e\\n        return output\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/src/lfx_amazon/components/amazon/s3_bucket_uploader.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"119c89b6bd4039a779760e70afe2bd4f05f20a309b6fa53934f578d676098a2e\",\"content\":\"from pathlib import Path\\nfrom typing import Any\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import (\\n    BoolInput,\\n    DropdownInput,\\n    HandleInput,\\n    Output,\\n    SecretStrInput,\\n    StrInput,\\n)\\n\\n\\nclass S3BucketUploaderComponent(Component):\\n    \\\"\\\"\\\"S3BucketUploaderComponent is a component responsible for uploading files to an S3 bucket.\\n\\n    It provides two strategies for file upload: \\\"By Data\\\" and \\\"By File Name\\\". The component\\n    requires AWS credentials and bucket details as inputs and processes files accordingly.\\n\\n    Attributes:\\n        display_name (str): The display name of the component.\\n        description (str): A brief description of the components functionality.\\n        icon (str): The icon representing the component.\\n        name (str): The internal name of the component.\\n        inputs (list): A list of input configurations required by the component.\\n        outputs (list): A list of output configurations provided by the component.\\n\\n    Methods:\\n        process_files() -> None:\\n            Processes files based on the selected strategy. Calls the appropriate method\\n            based on the strategy attribute.\\n        process_files_by_data() -> None:\\n            Processes and uploads files to an S3 bucket based on the data inputs. Iterates\\n            over the data inputs, logs the file path and text content, and uploads each file\\n            to the specified S3 bucket if both file path and text content are available.\\n        process_files_by_name() -> None:\\n            Processes and uploads files to an S3 bucket based on their names. Iterates through\\n            the list of data inputs, retrieves the file path from each data item, and uploads\\n            the file to the specified S3 bucket if the file path is available. Logs the file\\n            path being uploaded.\\n        _s3_client() -> Any:\\n            Creates and returns an S3 client using the provided AWS access key ID and secret\\n            access key.\\n\\n        Please note that this component requires the boto3 library to be installed. It is designed\\n        to work with File and Director components as inputs\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"S3 Bucket Uploader\\\"\\n    description = \\\"Uploads files to S3 bucket.\\\"\\n    icon = \\\"Amazon\\\"\\n    name = \\\"s3bucketuploader\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"aws_access_key_id\\\",\\n            display_name=\\\"AWS Access Key ID\\\",\\n            required=True,\\n            password=True,\\n            info=\\\"AWS Access key ID.\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"aws_secret_access_key\\\",\\n            display_name=\\\"AWS Secret Key\\\",\\n            required=True,\\n            password=True,\\n            info=\\\"AWS Secret Key.\\\",\\n        ),\\n        StrInput(\\n            name=\\\"bucket_name\\\",\\n            display_name=\\\"Bucket Name\\\",\\n            info=\\\"Enter the name of the bucket.\\\",\\n            advanced=False,\\n        ),\\n        DropdownInput(\\n            name=\\\"strategy\\\",\\n            display_name=\\\"Strategy for file upload\\\",\\n            options=[\\\"Store Data\\\", \\\"Store Original File\\\"],\\n            value=\\\"By Data\\\",\\n            info=(\\n                \\\"Choose the strategy to upload the file. By Data means that the source file \\\"\\n                \\\"is parsed and stored as LangFlow data. By File Name means that the source \\\"\\n                \\\"file is uploaded as is.\\\"\\n            ),\\n        ),\\n        HandleInput(\\n            name=\\\"data_inputs\\\",\\n            display_name=\\\"Data Inputs\\\",\\n            info=\\\"The data to split.\\\",\\n            input_types=[\\\"Data\\\", \\\"JSON\\\"],\\n            is_list=True,\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"s3_prefix\\\",\\n            display_name=\\\"S3 Prefix\\\",\\n            info=\\\"Prefix for all files.\\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"strip_path\\\",\\n            display_name=\\\"Strip Path\\\",\\n            info=\\\"Removes path from file path.\\\",\\n            required=True,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Writes to AWS Bucket\\\", name=\\\"data\\\", method=\\\"process_files\\\"),\\n    ]\\n\\n    def process_files(self) -> None:\\n        \\\"\\\"\\\"Process files based on the selected strategy.\\n\\n        This method uses a strategy pattern to process files. The strategy is determined\\n        by the `self.strategy` attribute, which can be either \\\"By Data\\\" or \\\"By File Name\\\".\\n        Depending on the strategy, the corresponding method (`process_files_by_data` or\\n        `process_files_by_name`) is called. If an invalid strategy is provided, an error\\n        is logged.\\n\\n        Returns:\\n            None\\n        \\\"\\\"\\\"\\n        strategy_methods = {\\n            \\\"Store Data\\\": self.process_files_by_data,\\n            \\\"Store Original File\\\": self.process_files_by_name,\\n        }\\n        strategy_methods.get(self.strategy, lambda: self.log(\\\"Invalid strategy\\\"))()\\n\\n    def process_files_by_data(self) -> None:\\n        \\\"\\\"\\\"Processes and uploads files to an S3 bucket based on the data inputs.\\n\\n        This method iterates over the data inputs, logs the file path and text content,\\n        and uploads each file to the specified S3 bucket if both file path and text content\\n        are available.\\n\\n        Args:\\n            None\\n\\n        Returns:\\n            None\\n        \\\"\\\"\\\"\\n        for data_item in self.data_inputs:\\n            file_path = data_item.data.get(\\\"file_path\\\")\\n            text_content = data_item.data.get(\\\"text\\\")\\n\\n            if file_path and text_content:\\n                self._s3_client().put_object(\\n                    Bucket=self.bucket_name, Key=self._normalize_path(file_path), Body=text_content\\n                )\\n\\n    def process_files_by_name(self) -> None:\\n        \\\"\\\"\\\"Processes and uploads files to an S3 bucket based on their names.\\n\\n        Iterates through the list of data inputs, retrieves the file path from each data item,\\n        and uploads the file to the specified S3 bucket if the file path is available.\\n        Logs the file path being uploaded.\\n\\n        Returns:\\n            None\\n        \\\"\\\"\\\"\\n        for data_item in self.data_inputs:\\n            file_path = data_item.data.get(\\\"file_path\\\")\\n            self.log(f\\\"Uploading file: {file_path}\\\")\\n            if file_path:\\n                self._s3_client().upload_file(file_path, Bucket=self.bucket_name, Key=self._normalize_path(file_path))\\n\\n    def _s3_client(self) -> Any:\\n        \\\"\\\"\\\"Creates and returns an S3 client using the provided AWS access key ID and secret access key.\\n\\n        Returns:\\n            Any: A boto3 S3 client instance.\\n        \\\"\\\"\\\"\\n        try:\\n            import boto3\\n        except ImportError as e:\\n            msg = \\\"boto3 is not installed. Please install it using `uv pip install boto3`.\\\"\\n            raise ImportError(msg) from e\\n\\n        return boto3.client(\\n            \\\"s3\\\",\\n            aws_access_key_id=self.aws_access_key_id,\\n            aws_secret_access_key=self.aws_secret_access_key,\\n        )\\n\\n    def _normalize_path(self, file_path) -> str:\\n        \\\"\\\"\\\"Process the file path based on the s3_prefix and path_as_prefix.\\n\\n        Args:\\n            file_path (str): The original file path.\\n            s3_prefix (str): The S3 prefix to use.\\n            path_as_prefix (bool): Whether to use the file path as the S3 prefix.\\n\\n        Returns:\\n            str: The processed file path.\\n        \\\"\\\"\\\"\\n        prefix = self.s3_prefix\\n        strip_path = self.strip_path\\n        processed_path: str = file_path\\n\\n        if strip_path:\\n            # Filename only\\n            processed_path = Path(file_path).name\\n\\n        # Concatenate the s3_prefix if it exists\\n        if prefix:\\n            processed_path = str(Path(prefix) / processed_path)\\n\\n        return processed_path\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/src/lfx_amazon/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f03bb535a6b21881bb4bc8c3f7eb57d3ac36aed37e24bd077c1aaf635cc8df6c\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-amazon\\\",\\n  \\\"version\\\": \\\"0.1.6\\\",\\n  \\\"name\\\": \\\"Amazon\\\",\\n  \\\"description\\\": \\\"Amazon component(s) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"amazon\\\",\\n      \\\"path\\\": \\\"components/amazon\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/amazon/tests/test_amazon_bedrock_converse.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0ec4cef2a0eb7cb1293a75f301afc5e4ab561baf923531835a60d0a1a55dcfad\",\"content\":\"\\\"\\\"\\\"Regression tests: the Top K input must reach models that support it, and only those.\\\"\\\"\\\"\\n\\nimport pytest\\nfrom lfx_amazon.components.amazon.amazon_bedrock_converse import AmazonBedrockConverseComponent\\n\\n_FAKE_AWS_ACCESS_KEY_ID = \\\"AKIAFAKEFAKEFAKEFAKE\\\"  # pragma: allowlist secret\\n_FAKE_AWS_SECRET_ACCESS_KEY = \\\"fake-secret\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n\\ndef _component(**overrides) -> AmazonBedrockConverseComponent:\\n    component = AmazonBedrockConverseComponent()\\n    component.model_id = \\\"anthropic.claude-3-5-sonnet-20241022-v2:0\\\"\\n    component.aws_access_key_id = _FAKE_AWS_ACCESS_KEY_ID\\n    component.aws_secret_access_key = _FAKE_AWS_SECRET_ACCESS_KEY\\n    component.region_name = \\\"us-east-1\\\"\\n    component.temperature = 0.7\\n    component.max_tokens = 4096\\n    component.top_p = 0.9\\n    component.top_k = 250\\n    component.disable_streaming = False\\n    component.additional_model_fields = []\\n    for name, value in overrides.items():\\n        setattr(component, name, value)\\n    return component\\n\\n\\ndef test_top_k_reaches_additional_model_request_fields():\\n    model = _component(top_k=17).build_model()\\n\\n    assert model.additional_model_request_fields == {\\\"top_k\\\": 17}\\n\\n\\ndef test_user_supplied_additional_model_fields_can_override_top_k():\\n    model = _component(top_k=17, additional_model_fields=[{\\\"top_k\\\": 99}]).build_model()\\n\\n    assert model.additional_model_request_fields == {\\\"top_k\\\": 99}\\n\\n\\ndef test_top_k_omitted_when_unset():\\n    model = _component(top_k=None).build_model()\\n\\n    assert not model.additional_model_request_fields\\n\\n\\n# Meta, Amazon Titan and AI21 document no top_k at all and Cohere spells it \\\"k\\\", so\\n# Bedrock rejects the whole Converse call when top_k is sent to them. The input carries\\n# a default of 250 that every saved flow persists, so an ungated send would break flows\\n# on those providers that work today.\\n@pytest.mark.parametrize(\\n    \\\"model_id\\\",\\n    [\\n        \\\"meta.llama3-1-70b-instruct-v1:0\\\",\\n        \\\"amazon.titan-text-premier-v1:0\\\",\\n        \\\"cohere.command-r-plus-v1:0\\\",\\n        \\\"ai21.jamba-1-5-large-v1:0\\\",\\n        # Mistral Large speaks the chat-completion schema, which has no top_k, and the\\n        # text-completion models cap it below this component's default of 250.\\n        \\\"mistral.mistral-large-2407-v1:0\\\",\\n        \\\"mistral.mistral-7b-instruct-v0:2\\\",\\n    ],\\n)\\ndef test_top_k_not_sent_to_providers_without_it(model_id):\\n    model = _component(model_id=model_id, top_k=250).build_model()\\n\\n    assert not model.additional_model_request_fields\\n\\n\\n# Every geography prefix langchain-aws strips before resolving the provider\\n# (MODEL_ID_GEO_PREFIXES in langchain_aws/utils.py). ChatBedrockConverse resolves\\n# provider=\\\"anthropic\\\" for all of them, so the component must not disagree.\\n_GEO_PREFIXES = (\\\"us\\\", \\\"eu\\\", \\\"apac\\\", \\\"global\\\", \\\"us-gov\\\", \\\"sa\\\", \\\"amer\\\", \\\"jp\\\", \\\"au\\\")\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"model_id\\\",\\n    [\\n        \\\"anthropic.claude-3-5-sonnet-20241022-v2:0\\\",\\n        *(f\\\"{prefix}.anthropic.claude-3-5-sonnet-20240620-v1:0\\\" for prefix in _GEO_PREFIXES),\\n    ],\\n)\\ndef test_top_k_sent_to_providers_that_support_it(model_id):\\n    model = _component(model_id=model_id, top_k=42).build_model()\\n\\n    assert model.additional_model_request_fields == {\\\"top_k\\\": 42}\\n\\n\\n@pytest.mark.parametrize(\\\"prefix\\\", _GEO_PREFIXES)\\ndef test_top_k_still_gated_behind_the_provider_for_prefixed_ids(prefix):\\n    \\\"\\\"\\\"Stripping the geography must not turn the gate into a pass-through.\\\"\\\"\\\"\\n    model = _component(model_id=f\\\"{prefix}.meta.llama3-1-70b-instruct-v1:0\\\", top_k=250).build_model()\\n\\n    assert not model.additional_model_request_fields\\n\\n\\ndef test_additional_model_fields_still_reach_unsupported_providers():\\n    \\\"\\\"\\\"A user who knows their provider's own key can still pass it explicitly.\\\"\\\"\\\"\\n    model = _component(\\n        model_id=\\\"meta.llama3-1-70b-instruct-v1:0\\\",\\n        top_k=250,\\n        additional_model_fields=[{\\\"max_gen_len\\\": 512}],\\n    ).build_model()\\n\\n    assert model.additional_model_request_fields == {\\\"max_gen_len\\\": 512}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6f01c769f571948af8c73938514e55aeacf1236e44a69c0752d81f756bfa1ed5\",\"content\":\"# lfx-anthropic\\n\\nAnthropic component(s) as a standalone Langflow Extension Bundle.\\n\\n## Install\\n\\n```bash\\npip install lfx-anthropic\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the bundle's\\ncomponents will appear in the palette under the `anthropic` group with\\nthe namespaced IDs `ext:anthropic:<Class>@official`.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/anthropic\\npip install -e .\\nlfx extension validate src/lfx_anthropic\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name(s) or the old import paths\\nunder `lfx.components.anthropic.*` are rewritten to the new namespaced\\nIDs by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e384c5e97282c0e8d24cda8a9d61500fb152b908fd22e468d4ee29ca05e6694d\",\"content\":\"[project]\\nname = \\\"lfx-anthropic\\\"\\nversion = \\\"0.1.7\\\"\\ndescription = \\\"Anthropic component(s) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"anthropic\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus any third-party imports\\n# the bundle's components rely on.  REVIEW THIS LIST -- the script ports\\n# only ``lfx``; add any other deps the moved component(s) import.\\n# lfx is floored at the current major.minor line and capped below the next\\n# lfx major (e.g. \\\"lfx>=1.11.0,<2.0.0\\\"); the floor is read from\\n# src/lfx/pyproject.toml at port time and re-synced on ``make patch`` via\\n# scripts/ci/sync_bundle_lfx_pin.py.  Fine-grained BUNDLE_API compatibility\\n# is enforced via extension.json's lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"langchain-anthropic~=1.4.6\\\",\\n    \\\"requests>=2.32.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-anthropic = \\\"lfx_anthropic\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_anthropic package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_anthropic\\\"]\\ninclude = [\\n    \\\"src/lfx_anthropic/extension.json\\\",\\n    \\\"src/lfx_anthropic/components/**/*.py\\\",\\n]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_anthropic\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/src/lfx_anthropic/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8ab10251760016776aff0429d38ea253005d3658045fad6ed36593d1c75aee7b\",\"content\":\"\\\"\\\"\\\"lfx-anthropic: Anthropic bundle.\\n\\nDistribution unit ``lfx-anthropic``.  At runtime Langflow's loader\\ndiscovers ``extension.json`` shipped alongside this ``__init__.py`` and\\nregisters the bundle's components under the namespaced IDs\\n``ext:anthropic:<Class>@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_anthropic.components.anthropic.anthropic import AnthropicModelComponent\\n\\n__all__ = [\\n    \\\"AnthropicModelComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/src/lfx_anthropic/anthropic_chat_model.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"570aa243208c642dfe758cef5f93b01617625816844e011fc9404d7900bfa3e0\",\"content\":\"\\\"\\\"\\\"Bundle-local ChatAnthropic compatibility wrapper.\\n\\nKeep this implementation inside ``lfx-anthropic`` so the standalone bundle\\ncontinues to work with every LFX version admitted by its minor-line dependency\\nfloor. The LFX unified-model registry carries an equivalent wrapper for Agent\\nmodel construction.\\n\\\"\\\"\\\"\\n\\nfrom typing import Any\\n\\nimport anthropic\\nimport httpx\\nfrom langchain_anthropic import ChatAnthropic\\n\\n\\ndef _ensure_thinking_field(payload: dict) -> None:\\n    \\\"\\\"\\\"Backfill `thinking` on thinking blocks serialized without it.\\\"\\\"\\\"\\n    for message in payload.get(\\\"messages\\\", []):\\n        content = message.get(\\\"content\\\")\\n        if not isinstance(content, list):\\n            continue\\n        for block in content:\\n            if isinstance(block, dict) and block.get(\\\"type\\\") == \\\"thinking\\\" and block.get(\\\"thinking\\\") is None:\\n                block[\\\"thinking\\\"] = \\\"\\\"\\n\\n\\ndef _install_thinking_compat() -> type[ChatAnthropic]:\\n    \\\"\\\"\\\"Patch ChatAnthropic's request hook once without rebuilding its Pydantic model.\\\"\\\"\\\"\\n    original_get_request_payload = getattr(ChatAnthropic, \\\"_get_request_payload\\\")  # noqa: B009\\n    if getattr(original_get_request_payload, \\\"__lfx_thinking_compat__\\\", False):\\n        return ChatAnthropic\\n\\n    def get_request_payload_with_thinking_compat(self: ChatAnthropic, *args: Any, **kwargs: Any) -> dict:\\n        payload = original_get_request_payload(self, *args, **kwargs)\\n        _ensure_thinking_field(payload)\\n        return payload\\n\\n    setattr(get_request_payload_with_thinking_compat, \\\"__lfx_thinking_compat__\\\", True)  # noqa: B010\\n    setattr(ChatAnthropic, \\\"_get_request_payload\\\", get_request_payload_with_thinking_compat)  # noqa: B010\\n    return ChatAnthropic\\n\\n\\n# Do not subclass ChatAnthropic here. Pydantic 2.14 can leave its inherited\\n# fields deferred during server startup; rebuilding a subclass then resolves\\n# those fields without their defaults. Patch the request hook once and keep the\\n# already-supported ChatAnthropic model and validator intact.\\nChatAnthropicThinkingCompat = _install_thinking_compat()\\n\\n\\ndef install_anthropic_ssrf_clients(\\n    model: ChatAnthropic,\\n    *,\\n    http_client: httpx.Client,\\n    http_async_client: httpx.AsyncClient,\\n) -> None:\\n    \\\"\\\"\\\"Install validated, DNS-pinned transports into ChatAnthropic's lazy SDK clients.\\\"\\\"\\\"\\n    client_params = model._client_params  # noqa: SLF001\\n    model.__dict__[\\\"_client\\\"] = anthropic.Anthropic(**client_params, http_client=http_client)\\n    model.__dict__[\\\"_async_client\\\"] = anthropic.AsyncAnthropic(**client_params, http_client=http_async_client)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/src/lfx_anthropic/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/src/lfx_anthropic/components/anthropic/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"718b98b00761dc35c0b1eb3f5993eaf1c43ad11782d8c9fd0fd5d86c539bb15a\",\"content\":\"\\\"\\\"\\\"Lazy component re-exports for the ``anthropic`` bundle.\\n\\nMirrors the pre-extraction layout of ``lfx.components.anthropic`` so saved\\nflows that referenced the module-level class\\n(e.g. ``lfx.components.anthropic.<Class>``) keep resolving via the\\nmigration table after rewrite to\\n``lfx_anthropic.components.anthropic.<Class>``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .anthropic import AnthropicModelComponent\\n\\n_dynamic_imports = {\\n    \\\"AnthropicModelComponent\\\": \\\"anthropic\\\",\\n}\\n\\n__all__ = [\\n    \\\"AnthropicModelComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module {__name__!r} has no attribute {attr_name!r}\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import {attr_name!r} from {__name__!r}: {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/src/lfx_anthropic/components/anthropic/anthropic.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6234f831b54538a96a2658f3c1166cf4ad381adb1938f02ecdbf2c1392e75265\",\"content\":\"from typing import Any, cast\\n\\nimport requests\\nfrom lfx.base.models.anthropic_constants import (\\n    ANTHROPIC_MODELS,\\n    DEFAULT_ANTHROPIC_API_URL,\\n    TOOL_CALLING_SUPPORTED_ANTHROPIC_MODELS,\\n    TOOL_CALLING_UNSUPPORTED_ANTHROPIC_MODELS,\\n)\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.base.models.provider_ssrf import provider_httpx_clients, validate_provider_base_url\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.io import BoolInput, DropdownInput, IntInput, MessageTextInput, SecretStrInput, SliderInput\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.dotdict import dotdict\\nfrom pydantic import ValidationError\\n\\n\\nclass AnthropicModelComponent(LCModelComponent):\\n    display_name = \\\"Anthropic\\\"\\n    description = \\\"Generate text using Anthropic's Messages API and models.\\\"\\n    icon = \\\"Anthropic\\\"\\n    name = \\\"AnthropicModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Tokens\\\",\\n            advanced=True,\\n            value=4096,\\n            info=\\\"The maximum number of tokens to generate. Set to 0 for unlimited tokens.\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            options=ANTHROPIC_MODELS,\\n            refresh_button=True,\\n            value=ANTHROPIC_MODELS[0],\\n            combobox=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Anthropic API Key\\\",\\n            info=\\\"Your Anthropic API key.\\\",\\n            value=None,\\n            required=True,\\n            real_time_refresh=True,\\n        ),\\n        SliderInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.1,\\n            info=\\\"Run inference with this temperature. Must by in the closed interval [0.0, 1.0].\\\",\\n            range_spec=RangeSpec(min=0, max=1, step=0.01),\\n            advanced=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"base_url\\\",\\n            display_name=\\\"Anthropic API URL\\\",\\n            info=\\\"Endpoint of the Anthropic API. Defaults to 'https://api.anthropic.com' if not specified.\\\",\\n            value=DEFAULT_ANTHROPIC_API_URL,\\n            real_time_refresh=True,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"tool_model_enabled\\\",\\n            display_name=\\\"Enable Tool Models\\\",\\n            info=(\\n                \\\"Select if you want to use models that can work with tools. If yes, only those models will be shown.\\\"\\n            ),\\n            advanced=False,\\n            value=False,\\n            real_time_refresh=True,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        try:\\n            from lfx_anthropic.anthropic_chat_model import (\\n                ChatAnthropicThinkingCompat,\\n                install_anthropic_ssrf_clients,\\n            )\\n        except ImportError as e:\\n            msg = \\\"langchain_anthropic is not installed. Please install it with `pip install langchain_anthropic`.\\\"\\n            raise ImportError(msg) from e\\n        # base_url is tenant-editable and the SDK sends the operator's stored API key to whatever\\n        # host it names. Build protected clients before the try block below, which would otherwise\\n        # flatten an SSRF error into a generic \\\"could not connect\\\" message.\\n        ssrf_clients = provider_httpx_clients(self.base_url, default_url=DEFAULT_ANTHROPIC_API_URL)\\n        try:\\n            max_tokens_value = getattr(self, \\\"max_tokens\\\", \\\"\\\")\\n            max_tokens_value = 4096 if max_tokens_value == \\\"\\\" else int(max_tokens_value)\\n            output = ChatAnthropicThinkingCompat(\\n                model=self.model_name,\\n                anthropic_api_key=self.api_key,\\n                max_tokens=max_tokens_value,\\n                temperature=self.temperature,\\n                anthropic_api_url=self.base_url or DEFAULT_ANTHROPIC_API_URL,\\n                streaming=self.stream,\\n                stream_usage=True,\\n            )\\n            if ssrf_clients:\\n                install_anthropic_ssrf_clients(output, **ssrf_clients)\\n        except ValidationError:\\n            raise\\n        except Exception as e:\\n            msg = \\\"Could not connect to Anthropic API.\\\"\\n            raise ValueError(msg) from e\\n\\n        return output\\n\\n    def get_models(self, *, tool_model_enabled: bool | None = None) -> list[str]:\\n        # Reject unsafe custom configuration before the capability probe constructs model objects.\\n        # The live model-list request below uses Anthropic's canonical endpoint, not base_url.\\n        validate_provider_base_url(self.base_url, default_url=DEFAULT_ANTHROPIC_API_URL)\\n        try:\\n            import anthropic\\n\\n            client = anthropic.Anthropic(api_key=self.api_key)\\n            models = client.models.list(limit=20).data\\n            model_ids = ANTHROPIC_MODELS + [model.id for model in models]\\n        except (ImportError, ValueError, requests.exceptions.RequestException) as e:\\n            logger.exception(f\\\"Error getting model names: {e}\\\")\\n            model_ids = ANTHROPIC_MODELS\\n\\n        if tool_model_enabled:\\n            try:\\n                from langchain_anthropic.chat_models import ChatAnthropic\\n            except ImportError as e:\\n                msg = \\\"langchain_anthropic is not installed. Please install it with `pip install langchain_anthropic`.\\\"\\n                raise ImportError(msg) from e\\n\\n            # Create a new list instead of modifying while iterating\\n            filtered_models = []\\n            for model in model_ids:\\n                if model in TOOL_CALLING_SUPPORTED_ANTHROPIC_MODELS:\\n                    filtered_models.append(model)\\n                    continue\\n\\n                model_with_tool = ChatAnthropic(\\n                    model=model,  # Use the current model being checked\\n                    anthropic_api_key=self.api_key,\\n                    anthropic_api_url=cast(\\\"str\\\", self.base_url) or DEFAULT_ANTHROPIC_API_URL,\\n                )\\n\\n                if (\\n                    not self.supports_tool_calling(model_with_tool)\\n                    or model in TOOL_CALLING_UNSUPPORTED_ANTHROPIC_MODELS\\n                ):\\n                    continue\\n\\n                filtered_models.append(model)\\n\\n            return filtered_models\\n\\n        return model_ids\\n\\n    def _get_exception_message(self, exception: Exception) -> str | None:\\n        \\\"\\\"\\\"Get a message from an Anthropic exception.\\n\\n        Args:\\n            exception (Exception): The exception to get the message from.\\n\\n        Returns:\\n            str: The message from the exception.\\n        \\\"\\\"\\\"\\n        try:\\n            from anthropic import BadRequestError\\n        except ImportError:\\n            return None\\n        if isinstance(exception, BadRequestError):\\n            message = exception.body.get(\\\"error\\\", {}).get(\\\"message\\\")\\n            if message:\\n                return message\\n        return None\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None):\\n        if \\\"base_url\\\" in build_config and build_config[\\\"base_url\\\"][\\\"value\\\"] is None:\\n            build_config[\\\"base_url\\\"][\\\"value\\\"] = DEFAULT_ANTHROPIC_API_URL\\n            self.base_url = DEFAULT_ANTHROPIC_API_URL\\n        if field_name in {\\\"base_url\\\", \\\"model_name\\\", \\\"tool_model_enabled\\\", \\\"api_key\\\"} and field_value:\\n            try:\\n                if len(self.api_key) == 0:\\n                    ids = ANTHROPIC_MODELS\\n                else:\\n                    try:\\n                        ids = self.get_models(tool_model_enabled=self.tool_model_enabled)\\n                    except (ImportError, ValueError, requests.exceptions.RequestException) as e:\\n                        logger.exception(f\\\"Error getting model names: {e}\\\")\\n                        ids = ANTHROPIC_MODELS\\n                build_config.setdefault(\\\"model_name\\\", {})\\n                build_config[\\\"model_name\\\"][\\\"options\\\"] = ids\\n                build_config[\\\"model_name\\\"].setdefault(\\\"value\\\", ids[0])\\n                build_config[\\\"model_name\\\"][\\\"combobox\\\"] = True\\n            except Exception as e:\\n                msg = f\\\"Error getting model names: {e}\\\"\\n                raise ValueError(msg) from e\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/src/lfx_anthropic/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a39869e06c3030d615ff96ea9e8e23e79249ea1f4528f6fc5e2df06324f5bf7b\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-anthropic\\\",\\n  \\\"version\\\": \\\"0.1.7\\\",\\n  \\\"name\\\": \\\"Anthropic\\\",\\n  \\\"description\\\": \\\"Anthropic component(s) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"anthropic\\\",\\n      \\\"path\\\": \\\"components/anthropic\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/tests/test_anthropic_base_url_ssrf.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3d805ee589b6ade3e0958031828f12750f89404c1f263fda8d5b6246247d1641\",\"content\":\"\\\"\\\"\\\"SSRF regression coverage for the Anthropic model component's API URL field.\\n\\n``base_url`` is tenant-editable and is handed to the Anthropic SDK, which then issues a\\nserver-side request to that host carrying the operator's stored provider credential.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx.base.models.anthropic_constants import DEFAULT_ANTHROPIC_API_URL\\nfrom lfx.utils.ssrf_transport import SSRFProtectedSyncTransport, SSRFProtectedTransport\\nfrom lfx_anthropic.components.anthropic.anthropic import AnthropicModelComponent\\n\\n_FAKE_ANTHROPIC_API_KEY = \\\"sk-ant-not-a-real-key\\\"  # pragma: allowlist secret\\n\\nBLOCKED_URLS = [\\n    \\\"http://169.254.169.254/latest/meta-data\\\",\\n    \\\"http://10.0.0.5:8000\\\",\\n    \\\"http://192.168.1.10\\\",\\n    \\\"http://172.16.0.9\\\",\\n    \\\"http://localhost:8000\\\",\\n    \\\"http://127.0.0.1:8000\\\",\\n]\\n\\n\\ndef _component(base_url: str | None) -> AnthropicModelComponent:\\n    component = AnthropicModelComponent()\\n    component.base_url = base_url\\n    component.api_key = _FAKE_ANTHROPIC_API_KEY\\n    component.model_name = \\\"claude-3-5-sonnet-latest\\\"\\n    component.max_tokens = 100\\n    component.temperature = 0.1\\n    component.stream = False\\n    component.tool_model_enabled = False\\n    return component\\n\\n\\nclass TestAnthropicBaseUrlSSRF:\\n    @pytest.mark.parametrize(\\\"blocked_url\\\", BLOCKED_URLS)\\n    @patch(\\\"lfx_anthropic.anthropic_chat_model.ChatAnthropicThinkingCompat\\\")\\n    def test_should_block_internal_base_url_in_build_model(self, mock_chat, blocked_url):\\n        \\\"\\\"\\\"Cloud-metadata and RFC1918 API URLs must never reach the SDK.\\\"\\\"\\\"\\n        component = _component(blocked_url)\\n\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.build_model()\\n\\n        mock_chat.assert_not_called()\\n\\n    @pytest.mark.parametrize(\\\"blocked_url\\\", BLOCKED_URLS)\\n    def test_should_block_internal_base_url_in_get_models(self, blocked_url):\\n        \\\"\\\"\\\"The tool-capability probe builds its own client and must be guarded too.\\\"\\\"\\\"\\n        component = _component(blocked_url)\\n\\n        with pytest.raises(ValueError, match=\\\"SSRF Protection\\\"):\\n            component.get_models(tool_model_enabled=True)\\n\\n    @patch(\\\"lfx_anthropic.anthropic_chat_model.ChatAnthropicThinkingCompat\\\")\\n    def test_should_leave_default_endpoint_untouched(self, mock_chat):\\n        \\\"\\\"\\\"The provider default is server-chosen, so it stays a no-op.\\\"\\\"\\\"\\n        component = _component(DEFAULT_ANTHROPIC_API_URL)\\n\\n        component.build_model()\\n\\n        assert mock_chat.call_args.kwargs[\\\"anthropic_api_url\\\"] == DEFAULT_ANTHROPIC_API_URL\\n\\n    @patch(\\\"lfx_anthropic.anthropic_chat_model.ChatAnthropicThinkingCompat\\\")\\n    def test_should_respect_global_ssrf_kill_switch(self, mock_chat, monkeypatch):\\n        \\\"\\\"\\\"Operators who disable SSRF protection keep the previous unvalidated behavior.\\\"\\\"\\\"\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_PROTECTION_ENABLED\\\", \\\"false\\\")\\n        component = _component(\\\"http://10.0.0.5:8000\\\")\\n\\n        component.build_model()\\n\\n        assert mock_chat.call_args.kwargs[\\\"anthropic_api_url\\\"] == \\\"http://10.0.0.5:8000\\\"\\n\\n    def test_should_install_dns_pinned_clients_for_custom_endpoint(self, monkeypatch):\\n        monkeypatch.setattr(\\\"lfx.utils.ssrf_protection.resolve_hostname\\\", lambda _hostname: [\\\"93.184.216.34\\\"])\\n        component = _component(\\\"https://anthropic-proxy.example\\\")\\n\\n        model = component.build_model()\\n\\n        assert isinstance(model._client._client._transport, SSRFProtectedSyncTransport)\\n        assert isinstance(model._async_client._client._transport, SSRFProtectedTransport)\\n        assert model._client._client._transport.pinned_ips == {\\\"anthropic-proxy.example\\\": [\\\"93.184.216.34\\\"]}\\n        assert model._async_client._client._transport.pinned_ips == {\\\"anthropic-proxy.example\\\": [\\\"93.184.216.34\\\"]}\\n\\n    def test_should_allow_explicitly_allowlisted_loopback(self, monkeypatch):\\n        monkeypatch.setenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", \\\"127.0.0.1\\\")\\n        component = _component(\\\"http://127.0.0.1:8000\\\")\\n\\n        model = component.build_model()\\n\\n        assert model.anthropic_api_url == \\\"http://127.0.0.1:8000\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/anthropic/tests/test_anthropic_thinking_blocks.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"59e968a96fead361f25cfd93513c366fbaf2a488af86923c5249619e63c9b68c\",\"content\":\"\\\"\\\"\\\"Regression tests for Anthropic thinking-block compatibility in the bundle.\\\"\\\"\\\"\\n\\nfrom langchain_anthropic import ChatAnthropic\\nfrom langchain_core.messages import AIMessage, HumanMessage, ToolMessage\\nfrom lfx_anthropic.anthropic_chat_model import (\\n    ChatAnthropicThinkingCompat,\\n    _ensure_thinking_field,\\n    _install_thinking_compat,\\n)\\nfrom lfx_anthropic.components.anthropic.anthropic import AnthropicModelComponent\\n\\n\\ndef _malformed_history() -> list:\\n    \\\"\\\"\\\"Return a tool-use history whose thinking block is missing `thinking`.\\\"\\\"\\\"\\n    ai_message = AIMessage(\\n        content=[\\n            {\\\"type\\\": \\\"thinking\\\", \\\"signature\\\": \\\"sig==\\\", \\\"index\\\": 0},\\n            {\\n                \\\"type\\\": \\\"tool_use\\\",\\n                \\\"id\\\": \\\"toolu_01\\\",\\n                \\\"name\\\": \\\"echo\\\",\\n                \\\"input\\\": {\\\"text\\\": \\\"hello\\\"},\\n                \\\"index\\\": 1,\\n            },\\n        ],\\n        tool_calls=[{\\\"name\\\": \\\"echo\\\", \\\"args\\\": {\\\"text\\\": \\\"hello\\\"}, \\\"id\\\": \\\"toolu_01\\\", \\\"type\\\": \\\"tool_call\\\"}],\\n    )\\n    return [\\n        HumanMessage(content=\\\"Use the 'echo' tool to echo: hello\\\"),\\n        ai_message,\\n        ToolMessage(content=\\\"hello\\\", tool_call_id=\\\"toolu_01\\\"),\\n    ]\\n\\n\\ndef _thinking_blocks(payload: dict) -> list[dict]:\\n    blocks = []\\n    for message in payload.get(\\\"messages\\\", []):\\n        content = message.get(\\\"content\\\")\\n        if isinstance(content, list):\\n            blocks.extend(block for block in content if isinstance(block, dict) and block.get(\\\"type\\\") == \\\"thinking\\\")\\n    return blocks\\n\\n\\ndef _build_model() -> ChatAnthropicThinkingCompat:\\n    component = AnthropicModelComponent(\\n        model_name=\\\"claude-sonnet-5\\\",\\n        api_key=\\\"test-key\\\",  # pragma: allowlist secret\\n        max_tokens=1024,\\n        temperature=0.1,\\n        base_url=\\\"https://api.anthropic.com\\\",\\n        stream=False,\\n    )\\n    return component.build_model()\\n\\n\\ndef test_component_builds_bundle_local_compat_class():\\n    model = _build_model()\\n\\n    assert type(model) is ChatAnthropicThinkingCompat\\n    blocks = _thinking_blocks(model._get_request_payload(_malformed_history()))\\n    assert blocks\\n    assert all(block.get(\\\"thinking\\\") == \\\"\\\" for block in blocks)\\n\\n\\ndef test_payload_preserves_existing_thinking_text():\\n    model = _build_model()\\n    history = _malformed_history()\\n    history[1].content[0] = {\\n        \\\"type\\\": \\\"thinking\\\",\\n        \\\"thinking\\\": \\\"let me reason\\\",\\n        \\\"signature\\\": \\\"sig==\\\",\\n        \\\"index\\\": 0,\\n    }\\n\\n    blocks = _thinking_blocks(model._get_request_payload(history))\\n\\n    assert blocks\\n    assert blocks[0][\\\"thinking\\\"] == \\\"let me reason\\\"\\n\\n\\ndef test_compat_reuses_parent_pydantic_model_and_defaults():\\n    assert ChatAnthropicThinkingCompat is ChatAnthropic\\n    required_fields = {name for name, field in ChatAnthropicThinkingCompat.model_fields.items() if field.is_required()}\\n    assert required_fields == {\\\"model\\\"}\\n    assert ChatAnthropicThinkingCompat.model_fields[\\\"temperature\\\"].default is None\\n\\n\\ndef test_compat_install_is_idempotent():\\n    request_hook = getattr(ChatAnthropic, \\\"_get_request_payload\\\")  # noqa: B009\\n    assert _install_thinking_compat() is ChatAnthropic\\n    assert getattr(ChatAnthropic, \\\"_get_request_payload\\\") is request_hook  # noqa: B009\\n\\n\\ndef test_ensure_thinking_field_handles_missing_and_none():\\n    payload = {\\n        \\\"messages\\\": [\\n            {\\n                \\\"role\\\": \\\"assistant\\\",\\n                \\\"content\\\": [\\n                    {\\\"type\\\": \\\"thinking\\\", \\\"signature\\\": \\\"a==\\\"},\\n                    {\\\"type\\\": \\\"thinking\\\", \\\"thinking\\\": None, \\\"signature\\\": \\\"b==\\\"},\\n                    {\\\"type\\\": \\\"thinking\\\", \\\"thinking\\\": \\\"kept\\\", \\\"signature\\\": \\\"c==\\\"},\\n                    {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"hi\\\"},\\n                ],\\n            },\\n            {\\\"role\\\": \\\"user\\\", \\\"content\\\": \\\"plain string content\\\"},\\n        ]\\n    }\\n\\n    _ensure_thinking_field(payload)\\n\\n    blocks = payload[\\\"messages\\\"][0][\\\"content\\\"]\\n    assert blocks[0][\\\"thinking\\\"] == \\\"\\\"\\n    assert blocks[1][\\\"thinking\\\"] == \\\"\\\"\\n    assert blocks[2][\\\"thinking\\\"] == \\\"kept\\\"\\n    assert payload[\\\"messages\\\"][1][\\\"content\\\"] == \\\"plain string content\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/arxiv/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f909f2bf0f55a6ab5dc4bdec87c683619b960611ddd0f49982bf66604f0eb022\",\"content\":\"# lfx-arxiv\\n\\narXiv search component as a standalone Langflow Extension Bundle.\\n\\nThis is the second-pilot port that validates\\n[`src/bundles/PORTING.md`](../PORTING.md) \u2014 the documented recipe for\\nextracting an in-tree provider into a standalone Bundle distribution.\\nThe bundle ships a single component, `ArXivComponent`, which queries\\narXiv's public Atom API for paper metadata.\\n\\n## Install\\n\\n```bash\\npip install lfx-arxiv\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the\\n`ArXivComponent` will appear in the palette under the `arxiv` bundle\\ngroup.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/arxiv\\npip install -e .\\nlfx extension validate .\\n```\\n\\n## Manifest\\n\\nThe extension manifest is shipped at\\n`src/lfx_arxiv/extension.json` and points at the bundle at\\n`components/arxiv`.  Components register under the canonical\\nnamespaced ID `ext:arxiv:ArXivComponent@official`.\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name `ArXivComponent` or the\\nold import paths `lfx.components.arxiv.arxiv.ArXivComponent` /\\n`lfx.components.arxiv.ArXivComponent` are rewritten to the new\\nnamespaced ID by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/arxiv/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a757695abee71b49565aba8a1ef5a02f9024cd8afcc510dcf95ac99445850eca\",\"content\":\"[project]\\nname = \\\"lfx-arxiv\\\"\\nversion = \\\"0.1.5\\\"\\ndescription = \\\"arXiv search component as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"arxiv\\\", \\\"search\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus defusedxml for safe XML\\n# parsing (the arxiv API returns Atom).  defusedxml is already an lfx dep\\n# but we list it here as a direct runtime dep so the bundle keeps building\\n# even if lfx drops it later.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"defusedxml>=0.7.1,<1.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  The value is the dotted path to\\n# the package containing ``extension.json`` -- the loader walks\\n# ``importlib.metadata.files()`` from there to find the manifest, and\\n# falls back to this entry-point for editable installs whose dist.files\\n# only surfaces dist-info entries.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-arxiv = \\\"lfx_arxiv\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_arxiv package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_arxiv\\\"]\\ninclude = [\\\"src/lfx_arxiv/extension.json\\\", \\\"src/lfx_arxiv/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_arxiv\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/arxiv/src/lfx_arxiv/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3c580e6a03ea06a4ec6d9039cd62b2112998e83f48f42adc59b5ee042af42530\",\"content\":\"\\\"\\\"\\\"lfx-arxiv: arXiv Search bundle.\\n\\nThis package is the distribution unit ``lfx-arxiv``.  At runtime\\nLangflow's loader discovers ``extension.json`` shipped alongside this\\n``__init__.py`` and registers ``ArXivComponent`` under the namespaced\\nID ``ext:arxiv:ArXivComponent@official``.\\n\\nSecond pilot port (after lfx-duckduckgo) -- exercises the same\\nextraction recipe documented in ``src/bundles/PORTING.md`` against a\\ncomponent with no third-party runtime deps.\\n\\\"\\\"\\\"\\n\\nfrom lfx_arxiv.components.arxiv.arxiv import ArXivComponent\\n\\n__all__ = [\\\"ArXivComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/arxiv/src/lfx_arxiv/components/arxiv/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"837ba16a1896cf56402d1eb9a0115f3be866ac77092dbe47b94a9b793159d92b\",\"content\":\"from .arxiv import ArXivComponent\\n\\n__all__ = [\\\"ArXivComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/arxiv/src/lfx_arxiv/components/arxiv/arxiv.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9475ee9469744656e52bb71fdd0805a6565a8de6dd947c64f554f211d6a70023\",\"content\":\"import urllib\\nfrom xml.etree.ElementTree import Element\\n\\nfrom defusedxml.ElementTree import fromstring\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import DropdownInput, IntInput, MessageTextInput, Output\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\n\\nARXIV_REQUEST_TIMEOUT_SECONDS = 10\\n\\n\\nclass ArXivComponent(Component):\\n    display_name = \\\"arXiv\\\"\\n    description = \\\"Search and retrieve papers from arXiv.org.\\\"\\n    icon = \\\"arXiv\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"search_query\\\",\\n            display_name=\\\"Search Query\\\",\\n            info=\\\"The search query for arXiv papers (e.g., 'quantum computing')\\\",\\n            tool_mode=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"search_type\\\",\\n            display_name=\\\"Search Field\\\",\\n            info=\\\"The field to search in\\\",\\n            options=[\\\"all\\\", \\\"title\\\", \\\"abstract\\\", \\\"author\\\", \\\"cat\\\"],  # cat is for category\\n            value=\\\"all\\\",\\n        ),\\n        IntInput(\\n            name=\\\"max_results\\\",\\n            display_name=\\\"Max Results\\\",\\n            info=\\\"Maximum number of results to return\\\",\\n            value=10,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Table\\\", name=\\\"dataframe\\\", method=\\\"search_papers_dataframe\\\"),\\n    ]\\n\\n    def build_query_url(self) -> str:\\n        \\\"\\\"\\\"Build the arXiv API query URL.\\\"\\\"\\\"\\n        base_url = \\\"http://export.arxiv.org/api/query?\\\"\\n\\n        # Build the search query based on search type\\n        if self.search_type == \\\"all\\\":\\n            search_query = self.search_query  # No prefix for all fields\\n        else:\\n            # Map dropdown values to ArXiv API prefixes\\n            prefix_map = {\\\"title\\\": \\\"ti\\\", \\\"abstract\\\": \\\"abs\\\", \\\"author\\\": \\\"au\\\", \\\"cat\\\": \\\"cat\\\"}\\n            prefix = prefix_map.get(self.search_type, \\\"\\\")\\n            search_query = f\\\"{prefix}:{self.search_query}\\\"\\n\\n        # URL parameters\\n        params = {\\n            \\\"search_query\\\": search_query,\\n            \\\"max_results\\\": str(self.max_results),\\n        }\\n\\n        # Convert params to URL query string\\n        query_string = \\\"&\\\".join([f\\\"{k}={urllib.parse.quote(str(v))}\\\" for k, v in params.items()])\\n\\n        return base_url + query_string\\n\\n    def parse_atom_response(self, response_text: str) -> list[dict]:\\n        \\\"\\\"\\\"Parse the Atom XML response from arXiv.\\\"\\\"\\\"\\n        # Parse XML safely using defusedxml\\n        root = fromstring(response_text)\\n\\n        # Define namespace dictionary for XML parsing\\n        ns = {\\\"atom\\\": \\\"http://www.w3.org/2005/Atom\\\", \\\"arxiv\\\": \\\"http://arxiv.org/schemas/atom\\\"}\\n\\n        papers = []\\n        # Process each entry (paper)\\n        for entry in root.findall(\\\"atom:entry\\\", ns):\\n            paper = {\\n                \\\"id\\\": self._get_text(entry, \\\"atom:id\\\", ns),\\n                \\\"title\\\": self._get_text(entry, \\\"atom:title\\\", ns),\\n                \\\"summary\\\": self._get_text(entry, \\\"atom:summary\\\", ns),\\n                \\\"published\\\": self._get_text(entry, \\\"atom:published\\\", ns),\\n                \\\"updated\\\": self._get_text(entry, \\\"atom:updated\\\", ns),\\n                \\\"authors\\\": [author.find(\\\"atom:name\\\", ns).text for author in entry.findall(\\\"atom:author\\\", ns)],\\n                \\\"arxiv_url\\\": self._get_link(entry, \\\"alternate\\\", ns),\\n                \\\"pdf_url\\\": self._get_link(entry, \\\"related\\\", ns),\\n                \\\"comment\\\": self._get_text(entry, \\\"arxiv:comment\\\", ns),\\n                \\\"journal_ref\\\": self._get_text(entry, \\\"arxiv:journal_ref\\\", ns),\\n                \\\"primary_category\\\": self._get_category(entry, ns),\\n                \\\"categories\\\": [cat.get(\\\"term\\\") for cat in entry.findall(\\\"atom:category\\\", ns)],\\n            }\\n            papers.append(paper)\\n\\n        return papers\\n\\n    def _get_text(self, element: Element, path: str, ns: dict) -> str | None:\\n        \\\"\\\"\\\"Safely extract text from an XML element.\\\"\\\"\\\"\\n        el = element.find(path, ns)\\n        return el.text.strip() if el is not None and el.text else None\\n\\n    def _get_link(self, element: Element, rel: str, ns: dict) -> str | None:\\n        \\\"\\\"\\\"Get link URL based on relation type.\\\"\\\"\\\"\\n        for link in element.findall(\\\"atom:link\\\", ns):\\n            if link.get(\\\"rel\\\") == rel:\\n                return link.get(\\\"href\\\")\\n        return None\\n\\n    def _get_category(self, element: Element, ns: dict) -> str | None:\\n        \\\"\\\"\\\"Get primary category.\\\"\\\"\\\"\\n        cat = element.find(\\\"arxiv:primary_category\\\", ns)\\n        return cat.get(\\\"term\\\") if cat is not None else None\\n\\n    def run_model(self) -> DataFrame:\\n        return self.search_papers_dataframe()\\n\\n    def search_papers(self) -> list[Data]:\\n        \\\"\\\"\\\"Search arXiv and return results.\\\"\\\"\\\"\\n        try:\\n            # Build the query URL\\n            url = self.build_query_url()\\n\\n            # Validate URL scheme and host\\n            parsed_url = urllib.parse.urlparse(url)\\n            if parsed_url.scheme not in {\\\"http\\\", \\\"https\\\"}:\\n                error_msg = f\\\"Invalid URL scheme: {parsed_url.scheme}\\\"\\n                raise ValueError(error_msg)\\n            if parsed_url.hostname != \\\"export.arxiv.org\\\":\\n                error_msg = f\\\"Invalid host: {parsed_url.hostname}\\\"\\n                raise ValueError(error_msg)\\n\\n            # Create a custom opener that only allows http/https schemes\\n            class RestrictedHTTPHandler(urllib.request.HTTPHandler):\\n                def http_open(self, req):\\n                    return super().http_open(req)\\n\\n            class RestrictedHTTPSHandler(urllib.request.HTTPSHandler):\\n                def https_open(self, req):\\n                    return super().https_open(req)\\n\\n            # Build opener with restricted handlers\\n            opener = urllib.request.build_opener(RestrictedHTTPHandler, RestrictedHTTPSHandler)\\n            urllib.request.install_opener(opener)\\n\\n            # Make the request with validated URL using restricted opener\\n            response = opener.open(url, timeout=ARXIV_REQUEST_TIMEOUT_SECONDS)\\n            response_text = response.read().decode(\\\"utf-8\\\")\\n\\n            # Parse the response\\n            papers = self.parse_atom_response(response_text)\\n\\n            # Convert to Data objects\\n            results = [Data(data=paper) for paper in papers]\\n            self.status = results\\n        except (TimeoutError, urllib.error.URLError, ValueError) as e:\\n            error_data = Data(data={\\\"error\\\": f\\\"Request error: {e!s}\\\"})\\n            self.status = error_data\\n            return [error_data]\\n        else:\\n            return results\\n\\n    def search_papers_dataframe(self) -> DataFrame:\\n        \\\"\\\"\\\"Convert the Arxiv search results to a DataFrame.\\n\\n        Returns:\\n            DataFrame: A DataFrame containing the search results.\\n        \\\"\\\"\\\"\\n        data = self.search_papers()\\n        return DataFrame(data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/arxiv/src/lfx_arxiv/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c6caf5d972bfb8d3a901aca32cdc781514410128af27f62f3c46fd7f3c9cdd88\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-arxiv\\\",\\n  \\\"version\\\": \\\"0.1.5\\\",\\n  \\\"name\\\": \\\"arXiv Search\\\",\\n  \\\"description\\\": \\\"arXiv search component as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"arxiv\\\",\\n      \\\"path\\\": \\\"components/arxiv\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/arxiv/tests/test_arxiv_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4d78cc3c8da633bae3928d4b85cea1cefc755c8449a08e0f7b6880e7f9bb0a7b\",\"content\":\"\\\"\\\"\\\"Unit tests for the ArXiv extension bundle (``lfx-arxiv``).\\n\\nThe component used to live at ``lfx.components.arxiv.arxiv`` and was tested\\nunder ``src/backend/tests/unit/components/search/``.  It has since been\\nextracted into a standalone bundle; these tests now travel with the bundle\\nand import the public bundle entry point.\\n\\\"\\\"\\\"\\n\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx_arxiv import ArXivComponent\\nfrom lfx_arxiv.components.arxiv.arxiv import ARXIV_REQUEST_TIMEOUT_SECONDS\\n\\n\\n@pytest.fixture\\ndef default_kwargs():\\n    return {\\n        \\\"search_query\\\": \\\"quantum computing\\\",\\n        \\\"search_type\\\": \\\"all\\\",\\n        \\\"max_results\\\": 10,\\n        \\\"_session_id\\\": \\\"test-session\\\",\\n    }\\n\\n\\ndef test_component_initialization(default_kwargs):\\n    component = ArXivComponent(**default_kwargs)\\n\\n    frontend_node = component.to_frontend_node()\\n\\n    node_data = frontend_node[\\\"data\\\"][\\\"node\\\"]\\n    assert node_data[\\\"template\\\"][\\\"search_query\\\"][\\\"value\\\"] == \\\"quantum computing\\\"\\n    assert node_data[\\\"template\\\"][\\\"search_type\\\"][\\\"value\\\"] == \\\"all\\\"\\n    assert node_data[\\\"template\\\"][\\\"max_results\\\"][\\\"value\\\"] == 10\\n\\n\\ndef test_build_query_url(default_kwargs):\\n    component = ArXivComponent(**default_kwargs)\\n\\n    url = component.build_query_url()\\n\\n    assert \\\"http://export.arxiv.org/api/query?\\\" in url\\n    assert \\\"search_query=quantum%20computing\\\" in url\\n    assert \\\"max_results=10\\\" in url\\n\\n\\ndef test_parse_atom_response(default_kwargs):\\n    component = ArXivComponent(**default_kwargs)\\n    sample_xml = \\\"\\\"\\\"<feed xmlns=\\\"http://www.w3.org/2005/Atom\\\"\\n              xmlns:arxiv=\\\"http://arxiv.org/schemas/atom\\\">\\n            <entry>\\n                <id>http://arxiv.org/abs/quant-ph/0000001</id>\\n                <title>Test Paper</title>\\n                <summary>Test summary</summary>\\n                <published>2023-01-01</published>\\n                <updated>2023-01-01</updated>\\n                <author><name>Test Author</name></author>\\n                <link rel=\\\"alternate\\\" href=\\\"http://arxiv.org/abs/quant-ph/0000001\\\"/>\\n                <link rel=\\\"related\\\" href=\\\"http://arxiv.org/pdf/quant-ph/0000001\\\"/>\\n                <category term=\\\"quant-ph\\\" scheme=\\\"http://arxiv.org/schemas/atom\\\"/>\\n                <arxiv:comment>Test comment</arxiv:comment>\\n                <arxiv:journal_ref>Test Journal</arxiv:journal_ref>\\n                <arxiv:primary_category term=\\\"quant-ph\\\"/>\\n            </entry>\\n        </feed>\\\"\\\"\\\"\\n\\n    papers = component.parse_atom_response(sample_xml)\\n\\n    assert len(papers) == 1\\n    paper = papers[0]\\n    assert paper[\\\"title\\\"] == \\\"Test Paper\\\"\\n    assert paper[\\\"summary\\\"] == \\\"Test summary\\\"\\n    assert paper[\\\"authors\\\"] == [\\\"Test Author\\\"]\\n    assert paper[\\\"arxiv_url\\\"] == \\\"http://arxiv.org/abs/quant-ph/0000001\\\"\\n    assert paper[\\\"pdf_url\\\"] == \\\"http://arxiv.org/pdf/quant-ph/0000001\\\"\\n    assert paper[\\\"comment\\\"] == \\\"Test comment\\\"\\n    assert paper[\\\"journal_ref\\\"] == \\\"Test Journal\\\"\\n    assert paper[\\\"primary_category\\\"] == \\\"quant-ph\\\"\\n\\n\\n@patch(\\\"urllib.request.build_opener\\\")\\ndef test_invalid_url_handling(mock_build_opener, default_kwargs):\\n    component = ArXivComponent(**default_kwargs)\\n    mock_build_opener.return_value.open.side_effect = ValueError(\\\"Invalid URL\\\")\\n\\n    results = component.search_papers()\\n\\n    assert len(results) == 1\\n    assert hasattr(results[0], \\\"error\\\")\\n    assert \\\"Invalid URL\\\" in results[0].error\\n\\n\\n@patch(\\\"urllib.request.build_opener\\\")\\ndef test_request_uses_bounded_timeout(mock_build_opener, default_kwargs):\\n    component = ArXivComponent(**default_kwargs)\\n    mock_build_opener.return_value.open.side_effect = TimeoutError(\\\"timed out\\\")\\n\\n    results = component.search_papers()\\n\\n    mock_build_opener.return_value.open.assert_called_once()\\n    assert mock_build_opener.return_value.open.call_args.kwargs[\\\"timeout\\\"] == ARXIV_REQUEST_TIMEOUT_SECONDS\\n    assert len(results) == 1\\n    assert hasattr(results[0], \\\"error\\\")\\n    assert \\\"timed out\\\" in results[0].error\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/azure/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7e339fb240f9b3de5613ab5398fe87bbb81f0f82e4714b1d2ed270a7075921dd\",\"content\":\"# lfx-azure\\n\\nAzure OpenAI components and Azure AI Foundry runtime support as a standalone\\nLangflow Extension Bundle.\\n\\n## Install\\n\\n```bash\\npip install lfx-azure\\n```\\n\\n`pip install langflow` includes this bundle because Azure AI Foundry is a\\nsupported model provider. The bundle is registered automatically through the\\n`langflow.extensions` entry point and appears under the `azure` group with\\ncanonical component IDs such as\\n`ext:azure:AzureChatOpenAIComponent@official`.\\n\\n## Develop\\n\\n```bash\\nuv sync\\nuv run pytest src/bundles/azure/tests -q\\nuv run lfx extension validate src/bundles/azure/src/lfx_azure\\n```\\n\\nThe bundle graduated from the manifest-less `lfx-bundles[azure]` provider in\\nLangflow 1.12. Its bundle and class names are unchanged, so existing saved\\nflows retain their canonical IDs.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/azure/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9b9e43848ab06f3a8d936b2552f58438fc04d0f12fd18a0511ada45fce27e678\",\"content\":\"[project]\\nname = \\\"lfx-azure\\\"\\nversion = \\\"0.1.0\\\"\\ndescription = \\\"Azure model components as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"azure\\\", \\\"azure-ai-foundry\\\", \\\"azure-openai\\\"]\\n\\n# Runtime deps cover both the dedicated Azure OpenAI components and the\\n# unified Azure AI Foundry provider exposed by Langflow's Language Model\\n# component. Keeping them here makes the default Langflow install complete\\n# without restoring the opt-in lfx-bundles metapackage.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"langchain-openai>=1.1.6\\\",\\n    \\\"langchain-azure-ai>=1.1.0,<2.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-azure = \\\"lfx_azure\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\npackages = [\\\"src/lfx_azure\\\"]\\ninclude = [\\n    \\\"src/lfx_azure/extension.json\\\",\\n    \\\"src/lfx_azure/components/**/*.py\\\",\\n]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_azure\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/azure/src/lfx_azure/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bddd0c443b5427ca9931d54e35448fbc250a103b743c93313f8719cb54ca1fcb\",\"content\":\"\\\"\\\"\\\"Azure model components for Langflow.\\\"\\\"\\\"\\n\\nfrom lfx_azure.components.azure import AzureChatOpenAIComponent, AzureOpenAIEmbeddingsComponent\\n\\n__all__ = [\\n    \\\"AzureChatOpenAIComponent\\\",\\n    \\\"AzureOpenAIEmbeddingsComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/azure/src/lfx_azure/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"624aa7a37cd5f16fbd1f987c45464467a7de85264ac7cd3a7069de32c503b1a3\",\"content\":\"\\\"\\\"\\\"Component packages shipped by lfx-azure.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/azure/src/lfx_azure/components/azure/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e28871191196570bba34b9ddece34246c68772a1232cda2777e8a67d0c4975da\",\"content\":\"\\\"\\\"\\\"Lazy component exports for the Azure bundle.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .azure_openai import AzureChatOpenAIComponent\\n    from .azure_openai_embeddings import AzureOpenAIEmbeddingsComponent\\n\\n_dynamic_imports = {\\n    \\\"AzureChatOpenAIComponent\\\": \\\"azure_openai\\\",\\n    \\\"AzureOpenAIEmbeddingsComponent\\\": \\\"azure_openai_embeddings\\\",\\n}\\n\\n__all__ = [\\n    \\\"AzureChatOpenAIComponent\\\",\\n    \\\"AzureOpenAIEmbeddingsComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import azure components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/azure/src/lfx_azure/components/azure/azure_openai.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"914ca845b4cba3f80ed3f36de775f76d25f66086f5bd9499a74f1477cb5b33e3\",\"content\":\"\\\"\\\"\\\"Azure OpenAI chat model component.\\\"\\\"\\\"\\n\\nfrom langchain_openai import AzureChatOpenAI\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.inputs.inputs import MessageTextInput\\nfrom lfx.io import DropdownInput, IntInput, SecretStrInput, SliderInput\\n\\n\\nclass AzureChatOpenAIComponent(LCModelComponent):\\n    model_provider_id = \\\"azure-openai\\\"\\n    display_name: str = \\\"Azure OpenAI\\\"\\n    description: str = \\\"Generate text using Azure OpenAI LLMs.\\\"\\n    documentation: str = \\\"https://python.langchain.com/docs/integrations/llms/azure_openai\\\"\\n    beta = False\\n    icon = \\\"Azure\\\"\\n    name = \\\"AzureOpenAIModel\\\"\\n\\n    AZURE_OPENAI_API_VERSIONS = [\\n        \\\"2024-06-01\\\",\\n        \\\"2024-07-01-preview\\\",\\n        \\\"2024-08-01-preview\\\",\\n        \\\"2024-09-01-preview\\\",\\n        \\\"2024-10-01-preview\\\",\\n        \\\"2023-05-15\\\",\\n        \\\"2023-12-01-preview\\\",\\n        \\\"2024-02-15-preview\\\",\\n        \\\"2024-03-01-preview\\\",\\n        \\\"2024-12-01-preview\\\",\\n        \\\"2025-01-01-preview\\\",\\n        \\\"2025-02-01-preview\\\",\\n    ]\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        MessageTextInput(\\n            name=\\\"azure_endpoint\\\",\\n            display_name=\\\"Azure Endpoint\\\",\\n            info=\\\"Your Azure endpoint, including the resource. Example: `https://example-resource.azure.openai.com/`\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(name=\\\"azure_deployment\\\", display_name=\\\"Deployment Name\\\", required=True),\\n        SecretStrInput(name=\\\"api_key\\\", display_name=\\\"Azure Chat OpenAI API Key\\\", required=True),\\n        DropdownInput(\\n            name=\\\"api_version\\\",\\n            display_name=\\\"API Version\\\",\\n            options=sorted(AZURE_OPENAI_API_VERSIONS, reverse=True),\\n            value=next(\\n                (\\n                    version\\n                    for version in sorted(AZURE_OPENAI_API_VERSIONS, reverse=True)\\n                    if not version.endswith(\\\"-preview\\\")\\n                ),\\n                AZURE_OPENAI_API_VERSIONS[0],\\n            ),\\n        ),\\n        SliderInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=1.0,\\n            range_spec=RangeSpec(min=0, max=2, step=0.01),\\n            info=\\\"Controls randomness. Lower values are more deterministic, higher values are more creative.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Tokens\\\",\\n            advanced=True,\\n            info=\\\"The maximum number of tokens to generate. Set to 0 for unlimited tokens.\\\",\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        azure_endpoint = self.azure_endpoint\\n        azure_deployment = self.azure_deployment\\n        api_version = self.api_version\\n        api_key = self.api_key\\n        temperature = self.temperature\\n        max_tokens = self.max_tokens\\n        stream = self.stream\\n\\n        try:\\n            output = AzureChatOpenAI(\\n                azure_endpoint=azure_endpoint,\\n                azure_deployment=azure_deployment,\\n                api_version=api_version,\\n                api_key=api_key,\\n                temperature=temperature,\\n                max_tokens=max_tokens or None,\\n                streaming=stream,\\n            )\\n        except Exception as e:\\n            msg = f\\\"Could not connect to AzureOpenAI API: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        return output\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/azure/src/lfx_azure/components/azure/azure_openai_embeddings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"30cb49642d17deee0eeb1d18a323c0c67546ed03cf4c127c742e1cc0adac0106\",\"content\":\"\\\"\\\"\\\"Azure OpenAI embeddings component.\\\"\\\"\\\"\\n\\nfrom langchain_openai import AzureOpenAIEmbeddings\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.base.models.openai_constants import OPENAI_EMBEDDING_MODEL_NAMES\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.io import DropdownInput, IntInput, MessageTextInput, Output, SecretStrInput\\n\\n\\nclass AzureOpenAIEmbeddingsComponent(LCModelComponent):\\n    model_provider_id = \\\"azure-openai\\\"\\n    display_name: str = \\\"Azure OpenAI Embeddings\\\"\\n    description: str = \\\"Generate embeddings using Azure OpenAI models.\\\"\\n    documentation: str = \\\"https://python.langchain.com/docs/integrations/text_embedding/azureopenai\\\"\\n    icon = \\\"Azure\\\"\\n    name = \\\"AzureOpenAIEmbeddings\\\"\\n\\n    API_VERSION_OPTIONS = [\\n        \\\"2022-12-01\\\",\\n        \\\"2023-03-15-preview\\\",\\n        \\\"2023-05-15\\\",\\n        \\\"2023-06-01-preview\\\",\\n        \\\"2023-07-01-preview\\\",\\n        \\\"2023-08-01-preview\\\",\\n    ]\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"model\\\",\\n            display_name=\\\"Model\\\",\\n            advanced=False,\\n            options=OPENAI_EMBEDDING_MODEL_NAMES,\\n            value=OPENAI_EMBEDDING_MODEL_NAMES[0],\\n        ),\\n        MessageTextInput(\\n            name=\\\"azure_endpoint\\\",\\n            display_name=\\\"Azure Endpoint\\\",\\n            required=True,\\n            info=\\\"Your Azure endpoint, including the resource. Example: `https://example-resource.azure.openai.com/`\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"azure_deployment\\\",\\n            display_name=\\\"Deployment Name\\\",\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"api_version\\\",\\n            display_name=\\\"API Version\\\",\\n            options=API_VERSION_OPTIONS,\\n            value=API_VERSION_OPTIONS[-1],\\n            advanced=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Azure OpenAI API Key\\\",\\n            required=True,\\n        ),\\n        IntInput(\\n            name=\\\"dimensions\\\",\\n            display_name=\\\"Dimensions\\\",\\n            info=\\\"The number of dimensions the resulting output embeddings should have. \\\"\\n            \\\"Only supported by certain models.\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Embeddings\\\", name=\\\"embeddings\\\", method=\\\"build_embeddings\\\"),\\n    ]\\n\\n    def build_embeddings(self) -> Embeddings:\\n        try:\\n            embeddings = AzureOpenAIEmbeddings(\\n                model=self.model,\\n                azure_endpoint=self.azure_endpoint,\\n                azure_deployment=self.azure_deployment,\\n                api_version=self.api_version,\\n                api_key=self.api_key,\\n                dimensions=self.dimensions or None,\\n            )\\n        except Exception as e:\\n            msg = f\\\"Could not connect to AzureOpenAIEmbeddings API: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        return embeddings\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/azure/src/lfx_azure/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a6bc0572219b4d66bea5140eb837eeb6ee783f8bdeb0f6d24121e7e992671c06\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-azure\\\",\\n  \\\"version\\\": \\\"0.1.0\\\",\\n  \\\"name\\\": \\\"Azure\\\",\\n  \\\"description\\\": \\\"Azure model components as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\n      \\\"1\\\"\\n    ]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"azure\\\",\\n      \\\"path\\\": \\\"components/azure\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/azure/tests/test_azure_bundle.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"202a9fb25c4a326d0cfed2de1641025707c52f29ba4caf1f5de288dace629866\",\"content\":\"from langchain_azure_ai.chat_models import AzureAIOpenAIApiChatModel\\nfrom lfx_azure import AzureChatOpenAIComponent, AzureOpenAIEmbeddingsComponent\\n\\n\\ndef test_azure_bundle_exports_components_and_foundry_runtime() -> None:\\n    assert AzureChatOpenAIComponent.name == \\\"AzureOpenAIModel\\\"\\n    assert AzureOpenAIEmbeddingsComponent.name == \\\"AzureOpenAIEmbeddings\\\"\\n    assert AzureAIOpenAIApiChatModel.__name__ == \\\"AzureAIOpenAIApiChatModel\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"123a3652cf0fb22ca3038f67973d45dc1281256d8277b1b0743a8dabe1995a9c\",\"content\":\"# lfx-cohere\\n\\nCohere component(s) as a standalone Langflow Extension Bundle.\\n\\n## Install\\n\\n```bash\\npip install lfx-cohere\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the bundle's\\ncomponents will appear in the palette under the `cohere` group with\\nthe namespaced IDs `ext:cohere:<Class>@official`.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/cohere\\npip install -e .\\nlfx extension validate src/lfx_cohere\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name(s) or the old import paths\\nunder `lfx.components.cohere.*` are rewritten to the new namespaced\\nIDs by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8a6f7177978da3191ff24cee8d5dcab6fb851f0e1b5f37949fec40198af00d44\",\"content\":\"[project]\\nname = \\\"lfx-cohere\\\"\\nversion = \\\"0.1.4\\\"\\ndescription = \\\"Cohere component(s) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"cohere\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus any third-party imports\\n# the bundle's components rely on.  REVIEW THIS LIST -- the script ports\\n# only ``lfx``; add any other deps the moved component(s) import.\\n# lfx is floored at the current major.minor line and capped below the next\\n# lfx major (e.g. \\\"lfx>=1.11.0,<2.0.0\\\"); the floor is read from\\n# src/lfx/pyproject.toml at port time and re-synced on ``make patch`` via\\n# scripts/ci/sync_bundle_lfx_pin.py.  Fine-grained BUNDLE_API compatibility\\n# is enforced via extension.json's lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"langchain-cohere~=0.6.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-cohere = \\\"lfx_cohere\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_cohere package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_cohere\\\"]\\ninclude = [\\n    \\\"src/lfx_cohere/extension.json\\\",\\n    \\\"src/lfx_cohere/components/**/*.py\\\",\\n]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_cohere\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/src/lfx_cohere/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"31cce602ec75b5290d0f28f917c93fc0d6995fd77401653668f122cf3fa9c472\",\"content\":\"\\\"\\\"\\\"lfx-cohere: Cohere bundle.\\n\\nDistribution unit ``lfx-cohere``.  At runtime Langflow's loader\\ndiscovers ``extension.json`` shipped alongside this ``__init__.py`` and\\nregisters the bundle's components under the namespaced IDs\\n``ext:cohere:<Class>@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_cohere.components.cohere.cohere_embeddings import CohereEmbeddingsComponent\\nfrom lfx_cohere.components.cohere.cohere_models import CohereComponent\\nfrom lfx_cohere.components.cohere.cohere_rerank import CohereRerankComponent\\n\\n__all__ = [\\n    \\\"CohereComponent\\\",\\n    \\\"CohereEmbeddingsComponent\\\",\\n    \\\"CohereRerankComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/src/lfx_cohere/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/src/lfx_cohere/components/cohere/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"721b3c674278885c35fd81ae6a6817a9adca9af94b64bd590588861d9de857e0\",\"content\":\"\\\"\\\"\\\"Lazy component re-exports for the ``cohere`` bundle.\\n\\nMirrors the pre-extraction layout of ``lfx.components.cohere`` so saved\\nflows that referenced the module-level class\\n(e.g. ``lfx.components.cohere.<Class>``) keep resolving via the\\nmigration table after rewrite to\\n``lfx_cohere.components.cohere.<Class>``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .cohere_embeddings import CohereEmbeddingsComponent\\n    from .cohere_models import CohereComponent\\n    from .cohere_rerank import CohereRerankComponent\\n\\n_dynamic_imports = {\\n    \\\"CohereComponent\\\": \\\"cohere_models\\\",\\n    \\\"CohereEmbeddingsComponent\\\": \\\"cohere_embeddings\\\",\\n    \\\"CohereRerankComponent\\\": \\\"cohere_rerank\\\",\\n}\\n\\n__all__ = [\\n    \\\"CohereComponent\\\",\\n    \\\"CohereEmbeddingsComponent\\\",\\n    \\\"CohereRerankComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module {__name__!r} has no attribute {attr_name!r}\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import {attr_name!r} from {__name__!r}: {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/src/lfx_cohere/components/cohere/cohere_embeddings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cf5fedd9ea47fd7bb376cc16f7f8de330d2106ab0731e53609d3639f7c9c35a8\",\"content\":\"from typing import Any\\n\\nimport cohere\\nfrom langchain_cohere import CohereEmbeddings\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.io import DropdownInput, FloatInput, IntInput, MessageTextInput, Output, SecretStrInput\\n\\nHTTP_STATUS_OK = 200\\n\\n\\nclass CohereEmbeddingsComponent(LCModelComponent):\\n    display_name = \\\"Cohere Embeddings\\\"\\n    description = \\\"Generate embeddings using Cohere models.\\\"\\n    icon = \\\"Cohere\\\"\\n    name = \\\"CohereEmbeddings\\\"\\n\\n    inputs = [\\n        SecretStrInput(name=\\\"api_key\\\", display_name=\\\"Cohere API Key\\\", required=True, real_time_refresh=True),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model\\\",\\n            advanced=False,\\n            options=[\\n                \\\"embed-english-v2.0\\\",\\n                \\\"embed-multilingual-v2.0\\\",\\n                \\\"embed-english-light-v2.0\\\",\\n                \\\"embed-multilingual-light-v2.0\\\",\\n            ],\\n            value=\\\"embed-english-v2.0\\\",\\n            refresh_button=True,\\n            combobox=True,\\n        ),\\n        MessageTextInput(name=\\\"truncate\\\", display_name=\\\"Truncate\\\", advanced=True),\\n        IntInput(name=\\\"max_retries\\\", display_name=\\\"Max Retries\\\", value=3, advanced=True),\\n        MessageTextInput(name=\\\"user_agent\\\", display_name=\\\"User Agent\\\", advanced=True, value=\\\"langchain\\\"),\\n        FloatInput(name=\\\"request_timeout\\\", display_name=\\\"Request Timeout\\\", advanced=True),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Embeddings\\\", name=\\\"embeddings\\\", method=\\\"build_embeddings\\\"),\\n    ]\\n\\n    def build_embeddings(self) -> Embeddings:\\n        data = None\\n        try:\\n            data = CohereEmbeddings(\\n                cohere_api_key=self.api_key,\\n                model=self.model_name,\\n                truncate=self.truncate,\\n                max_retries=self.max_retries,\\n                user_agent=self.user_agent,\\n                request_timeout=self.request_timeout or None,\\n            )\\n        except Exception as e:\\n            msg = (\\n                \\\"Unable to create Cohere Embeddings. \\\",\\n                \\\"Please verify the API key and model parameters, and try again.\\\",\\n            )\\n            raise ValueError(msg) from e\\n        # added status if not the return data would be serialised to create the status\\n        return data\\n\\n    def get_model(self):\\n        try:\\n            co = cohere.ClientV2(self.api_key)\\n            response = co.models.list(endpoint=\\\"embed\\\")\\n            models = response.models\\n            return [model.name for model in models]\\n        except Exception as e:\\n            msg = f\\\"Failed to fetch Cohere models. Error: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n    async def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None):\\n        if field_name in {\\\"model_name\\\", \\\"api_key\\\"}:\\n            if build_config.get(\\\"api_key\\\", {}).get(\\\"value\\\", None):\\n                build_config[\\\"model_name\\\"][\\\"options\\\"] = self.get_model()\\n        else:\\n            build_config[\\\"model_name\\\"][\\\"options\\\"] = field_value\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/src/lfx_cohere/components/cohere/cohere_models.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1c31df33982127dc354149f8af018d57448e6b28007d7d2256597b5d14b95f08\",\"content\":\"from langchain_cohere import ChatCohere\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.io import SecretStrInput, SliderInput\\nfrom pydantic.v1 import SecretStr\\n\\n\\nclass CohereComponent(LCModelComponent):\\n    display_name = \\\"Cohere Language Models\\\"\\n    description = \\\"Generate text using Cohere LLMs.\\\"\\n    documentation = \\\"https://python.langchain.com/docs/integrations/llms/cohere/\\\"\\n    icon = \\\"Cohere\\\"\\n    name = \\\"CohereModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        SecretStrInput(\\n            name=\\\"cohere_api_key\\\",\\n            display_name=\\\"Cohere API Key\\\",\\n            info=\\\"The Cohere API Key to use for the Cohere model.\\\",\\n            advanced=False,\\n            value=\\\"COHERE_API_KEY\\\",\\n            required=True,\\n        ),\\n        SliderInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.75,\\n            range_spec=RangeSpec(min=0, max=2, step=0.01),\\n            info=\\\"Controls randomness. Lower values are more deterministic, higher values are more creative.\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        cohere_api_key = self.cohere_api_key\\n        temperature = self.temperature\\n\\n        api_key = SecretStr(cohere_api_key).get_secret_value() if cohere_api_key else None\\n\\n        return ChatCohere(\\n            temperature=temperature or 0.75,\\n            cohere_api_key=api_key,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/src/lfx_cohere/components/cohere/cohere_rerank.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a94a0d11eeac8d49ef9131e40b3c1ac81b8b0e81fde7b0411206fe42efe4f589\",\"content\":\"from lfx.base.compressors.model import LCCompressorComponent\\nfrom lfx.field_typing import BaseDocumentCompressor\\nfrom lfx.inputs.inputs import SecretStrInput\\nfrom lfx.io import DropdownInput\\nfrom lfx.template.field.base import Output\\n\\n\\nclass CohereRerankComponent(LCCompressorComponent):\\n    display_name = \\\"Cohere Rerank\\\"\\n    description = \\\"Rerank documents using the Cohere API.\\\"\\n    name = \\\"CohereRerank\\\"\\n    icon = \\\"Cohere\\\"\\n\\n    inputs = [\\n        *LCCompressorComponent.inputs,\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Cohere API Key\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"model\\\",\\n            display_name=\\\"Model\\\",\\n            options=[\\n                \\\"rerank-english-v3.0\\\",\\n                \\\"rerank-multilingual-v3.0\\\",\\n                \\\"rerank-english-v2.0\\\",\\n                \\\"rerank-multilingual-v2.0\\\",\\n            ],\\n            value=\\\"rerank-english-v3.0\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"Reranked Documents\\\",\\n            name=\\\"reranked_documents\\\",\\n            method=\\\"compress_documents\\\",\\n        ),\\n    ]\\n\\n    def build_compressor(self) -> BaseDocumentCompressor:  # type: ignore[type-var]\\n        try:\\n            from langchain_cohere import CohereRerank\\n        except ImportError as e:\\n            msg = \\\"Please install langchain-cohere to use the Cohere model.\\\"\\n            raise ImportError(msg) from e\\n        return CohereRerank(\\n            cohere_api_key=self.api_key,\\n            model=self.model,\\n            top_n=self.top_n,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/src/lfx_cohere/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3b3b35e6fb4c06b02c8a1155e7dba875a89dbe9fce932e3fc7086d2350c9ce3e\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-cohere\\\",\\n  \\\"version\\\": \\\"0.1.4\\\",\\n  \\\"name\\\": \\\"Cohere\\\",\\n  \\\"description\\\": \\\"Cohere component(s) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"cohere\\\",\\n      \\\"path\\\": \\\"components/cohere\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/cohere/tests/test_cohere_community_migration.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"68815351e51aa4ac3dfdca5e1a42d5219baba9340a03b883c557a26de3e9e2ae\",\"content\":\"\\\"\\\"\\\"Exercise the Cohere component surface after removing its indirect Community edge.\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\nfrom unittest.mock import MagicMock, patch\\n\\nfrom langchain_core.documents import Document\\nfrom lfx_cohere.components.cohere.cohere_embeddings import CohereEmbeddingsComponent\\nfrom lfx_cohere.components.cohere.cohere_models import CohereComponent\\nfrom lfx_cohere.components.cohere.cohere_rerank import CohereRerankComponent\\n\\nTEST_KEY = \\\"test-key\\\"\\n\\n\\ndef test_chat_constructor_preserves_temperature_and_credentials():\\n    response = SimpleNamespace(models=[SimpleNamespace(name=\\\"command-r-plus\\\")])\\n    with patch(\\\"cohere.models.client.ModelsClient.list\\\", return_value=response) as discover:\\n        model = CohereComponent().set(cohere_api_key=TEST_KEY, temperature=0.2).build_model()\\n    discover.assert_called_once_with(default_only=True, endpoint=\\\"chat\\\")\\n    assert model.model == \\\"command-r-plus\\\"\\n    assert model.temperature == 0.2\\n    assert model.cohere_api_key.get_secret_value() == TEST_KEY\\n\\n\\ndef test_embeddings_preserve_request_and_result_contract():\\n    embeddings = CohereEmbeddingsComponent().set(api_key=TEST_KEY, model_name=\\\"embed-english-v3.0\\\").build_embeddings()\\n    response = MagicMock()\\n    response.dict.return_value = {\\\"embeddings\\\": {\\\"float\\\": [[0.1, 0.2]]}}\\n    with patch.object(embeddings.client, \\\"embed\\\", return_value=response) as embed:\\n        assert embeddings.embed_query(\\\"question\\\") == [0.1, 0.2]\\n    assert embed.call_args.kwargs[\\\"texts\\\"] == [\\\"question\\\"]\\n    assert embed.call_args.kwargs[\\\"model\\\"] == \\\"embed-english-v3.0\\\"\\n    assert embed.call_args.kwargs[\\\"input_type\\\"] == \\\"search_query\\\"\\n\\n\\ndef test_reranker_preserves_order_and_metadata():\\n    compressor = CohereRerankComponent().set(api_key=TEST_KEY, top_n=1).build_compressor()\\n    documents = [Document(page_content=\\\"first\\\"), Document(page_content=\\\"second\\\", metadata={\\\"source\\\": \\\"saved\\\"})]\\n    response = SimpleNamespace(results=[SimpleNamespace(index=1, relevance_score=0.9)])\\n    with patch.object(compressor.client, \\\"rerank\\\", return_value=response) as rerank:\\n        result = compressor.compress_documents(documents, \\\"question\\\")\\n    assert rerank.call_args.kwargs[\\\"top_n\\\"] == 1\\n    assert result[0].page_content == \\\"second\\\"\\n    assert result[0].metadata == {\\\"source\\\": \\\"saved\\\", \\\"relevance_score\\\": 0.9}\\n    assert documents[1].metadata == {\\\"source\\\": \\\"saved\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f484e6eaa59845b06067b61b93e41027926ba4e32de56ca8529d1c49cbe0a790\",\"content\":\"# lfx-confluent\\n\\n[IBM Confluent](https://www.ibm.com/products/confluent) \u2014 the data-in-motion\\nhalf of IBM's streaming lakehouse \u2014 as a standalone Langflow Extension\\nBundle. Everything talks to Confluent over open protocols only (Kafka wire\\nprotocol, the Tableflow Iceberg REST catalog, and MCP over Streamable HTTP),\\nso the same components work against Confluent Cloud, Confluent Platform, and\\nWarpStream wherever the corresponding surface is exposed.\\n\\n## What it ships\\n\\nFour components, registered under the `confluent` bundle group:\\n\\n- **Confluent Real-Time Context Engine** (`ConfluentContextEngineComponent`,\\n  canonical ID `ext:confluent:ConfluentContextEngineComponent@official`) \u2014 a\\n  preset MCP toolset for Confluent's Real-Time Context Engine. Templates the\\n  regional MCP endpoint from your organization / environment / cluster IDs,\\n  authenticates with a Confluent Cloud API key, and exposes `list_topics`,\\n  `get_metadata`, and `query_data` to an **Agent** (Tool Mode) or runs one\\n  tool directly (Response output).\\n- **Confluent Kafka Producer** (`ConfluentKafkaProducerComponent`) \u2014 publish\\n  a Message, a Data object, or every row of a DataFrame to a topic and return\\n  the delivery report.\\n- **Confluent Kafka Consumer** (`ConfluentKafkaConsumerComponent`) \u2014 read a\\n  bounded batch of records (message limit + timeout) into a DataFrame; JSON,\\n  string, Avro, and JSON-Schema (Schema Registry) values.\\n- **Confluent Tableflow Reader** (`ConfluentTableflowReaderComponent`) \u2014 read\\n  a Kafka topic that Tableflow has materialized as an Apache Iceberg table\\n  through the Tableflow Iceberg REST catalog (`pyiceberg`, no JVM), with a\\n  row filter, projection, and row limit; or list the tables in a cluster.\\n\\nBuilt on [`confluent-kafka`](https://pypi.org/project/confluent-kafka/) and\\n[`pyiceberg`](https://pypi.org/project/pyiceberg/); the MCP component reuses\\nLangflow's own MCP client engine.\\n\\n## Install\\n\\n```bash\\npip install lfx-confluent\\n```\\n\\n`pip install \\\"langflow[bundles]\\\"` also includes it.\\n\\n## Develop\\n\\nThe bundle is a uv workspace member of the Langflow monorepo:\\n\\n```bash\\nuv sync\\nuv run pytest src/bundles/confluent/tests -q\\nuv run lfx extension validate src/bundles/confluent/src/lfx_confluent\\n```\\n\\nTo iterate on the components with a live palette:\\n\\n```bash\\nuv run lfx extension dev src/bundles/confluent\\n```\\n\\nLive smoke tests (marked `api_key_required`) need a Confluent Cloud\\nenvironment; see the test module docstrings for the environment variables\\nthey read.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3d03ee37686d96d19e179bd63334cabe37669ce27be286b801a3a1e7cf700038\",\"content\":\"[project]\\nname = \\\"lfx-confluent\\\"\\nversion = \\\"0.1.0\\\"\\ndescription = \\\"IBM Confluent components (Kafka producer/consumer";
